-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('49d2c61a-e8d8-544d-837b-99dab77d1f95'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Quel est l’ordre correct des niveaux d’organisation, du plus grand au plus petit ?', 'mcq', '["Organe, appareil, tissu, cellule","Appareil, organe, tissu, cellule","Tissu, organe, cellule, appareil","Appareil, tissu, organe, molécule"]'::jsonb, 1, 'L’appareil regroupe des organes, formés de tissus, eux-mêmes formés de cellules.', 1),
    ('672ccf9f-44a5-55ce-ad18-e433a3fd50d4'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Une mitochondrie appartient au niveau :', 'mcq', '["De l’organe","Du tissu","De l’ultrastructure cellulaire","De l’appareil"]'::jsonb, 2, 'C’est un organite, visible en détail au microscope électronique.', 2),
    ('19990012-25a3-5aa4-8383-6f8e7e8b6e20'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Quelle coupe sépare le corps en une partie droite et une partie gauche ?', 'mcq', '["Frontale","Transversale","Sagittale","Horizontale"]'::jsonb, 2, 'Le plan sagittal est vertical, d’avant en arrière.', 3),
    ('d237b862-c3c0-524d-9b0c-1c265b906068'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Quelle coupe sépare le haut du bas du corps ?', 'mcq', '["Sagittale","Frontale","Transversale","Coronale"]'::jsonb, 2, 'La coupe transversale (ou axiale) est horizontale, comme celles du scanner.', 4),
    ('a84295ab-5171-5e49-b31a-4089e252b4ad'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Dans quelle cavité se trouve la moelle épinière ?', 'mcq', '["Crânienne","Rachidienne","Thoracique","Abdominale"]'::jsonb, 1, 'Elle est logée dans le canal vertébral de la colonne.', 5),
    ('78995e17-5fb5-50ba-82cd-9e4f4b964747'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Quel muscle sépare les cavités thoracique et abdominale ?', 'mcq', '["Le psoas","Le diaphragme","Le grand pectoral","Le muscle cardiaque"]'::jsonb, 1, 'C’est aussi le principal muscle inspiratoire.', 6),
    ('493b6db4-0e40-5c13-afc1-ed1bdb8636bd'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Quelle technique permet d’observer une molécule du sang comme le glucose ?', 'mcq', '["La radiographie","L’analyse biochimique","La microscopie optique","L’échographie"]'::jsonb, 1, 'Le bilan sanguin dose les molécules : glycémie, cholestérol, urée.', 7),
    ('e06984f7-67fa-591b-ba87-5a8ca1bc94c6'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Que signifie la racine « hist(o) » ?', 'mcq', '["Cellule","Tissu","Os","Sang"]'::jsonb, 1, 'L’histologie est l’étude des tissus ; la cytologie, celle des cellules.', 8),
    ('fced2822-814a-5837-8d0b-ddc2e2db5520'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Sur un cliché de face, la droite du patient apparaît à gauche de l’image.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On regarde le patient face à face, comme s’il était devant nous.', 9),
    ('a1fdeeea-74c1-5d31-82f7-751d7c7d1802'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Dans quelle cavité se situent la vessie et le rectum ?', 'mcq', '["Thoracique","Abdominale","Pelvienne","Crânienne"]'::jsonb, 2, 'La cavité pelvienne est la partie basse, protégée par le bassin.', 10),
    ('f6bebfcb-5021-56e8-a4ef-adb8f9e183a2'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Quel appareil distribue le dioxygène et les nutriments à toutes les cellules ?', 'mcq', '["L’appareil digestif","L’appareil respiratoire","L’appareil cardio-vasculaire","L’appareil locomoteur"]'::jsonb, 2, 'Le sang, mis en mouvement par le cœur, relie tous les autres appareils.', 11),
    ('97be73cc-56ed-5a08-baa9-76edf0d9af4f'::uuid, '673d2470-8675-5a6d-b6ac-f8acb800ebc6'::uuid, 'Les appareils de l’organisme fonctionnent indépendamment les uns des autres.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils échangent matière et information : c’est le fonctionnement intégré de l’organisme.', 12),
    ('8ff9bd1d-e8c3-52ee-8f42-041b2addd295'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Qu’est-ce qui caractérise un tissu épithélial ?', 'mcq', '["Des cellules dispersées dans une matrice abondante","Des cellules jointives reposant sur une lame basale, sans vaisseaux","Des cellules contractiles","Une matrice liquide"]'::jsonb, 1, 'Il est nourri par diffusion à partir du tissu conjonctif sous-jacent.', 1),
    ('e2382bf7-b2a0-5b21-b146-a1eed2390cf5'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Lequel de ces tissus est un tissu conjonctif ?', 'mcq', '["L’épiderme","Le tissu adipeux","L’épithélium intestinal","Le revêtement de la bouche"]'::jsonb, 1, 'Cellules dispersées dans une matrice : c’est un conjonctif spécialisé dans la réserve.', 2),
    ('ce8693af-b8de-5d56-be12-55ed5e6cfab2'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Quel organite est le siège de la respiration cellulaire ?', 'mcq', '["Le noyau","La mitochondrie","L’appareil de Golgi","Le lysosome"]'::jsonb, 1, 'Elle y produit l’essentiel de l’ATP de la cellule.', 3),
    ('65b45543-a8ca-5634-a0c5-7327a91ec84c'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Où est stockée l’information génétique ?', 'mcq', '["Dans les ribosomes","Dans le noyau","Dans la membrane","Dans les lysosomes"]'::jsonb, 1, 'L’ADN du noyau porte les gènes.', 4),
    ('d9e29b91-9e3c-589c-b3ac-dd3f44f2eb9a'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Quel est le rôle de l’appareil de Golgi ?', 'mcq', '["Produire de l’ATP","Maturation, tri et sécrétion des protéines","Digérer les déchets","Copier l’ADN"]'::jsonb, 1, 'Il reçoit les protéines du réticulum rugueux et les expédie.', 5),
    ('61077612-56ae-55bc-8f7c-2082fdcac4df'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Un épithélium formé de plusieurs couches de cellules est dit :', 'mcq', '["Simple","Stratifié","Glandulaire","Conjonctif"]'::jsonb, 1, 'L’épiderme, pavimenteux stratifié, résiste aux frottements.', 6),
    ('26f8874a-06aa-5d27-948a-4e69e5eb9a33'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Le sang est considéré comme un tissu conjonctif à matrice liquide.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ses cellules sont dispersées dans le plasma, qui tient lieu de matrice.', 7),
    ('381de2b6-9951-5cac-affc-873879cfcfbb'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Quelle particularité de l’entérocyte favorise l’absorption ?', 'mcq', '["L’absence de noyau","Les microvillosités de son pôle apical","Sa forme en étoile","Ses nombreux lysosomes"]'::jsonb, 1, 'Elles multiplient la surface d’échange avec le contenu intestinal.', 8),
    ('d5b7875b-b017-5370-85b9-ebd570e0da56'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Quelles molécules forment la trame de la membrane plasmique ?', 'mcq', '["Des acides nucléiques","Une bicouche de phospholipides","Des glucides seuls","Du collagène"]'::jsonb, 1, 'Des protéines et du cholestérol y sont insérés.', 9),
    ('d5f458eb-a609-5afe-b49a-6533f22f1544'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Une cellule qui sécrète beaucoup de protéines est riche en :', 'mcq', '["Réticulum endoplasmique rugueux et appareil de Golgi","Gouttelettes lipidiques","Cils","Lysosomes uniquement"]'::jsonb, 0, 'Ribosomes du réticulum rugueux pour produire, Golgi pour sécréter.', 10),
    ('fae143ba-2467-5660-a186-588f284c084f'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Quelle cellule ne possède pas de noyau à maturité ?', 'mcq', '["Le neurone","L’hématie","L’entérocyte","La fibre musculaire"]'::jsonb, 1, 'Le globule rouge perd son noyau et se remplit d’hémoglobine.', 11),
    ('0a16fe91-96e9-5a8f-ad52-1e2281bcb789'::uuid, '5f1ddd16-fca8-5a16-b94a-123ba47324f2'::uuid, 'Le tissu épithélial est richement vascularisé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne contient pas de vaisseaux : c’est le conjonctif voisin qui le nourrit.', 12),
    ('f3e10d36-45e4-5105-b634-eafe50966e34'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Combien de vertèbres cervicales compte la colonne vertébrale ?', 'mcq', '["5","7","12","33"]'::jsonb, 1, 'Sept cervicales, douze thoraciques et cinq lombaires, puis le sacrum et le coccyx.', 1),
    ('ab9c9a85-46f2-5da0-9070-f4e6a8b178a5'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Quel os appartient au squelette axial ?', 'mcq', '["Le fémur","La clavicule","Le sternum","L’humérus"]'::jsonb, 2, 'Le squelette axial comprend crâne, colonne, côtes et sternum.', 2),
    ('a34a0c89-8168-59cc-a532-bbf7fb0e63d6'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Quel est le rôle du liquide synovial ?', 'mcq', '["Relier les muscles aux os","Lubrifier l’articulation et nourrir le cartilage","Produire les globules rouges","Contracter l’articulation"]'::jsonb, 1, 'Il est sécrété par la membrane synoviale.', 3),
    ('9da2bf6e-65d1-56df-a8d2-35e35dfa23d6'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Qu’est-ce qui relie un muscle à un os ?', 'mcq', '["Un ligament","Un tendon","Une capsule","Un cartilage"]'::jsonb, 1, 'Les ligaments, eux, relient les os entre eux.', 4),
    ('999438b8-7103-5302-b893-cf89711b9463'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Pourquoi l’os apparaît-il blanc sur une radiographie ?', 'mcq', '["Parce qu’il émet de la lumière","Parce qu’il absorbe fortement les rayons X","Parce qu’il réfléchit les ultrasons","Parce qu’il contient de l’eau"]'::jsonb, 1, 'Les rayons X arrêtés par l’os n’atteignent pas le détecteur.', 5),
    ('ce0571bd-14b0-56b9-ae17-788e7387763c'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Quelle technique d’imagerie n’utilise pas de rayonnement ionisant ?', 'mcq', '["La radiographie","Le scanner","L’IRM","L’angiographie"]'::jsonb, 2, 'Elle repose sur un champ magnétique et des ondes de radiofréquence.', 6),
    ('194f0bd7-e7af-542d-aed4-b30a205ceddd'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Quel avantage le scanner a-t-il sur la radiographie ?', 'mcq', '["Il n’irradie pas","Il donne des coupes sans superposition des structures","Il est moins cher","Il ne nécessite aucun appareil"]'::jsonb, 1, 'L’ordinateur reconstruit des coupes et des images en trois dimensions.', 7),
    ('a928b433-215d-5860-836b-33c16830601c'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Quel examen est le plus adapté pour explorer un ligament du genou ?', 'mcq', '["La radiographie","L’IRM","Le bilan sanguin","La spirométrie"]'::jsonb, 1, 'Les tissus mous sont mal vus par les rayons X, très bien par l’IRM.', 8),
    ('915d0ccd-2d76-5ce4-a5a6-14f2bf7e2874'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Que signifie « gonarthrose » ?', 'mcq', '["Une fracture de la hanche","Une arthrose du genou","Une inflammation d’un tendon","Une fragilité osseuse généralisée"]'::jsonb, 1, 'gon(o) = genou, arthr(o) = articulation, -ose = affection non inflammatoire.', 9),
    ('c5c61f3e-6c88-5d11-9cb1-da06915c2777'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Un porteur d’éclats métalliques peut passer une IRM sans précaution.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le champ magnétique intense peut déplacer ou chauffer un objet métallique : c’est une contre-indication.', 10),
    ('d73e939b-ab5a-5cb8-b560-1824ad574e22'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Où sont produites les cellules sanguines ?', 'mcq', '["Dans le cartilage","Dans la moelle osseuse rouge","Dans le liquide synovial","Dans les ligaments"]'::jsonb, 1, 'La moelle osseuse rouge est logée dans l’os spongieux.', 11),
    ('f1f8e62a-a4e7-5f22-846b-f8136b2c2d5a'::uuid, '522c8b92-71ea-56bc-93c6-d6e7c0c01965'::uuid, 'Quels os forment la ceinture scapulaire ?', 'mcq', '["Les os coxaux","La clavicule et la scapula","Le radius et l’ulna","Le tibia et la fibula"]'::jsonb, 1, 'Elle rattache les membres supérieurs au tronc.', 12),
    ('cfb82405-bb40-52bc-a385-d44021cab2bc'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Quels organes forment le système nerveux central ?', 'mcq', '["Les nerfs crâniens et rachidiens","L’encéphale et la moelle épinière","Les ganglions et les nerfs","Le cœur et le cerveau"]'::jsonb, 1, 'Le SNC intègre les informations et élabore les commandes.', 1),
    ('2d293e2c-58d6-5fa3-a17c-e9a66d72d77e'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Quel prolongement du neurone conduit l’influx vers les terminaisons ?', 'mcq', '["La dendrite","L’axone","Le noyau","La synapse"]'::jsonb, 1, 'Chaque neurone n’a qu’un axone ; les dendrites reçoivent les messages.', 2),
    ('086b1fc9-f385-5034-8fb5-df840927d160'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Quelle est la valeur approximative du potentiel de repos d’une fibre nerveuse ?', 'mcq', '["+ 30 mV","0 mV","− 70 mV","− 200 mV"]'::jsonb, 2, 'L’intérieur de la fibre est négatif par rapport à l’extérieur.', 3),
    ('9a5bb3e7-be44-56a6-a83c-c8d782ae0981'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Comment l’intensité d’une stimulation est-elle codée sur une fibre nerveuse ?', 'mcq', '["Par l’amplitude des potentiels d’action","Par la fréquence des potentiels d’action","Par la durée du potentiel de repos","Par la vitesse de la fibre"]'::jsonb, 1, 'Le PA d’une fibre a une amplitude constante : seule sa fréquence varie.', 4),
    ('56f56403-1d4e-55d7-8e91-cadbc04f87a8'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Que signifie la loi du « tout ou rien » ?', 'mcq', '["Une fibre répond toujours, quelle que soit la stimulation","Sous le seuil, pas de PA ; au-dessus, un PA d’amplitude constante","L’amplitude du PA augmente avec la stimulation","Le nerf ne répond qu’une fois"]'::jsonb, 1, 'Elle s’applique à une fibre isolée, pas au nerf entier.', 5),
    ('51006205-73ca-5983-9e35-974797057308'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Pourquoi la réponse d’un nerf augmente-t-elle avec l’intensité de la stimulation ?', 'mcq', '["Chaque fibre produit des PA plus grands","De plus en plus de fibres, de seuils différents, sont recrutées","La myéline s’épaissit","Le potentiel de repos diminue"]'::jsonb, 1, 'Quand toutes les fibres répondent, la réponse atteint son maximum.', 6),
    ('4a5e28cf-535d-51a9-855e-f7c599c6c17e'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Quel est le rôle de la gaine de myéline ?', 'mcq', '["Produire l’influx","Accélérer la conduction de l’influx","Nourrir le corps cellulaire","Relier deux os"]'::jsonb, 1, 'L’influx saute d’un nœud de Ranvier à l’autre : c’est la conduction saltatoire.', 7),
    ('9189586a-4ffa-5650-86b7-415cd8c1e50f'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Combien de paires de nerfs rachidiens compte l’être humain ?', 'mcq', '["12","24","31","206"]'::jsonb, 2, 'Ils naissent de la moelle épinière ; les nerfs crâniens, eux, sont 12 paires.', 8),
    ('e9f51cb4-d0d0-569d-b43f-c0e09f4c1cdb'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Pendant la dépolarisation, l’intérieur de la fibre devient momentanément positif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le potentiel passe d’environ − 70 mV à environ + 30 mV.', 9),
    ('8421e545-9810-5e54-ac32-d21a63a42df2'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Un nerf est formé :', 'mcq', '["D’un seul neurone","De nombreuses fibres nerveuses regroupées en fascicules","De cellules musculaires","De moelle épinière"]'::jsonb, 1, 'Chaque fascicule est entouré de périnèvre, le nerf entier d’épinèvre.', 10),
    ('7dbd3f1a-c1a2-5005-a2ba-e147320fe70c'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Que désigne la racine « myél(o) » ?', 'mcq', '["Le muscle","La moelle","Le cerveau","Le nerf"]'::jsonb, 1, 'La myélite est une inflammation de la moelle épinière.', 11),
    ('1b932e42-1069-5272-b6b6-ea06e5afaae5'::uuid, '1632fd63-b78f-5891-9d3b-293b95f88052'::uuid, 'Les fibres motrices apportent au SNC les informations des organes des sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les fibres sensitives ; les motrices portent les ordres vers les muscles.', 12),
    ('49ec3e3b-019a-5b30-af6a-2fb4b6c53272'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Qu’est-ce qu’un sarcomère ?', 'mcq', '["Un faisceau de fibres","L’unité contractile délimitée par deux stries Z","Une cellule nerveuse","L’enveloppe du muscle"]'::jsonb, 1, 'C’est la plus petite unité capable de se contracter.', 1),
    ('ed815394-ef3d-56bb-a044-848aeee90ff6'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Quelles protéines forment les myofilaments ?', 'mcq', '["L’hémoglobine et la myoglobine","L’actine et la myosine","Le collagène et l’élastine","L’insuline et le glucagon"]'::jsonb, 1, 'L’actine forme les filaments fins, la myosine les filaments épais.', 2),
    ('78fb6e94-ce04-59a5-b6fd-99b394042029'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Au cours de la contraction, quelle zone garde la même longueur ?', 'mcq', '["La bande I","La zone H","La bande A","Le sarcomère"]'::jsonb, 2, 'La bande A correspond à la longueur des filaments de myosine, qui ne raccourcissent pas.', 3),
    ('94a47413-c099-554d-b4b0-21f9afddb986'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Pendant la contraction, les myofilaments raccourcissent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils glissent les uns sur les autres sans changer de longueur ; c’est le sarcomère qui raccourcit.', 4),
    ('6a8b82b0-72be-5a85-9131-cccb45906ed2'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Quel neurotransmetteur agit à la jonction neuromusculaire ?', 'mcq', '["La dopamine","L’acétylcholine","L’adrénaline","La sérotonine"]'::jsonb, 1, 'Libérée par le motoneurone, elle se fixe sur les récepteurs de la fibre musculaire.', 5),
    ('28a3ab72-24c9-56a7-96d3-9d6624d1c9ba'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Quels éléments sont nécessaires au glissement des myofilaments ?', 'mcq', '["L’ATP et les ions calcium","Le glucose et l’insuline","Le dioxygène seul","Les ions chlorure"]'::jsonb, 0, 'L’ATP fournit l’énergie, le calcium autorise l’accrochage de la myosine à l’actine.', 6),
    ('724f8131-51b0-54c3-9659-a50c22eb8ee1'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Combien de noyaux possède une fibre musculaire striée squelettique ?', 'mcq', '["Aucun","Un seul","Plusieurs","Deux exactement"]'::jsonb, 2, 'C’est une cellule géante plurinucléée.', 7),
    ('b9b028bc-f03a-5f35-9dcc-d269ed7504b7'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Quelle zone du sarcomère ne contient que des filaments d’actine ?', 'mcq', '["La bande A","La bande I","La zone H","La strie M"]'::jsonb, 1, 'La bande I, claire, est traversée en son milieu par la strie Z.', 8),
    ('4ce27728-4948-5810-9b61-3150cef83430'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Quel est le rôle de l’acétylcholinestérase ?', 'mcq', '["Produire l’acétylcholine","Dégrader l’acétylcholine pour arrêter la commande","Fixer le calcium","Fabriquer de l’ATP"]'::jsonb, 1, 'Sans elle, le muscle resterait stimulé.', 9),
    ('87f7ebfd-4c2f-509d-9018-b101b2b29fe5'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Dans quel ordre se succèdent ces niveaux, du plus grand au plus petit ?', 'mcq', '["Fibre, muscle, myofibrille, sarcomère","Muscle, faisceau, fibre, myofibrille","Myofibrille, fibre, faisceau, muscle","Sarcomère, myofibrille, fibre, muscle"]'::jsonb, 1, 'Le muscle contient des faisceaux de fibres, remplies de myofibrilles.', 10),
    ('98615152-ecb3-55bb-94ea-f92d5df36672'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Que signifie « myalgie » ?', 'mcq', '["Une douleur musculaire","Une inflammation du tendon","Une paralysie","Une fracture"]'::jsonb, 0, 'my(o) = muscle, -algie = douleur.', 11),
    ('5413c218-9c0d-5ba6-b77f-dd92043407fe'::uuid, 'ce92049d-4933-5e1a-aa20-4cec42fa30de'::uuid, 'Pourquoi les fibres musculaires sont-elles riches en mitochondries ?', 'mcq', '["Pour stocker le calcium","Pour produire l’ATP nécessaire à la contraction","Pour fabriquer l’acétylcholine","Pour former les stries Z"]'::jsonb, 1, 'La contraction consomme beaucoup d’énergie.', 12),
    ('59692922-c9fd-5e36-8e33-763a9cd3380d'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Une lésion de la moelle épinière au niveau cervical provoque en général :', 'mcq', '["Une paraplégie","Une tétraplégie","Une aphasie","Aucun trouble moteur"]'::jsonb, 1, 'La lésion interrompt les voies destinées aux quatre membres.', 1),
    ('30ac7b63-5d83-5a9f-8fa1-26ffa3e78018'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Qu’est-ce qu’une paraplégie ?', 'mcq', '["La paralysie des quatre membres","La paralysie des deux membres inférieurs","La perte de la parole","La perte de la mémoire"]'::jsonb, 1, 'Elle résulte d’une lésion thoracique ou lombaire de la moelle.', 2),
    ('57093e11-2ff6-55d1-b24c-3f81e8ab21d5'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Quelle est la cause d’un AVC ischémique ?', 'mcq', '["La rupture d’une artère cérébrale","L’obstruction d’une artère cérébrale par un caillot","Une infection du cerveau","Une fracture du crâne"]'::jsonb, 1, 'C’est la forme la plus fréquente, environ 80 % des AVC.', 3),
    ('09ee51c9-f6d6-5d90-8637-c91b6dc897e5'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Une lésion de l’hémisphère cérébral gauche entraîne une paralysie :', 'mcq', '["Du côté gauche du corps","Du côté droit du corps","Des deux côtés","Des yeux seulement"]'::jsonb, 1, 'Les voies motrices se croisent : chaque hémisphère commande le côté opposé.', 4),
    ('7ad54463-1535-5f09-909d-78c2e99b4f8a'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Que désigne l’aphasie ?', 'mcq', '["Une paralysie d’un membre","Un trouble du langage","Une perte de mémoire","Un fourmillement"]'::jsonb, 1, 'Elle survient souvent après une atteinte de l’hémisphère gauche.', 5),
    ('cb8a2cce-dd7c-5c88-b382-e19940f7acd8'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Quel est le premier facteur de risque de l’AVC ?', 'mcq', '["L’hypertension artérielle","La myopie","L’asthme","L’anémie"]'::jsonb, 0, 'Elle fragilise les artères et favorise leur obstruction comme leur rupture.', 6),
    ('b8d44e67-347b-58f2-b271-e2c98804178c'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Quel examen distingue en urgence un AVC ischémique d’un AVC hémorragique ?', 'mcq', '["L’électrocardiogramme","L’imagerie cérébrale (IRM ou scanner)","La spirométrie","La fibroscopie"]'::jsonb, 1, 'Le traitement est opposé : on ne dissout pas un caillot en cas d’hémorragie.', 7),
    ('4ee5636a-9609-5c6b-b4e6-cf63a3325049'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Que signifie « paresthésie » ?', 'mcq', '["Une sensation anormale comme des fourmillements","Une paralysie totale","Une douleur thoracique","Une perte de mémoire"]'::jsonb, 0, 'C’est un trouble de la sensibilité fréquent dans les lésions nerveuses.', 8),
    ('170fe524-71ea-5d03-a907-8a94e12f182c'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Face à une victime d’accident suspecte de lésion de la moelle, il faut la déplacer rapidement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On immobilise le rachis : un déplacement peut aggraver la lésion.', 9),
    ('b2e99e28-9f56-5e41-a258-2bdd18b06ef4'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Dans une lésion complète de la moelle, la motricité et la sensibilité sous la lésion sont :', 'mcq', '["Conservées","Totalement perdues","Augmentées","Perdues au-dessus seulement"]'::jsonb, 1, 'Une lésion incomplète laisse une perte partielle et un espoir de récupération.', 10),
    ('45753868-8d44-5d48-b88b-660e59b54f37'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'Pourquoi l’AVC est-il une urgence absolue ?', 'mcq', '["Parce qu’il est contagieux","Parce que les neurones privés de dioxygène meurent en quelques minutes","Parce qu’il provoque toujours une fièvre","Parce qu’il ne se soigne qu’à l’hôpital de jour"]'::jsonb, 1, 'La thrombolyse ou la thrombectomie ne sont possibles que dans les premières heures.', 11),
    ('d05d0827-5a26-51f5-b3c5-068d0b62ecc3'::uuid, 'e829f906-7d92-531d-a2c3-8ac21ce1b739'::uuid, 'L’AVC hémorragique est plus fréquent que l’AVC ischémique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’AVC ischémique représente environ 80 % des cas.', 12),
    ('225eb61f-19e6-5bc6-8aea-fbb587f157cd'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Quelle est la différence entre un aliment et un nutriment ?', 'mcq', '["Il n’y en a aucune","L’aliment est la denrée consommée, le nutriment la molécule utilisable par l’organisme","Le nutriment est toujours d’origine animale","L’aliment est une molécule, le nutriment un repas"]'::jsonb, 1, 'La digestion transforme les aliments en nutriments.', 1),
    ('a40ac620-b8e3-5a41-a238-90f58da5935c'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Lequel est un micronutriment ?', 'mcq', '["Les glucides","Les lipides","La vitamine C","Les protides"]'::jsonb, 2, 'Vitamines et minéraux sont nécessaires en très petites quantités.', 2),
    ('a9773624-0c65-5914-831f-c46cedfbf259'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Quel est le rôle principal des protéines ?', 'mcq', '["Énergétique","Structural (construction)","Uniquement fonctionnel","Aucun"]'::jsonb, 1, 'Elles construisent et renouvellent les tissus, même si certaines ont aussi un rôle fonctionnel.', 3),
    ('5fc17eaa-a40c-5d21-86b1-82a14bdddcbd'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Lequel de ces glucides est un polymère ?', 'mcq', '["Le glucose","Le saccharose","L’amidon","Le fructose"]'::jsonb, 2, 'L’amidon est une longue chaîne de glucoses ; le saccharose est un dimère.', 4),
    ('0679a900-2131-529b-bf59-ca41cbfab216'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Quelle part de la masse corporelle l’eau représente-t-elle environ chez l’adulte ?', 'mcq', '["10 %","30 %","60 %","95 %"]'::jsonb, 2, 'Elle est le solvant de toutes les réactions de l’organisme.', 5),
    ('ac57de2e-fc0d-5fd0-a19c-f77c40ffb06b'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Comment calcule-t-on l’IMC ?', 'mcq', '["Masse × taille","Masse / taille²","Taille / masse","Masse / âge"]'::jsonb, 1, 'Masse en kilogrammes, taille en mètres.', 6),
    ('33d35e8d-686b-53f9-abc3-841537430eac'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Une personne de 64 kg mesure 1,60 m. Quel est son IMC ?', 'mcq', '["25","40","20","16"]'::jsonb, 0, 'IMC = 64 / (1,60 × 1,60) = 64 / 2,56 = 25.', 7),
    ('3ed8f029-ecc6-50da-998e-b3073898d8d6'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'À partir de quel IMC parle-t-on d’obésité chez l’adulte ?', 'mcq', '["18,5","25","30","40"]'::jsonb, 2, 'Entre 25 et 30, on parle de surpoids.', 8),
    ('3b7261ca-89f7-56e6-bc3a-e856831d5b2a'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Un bilan énergétique durablement positif entraîne :', 'mcq', '["Un amaigrissement","Une prise de poids","Aucun changement","Une carence en fer"]'::jsonb, 1, 'Les apports dépassent les dépenses : l’excédent est stocké, surtout en graisses.', 9),
    ('9bdeed62-4839-539f-b683-bef63cb20f11'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Les besoins nutritionnels d’une adolescente en croissance sont les mêmes que ceux d’une femme âgée sédentaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Âge, croissance et activité physique modifient les besoins.', 10),
    ('59516ec8-0f20-561a-859b-8fb4c7f28c4c'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Qu’est-ce qu’un besoin qualitatif ?', 'mcq', '["La quantité totale d’énergie","Le besoin en nutriments précis, comme les acides aminés indispensables ou les vitamines","Le nombre de repas par jour","Le poids idéal"]'::jsonb, 1, 'Un apport énergétique suffisant peut rester qualitativement déséquilibré.', 11),
    ('3947e9f5-a754-5c48-bd61-4e4129208eb5'::uuid, 'd05fffd6-4939-51d5-9c58-f5773ddf66f0'::uuid, 'Quels nutriments traversent la paroi intestinale sans digestion préalable ?', 'mcq', '["L’amidon et les protéines","L’eau, les ions et les monomères","Les triglycérides entiers","Le glycogène"]'::jsonb, 1, 'Les polymères doivent d’abord être hydrolysés en monomères.', 12),
    ('fd04149e-ab16-539b-89c0-4d050cf09680'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'L’obésité est une malnutrition :', 'mcq', '["Par défaut","Par excès","Qui ne touche que les enfants","Sans lien avec l’alimentation"]'::jsonb, 1, 'Elle résulte d’un excès d’apports par rapport aux dépenses.', 1),
    ('2057f399-b625-5122-ad4d-cbf3aaff50b4'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Laquelle est une conséquence de l’obésité ?', 'mcq', '["L’anémie ferriprive","Le diabète de type 2","Le scorbut","La myopie"]'::jsonb, 1, 'L’obésité favorise aussi l’hypertension, l’apnée du sommeil et l’arthrose.', 2),
    ('9badf455-da42-53d8-819e-6d7479f4ee0f'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Quel est un traitement de première intention de l’obésité ?', 'mcq', '["La chirurgie immédiate","Le rééquilibrage alimentaire associé à l’activité physique","Le jeûne complet","Les antibiotiques"]'::jsonb, 1, 'La chirurgie bariatrique est réservée aux obésités sévères.', 3),
    ('8b79a918-8bfe-5d24-84d2-1f8bcbd4c0e9'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Qu’est-ce qu’une carence qualitative ?', 'mcq', '["Un apport énergétique global insuffisant","Un apport suffisant en énergie mais pauvre en un nutriment précis","Un excès de sucres","Une intoxication"]'::jsonb, 1, 'Exemple : une alimentation abondante mais pauvre en fer.', 4),
    ('2b34f582-19a3-52db-84fc-4dc69f431094'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Pourquoi une carence en fer provoque-t-elle une anémie ?', 'mcq', '["Le fer est nécessaire à la fabrication de l’hémoglobine","Le fer détruit les globules rouges","Le fer bloque la respiration","Le fer est un sucre énergétique"]'::jsonb, 0, 'Sans fer, l’hémoglobine manque et le sang transporte moins de dioxygène.', 5),
    ('fc67674c-ec8c-51ef-aee3-91b06c2c265f'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Quel signe clinique évoque une anémie ?', 'mcq', '["Une fièvre élevée","Une pâleur et une fatigue","Une douleur au genou","Une toux grasse"]'::jsonb, 1, 'Le manque de dioxygène apporté aux tissus fatigue et essouffle.', 6),
    ('bb192061-0569-51f7-8199-8290959d9248'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Quel dosage sanguin indique que les réserves de fer sont vides ?', 'mcq', '["La glycémie","La ferritine","La créatinine","Le cholestérol"]'::jsonb, 1, 'Une ferritine basse signe une carence en fer.', 7),
    ('e3089311-2874-56e3-8bce-20017b97572a'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Que désigne la cachexie ?', 'mcq', '["Une faim excessive","Un amaigrissement extrême avec fonte musculaire","Une prise de poids rapide","Une inflammation de l’estomac"]'::jsonb, 1, 'C’est l’aboutissement d’une malnutrition quantitative sévère ou de certaines maladies.', 8),
    ('4bd63cfd-fc5e-5f5a-9d76-8b7d44a4df3f'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'La vitamine C favorise l’absorption du fer d’origine végétale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est pourquoi on conseille un fruit riche en vitamine C au cours du repas.', 9),
    ('efc9e7fc-f1ba-5b91-b8d0-9c1f02a9b0d7'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Quelle carence provoque le scorbut ?', 'mcq', '["En vitamine D","En vitamine C","En fer","En calcium"]'::jsonb, 1, 'Gencives qui saignent et fatigue en sont les signes classiques.', 10),
    ('75984a2f-08bc-5487-8bef-837621736e6f'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'La sédentarité est un facteur de risque d’obésité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle réduit les dépenses énergétiques et déséquilibre le bilan.', 11),
    ('3d192bba-1f90-5e5a-9453-ed69871ba644'::uuid, '5b278a8e-cc5b-50cb-9f80-cc86b74810c0'::uuid, 'Que signifie « polyphagie » ?', 'mcq', '["Un refus de s’alimenter","Un besoin excessif de manger","Une difficulté à avaler","Une perte de goût"]'::jsonb, 1, 'poly = beaucoup, -phagie = manger.', 12),
    ('2fa79f39-906e-50d1-8084-13abfd1093ee'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Lequel est une glande annexe du tube digestif ?', 'mcq', '["L’estomac","Le pancréas","Le côlon","L’œsophage"]'::jsonb, 1, 'Il déverse le suc pancréatique dans le duodénum sans être traversé par les aliments.', 1),
    ('b510fde3-8ff1-5f4e-b700-24104fcdcab5'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Quel est l’ordre de passage des aliments ?', 'mcq', '["Bouche, œsophage, estomac, intestin grêle, côlon","Bouche, estomac, œsophage, côlon, intestin grêle","Bouche, pharynx, foie, estomac","Œsophage, bouche, estomac, rectum"]'::jsonb, 0, 'Le pharynx suit la bouche, puis viennent œsophage, estomac, grêle et gros intestin.', 2),
    ('c88f4d54-dd96-50e7-831f-ae59018270a3'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Quelle tunique de la paroi digestive assure le brassage et la progression des aliments ?', 'mcq', '["La muqueuse","La sous-muqueuse","La musculeuse","La séreuse"]'::jsonb, 2, 'Ses muscles lisses produisent le péristaltisme.', 3),
    ('d97c00d4-8df3-5c0f-b027-f9b1f475c596'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Quelle enzyme commence la digestion des protéines dans l’estomac ?', 'mcq', '["L’amylase","La lipase","La pepsine","La lactase"]'::jsonb, 2, 'Elle agit à pH très acide, environ 2.', 4),
    ('b46c9d42-2b2a-5179-ad1d-974330eab8ea'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Quel est le rôle de la bile ?', 'mcq', '["Hydrolyser l’amidon","Émulsionner les graisses","Digérer les protéines","Produire de l’insuline"]'::jsonb, 1, 'Elle fragmente les graisses en gouttelettes, sans être une enzyme.', 5),
    ('cebcc0de-387c-5ede-8d87-15175ee13fb3'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Quels sont les produits de la digestion des triglycérides ?', 'mcq', '["Glucose et fructose","Acides aminés","Acides gras et monoglycérides","Maltose"]'::jsonb, 2, 'L’action de la lipase pancréatique libère des acides gras.', 6),
    ('e273cc76-8a83-555c-92bd-b094140f3322'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Où la bile est-elle produite ?', 'mcq', '["Dans la vésicule biliaire","Dans le foie","Dans le pancréas","Dans l’estomac"]'::jsonb, 1, 'Elle est seulement stockée et concentrée dans la vésicule biliaire.', 7),
    ('c4c62dbd-4390-570c-b9cb-d4bbfda7f6a9'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Une enzyme digestive agit sur n’importe quel substrat.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est spécifique : l’amylase n’agit que sur l’amidon, pas sur les protéines.', 8),
    ('585dd964-18de-5a06-953f-e7cec995862d'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Pourquoi la mastication facilite-t-elle la digestion chimique ?', 'mcq', '["Elle chauffe les aliments","Elle fragmente les aliments et augmente la surface d’action des enzymes","Elle neutralise l’acidité","Elle absorbe le glucose"]'::jsonb, 1, 'Phénomènes mécaniques et chimiques se complètent.', 9),
    ('6c20b64a-7764-5213-a76e-8919cef6ae09'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Quel rôle joue le microbiote intestinal ?', 'mcq', '["Il produit la bile","Il fermente les fibres et produit certaines vitamines","Il digère l’amidon dans la bouche","Il absorbe l’eau dans l’estomac"]'::jsonb, 1, 'Il participe aussi à la défense contre les pathogènes.', 10),
    ('3df412c5-6a1e-57c6-bd5d-ee6832e45225'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'Que désigne la racine « hépat(o) » ?', 'mcq', '["L’estomac","Le foie","L’intestin","La vésicule biliaire"]'::jsonb, 1, 'L’hépatite est une inflammation du foie.', 11),
    ('55e78722-91fc-5cb3-b039-d54fb846ef0d'::uuid, 'db9d6a72-b566-5310-a1fb-a4d12613c7b8'::uuid, 'L’amylase salivaire transforme l’amidon en :', 'mcq', '["Glucose directement","Maltose","Acides aminés","Lactose"]'::jsonb, 1, 'Le maltose sera hydrolysé en glucose par la maltase intestinale.', 12),
    ('92a73d90-0f80-5660-90e9-49555cde37a2'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Quelle structure de la muqueuse intestinale contient un chylifère ?', 'mcq', '["La valvule connivente","La villosité","La microvillosité","La glande gastrique"]'::jsonb, 1, 'Chaque villosité contient des capillaires sanguins et un vaisseau lymphatique central.', 1),
    ('aa568f76-51b5-5de9-95b8-9a79201d005c'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Par quelle voie le glucose rejoint-il la circulation ?', 'mcq', '["La voie lymphatique","La voie sanguine, par la veine porte","Il reste dans l’intestin","Par la bile"]'::jsonb, 1, 'Hydrophile, il passe dans les capillaires sanguins puis va au foie.', 2),
    ('b263c4a4-b38a-5d75-962d-0c508b80c249'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Par quelle voie les acides gras longs sont-ils principalement absorbés ?', 'mcq', '["La voie sanguine directe","La voie lymphatique, sous forme de chylomicrons","Ils ne sont jamais absorbés","Par l’estomac"]'::jsonb, 1, 'Reconstitués en triglycérides, ils sont emballés dans des chylomicrons.', 3),
    ('1ca526db-d180-5eb5-b67f-110f7551c0ab'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Comment l’eau est-elle absorbée dans l’intestin ?', 'mcq', '["Par digestion enzymatique","Par osmose","Par la bile","Par la voie lymphatique uniquement"]'::jsonb, 1, 'Elle suit les nutriments et ions absorbés, vers le milieu le plus concentré.', 4),
    ('38866c73-49d9-539f-8bc1-ce0e29c27027'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Quelles caractéristiques de l’intestin grêle favorisent l’absorption ?', 'mcq', '["Une paroi épaisse et peu vascularisée","Une surface immense, une paroi fine et une riche vascularisation","L’absence de replis","Une muqueuse kératinisée"]'::jsonb, 1, 'Replis, villosités et microvillosités multiplient la surface.', 5),
    ('2c5a586d-1004-5f4a-b2ca-b41d5d3bc1d9'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Quelles vitamines empruntent la voie lymphatique ?', 'mcq', '["Les vitamines B et C","Les vitamines A, D, E et K","Toutes les vitamines","Aucune vitamine"]'::jsonb, 1, 'Ce sont les vitamines liposolubles, absorbées avec les graisses.', 6),
    ('abe9027f-8d54-503b-a958-61d8c88f2123'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Qu’est-ce qu’une fibroscopie œso-gastro-duodénale ?', 'mcq', '["Une radiographie de l’abdomen","L’introduction par la bouche d’un tube souple muni d’une caméra","Un dosage sanguin","Une échographie du foie"]'::jsonb, 1, 'Elle permet de voir la muqueuse et de faire des biopsies.', 7),
    ('7f139905-600b-5bd6-81e1-901d7d3fff5f'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Quelle lésion caractérise la maladie cœliaque ?', 'mcq', '["Un ulcère de l’estomac","L’atrophie des villosités intestinales","Un polype du côlon","Une obstruction de l’œsophage"]'::jsonb, 1, 'Le gluten déclenche une réaction qui détruit les villosités.', 8),
    ('accbe107-ee87-5597-b001-b4e6a718681b'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Quel est le traitement de la maladie cœliaque ?', 'mcq', '["Des antibiotiques","Un régime strict sans gluten à vie","Une chirurgie de l’estomac","Un régime riche en blé"]'::jsonb, 1, 'Sans gluten, les villosités repoussent.', 9),
    ('6ae547bc-3210-56cd-9547-deba4d856148'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Que signifie « rectorragie » ?', 'mcq', '["Un vomissement de sang","Un saignement par l’anus","Une inflammation du rectum","Une douleur abdominale"]'::jsonb, 1, 'rect(o) = rectum, -rragie = écoulement de sang.', 10),
    ('fbf454f1-39bd-5837-9f13-ff7e5f0318d6'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'La fibroscopie permet de réaliser des biopsies.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Des prélèvements de muqueuse sont analysés au microscope.', 11),
    ('71fb38a1-bcdd-5a0b-a226-6ad429121218'::uuid, '85891d8a-e158-515a-b6dd-e4e6dcc6cbf2'::uuid, 'Pourquoi une malabsorption peut-elle provoquer une anémie ?', 'mcq', '["Parce que le fer n’est plus absorbé correctement","Parce que l’intestin détruit les globules rouges","Parce que le gluten contient du fer","Parce que la bile manque"]'::jsonb, 0, 'Les villosités détruites laissent passer moins de fer et de vitamines.', 12),
    ('d9fca9d4-8d13-5dc1-b29f-a15e46cc3b1b'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Quelle cavité cardiaque envoie le sang dans l’aorte ?', 'mcq', '["L’oreillette droite","Le ventricule droit","L’oreillette gauche","Le ventricule gauche"]'::jsonb, 3, 'Le ventricule gauche, à la paroi la plus épaisse, alimente la grande circulation.', 1),
    ('d46d6f21-05f0-5694-8dc7-10b0080f94d0'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Par quels vaisseaux le sang revient-il des poumons au cœur ?', 'mcq', '["Les veines caves","Les artères pulmonaires","Les veines pulmonaires","L’aorte"]'::jsonb, 2, 'Riche en dioxygène, il arrive dans l’oreillette gauche.', 2),
    ('36a93c3a-8068-5584-974c-70996d029e55'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Quelle valve sépare l’oreillette gauche du ventricule gauche ?', 'mcq', '["La valve tricuspide","La valve mitrale","La valve aortique","La valve pulmonaire"]'::jsonb, 1, 'La tricuspide est son équivalent dans le cœur droit.', 3),
    ('4c356a39-f8a8-5c72-a480-371b1d546edb'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Pourquoi le ventricule gauche a-t-il une paroi plus épaisse que le droit ?', 'mcq', '["Il reçoit plus de sang","Il doit propulser le sang dans tout l’organisme","Il contient le tissu nodal","Il est plus ancien"]'::jsonb, 1, 'La grande circulation oppose une résistance bien plus forte que la petite.', 4),
    ('2ce6c282-868e-5c3f-a20c-647835283657'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Quel élément joue le rôle de pacemaker naturel du cœur ?', 'mcq', '["Le faisceau de His","Le nœud sinusal","La valve mitrale","Le péricarde"]'::jsonb, 1, 'Situé dans l’oreillette droite, il impose le rythme cardiaque.', 5),
    ('2fd5227d-6e62-5047-97a8-e8bacf1abd4e'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Un cœur isolé de tout nerf cesse immédiatement de battre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il continue de battre grâce à l’automatisme de son tissu nodal.', 6),
    ('606ce8f7-30ec-51bb-8e87-ec26eb075496'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Volume en fin de diastole 120 mL, en fin de systole 50 mL. Quel est le VES ?', 'mcq', '["170 mL","70 mL","60 mL","2,4 mL"]'::jsonb, 1, 'VES = 120 − 50 = 70 mL.', 7),
    ('52afc6c7-a06a-523c-bd52-2e219cc1faf1'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'fC = 80 battements/min et VES = 60 mL. Quel est le débit cardiaque ?', 'mcq', '["140 mL/min","4,8 L/min","1,3 L/min","48 L/min"]'::jsonb, 1, 'DC = 80 × 60 = 4 800 mL/min = 4,8 L/min.', 8),
    ('62234f26-9239-5ce4-bdec-497d9b1672c3'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Pendant l’éjection ventriculaire, les valves sigmoïdes sont :', 'mcq', '["Fermées","Ouvertes","Absentes","Retournées"]'::jsonb, 1, 'Elles s’ouvrent quand la pression ventriculaire dépasse celle des artères.', 9),
    ('b2bf2338-ce53-5b2f-b985-cd4347dc415a'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Quel est le trajet de la circulation pulmonaire ?', 'mcq', '["Ventricule gauche, aorte, organes","Ventricule droit, artère pulmonaire, poumons, veines pulmonaires, oreillette gauche","Oreillette droite, aorte, poumons","Veines caves, poumons, ventricule gauche"]'::jsonb, 1, 'C’est la petite circulation, qui recharge le sang en dioxygène.', 10),
    ('cb103a4c-cb3a-5515-87bc-223af8a6fd46'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Quel est le rôle du nœud atrio-ventriculaire ?', 'mcq', '["Donner le rythme","Retarder légèrement l’influx pour laisser les ventricules se remplir","Fermer les valves","Produire le sang"]'::jsonb, 1, 'Ce délai coordonne la contraction des oreillettes puis des ventricules.', 11),
    ('ac85c927-fe0d-5fc6-87c0-86519a5c6739'::uuid, 'a5502251-87ac-5931-940d-ac26bce88331'::uuid, 'Quelle enveloppe entoure le cœur ?', 'mcq', '["L’endocarde","Le péricarde","La plèvre","Le péritoine"]'::jsonb, 1, 'L’endocarde tapisse l’intérieur, le péricarde enveloppe l’extérieur.', 12),
    ('4934c448-a5c5-59e6-86ac-2f972da6f64b'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Quel vaisseau possède une paroi réduite à un endothélium ?', 'mcq', '["L’artère","La veine","Le capillaire","L’aorte"]'::jsonb, 2, 'Cette paroi très fine permet les échanges avec les tissus.', 1),
    ('14219c4b-4095-5727-bbb9-34e94b10e8ce'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'À quoi servent les valvules des veines ?', 'mcq', '["À accélérer le sang","À empêcher le reflux du sang","À filtrer le sang","À produire des globules"]'::jsonb, 1, 'Elles aident le retour du sang vers le cœur, à basse pression.', 2),
    ('948c035b-4c50-555d-89da-3fa3522e95b0'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Où sont situés les barorécepteurs ?', 'mcq', '["Dans le bulbe rachidien","Dans le sinus carotidien et la crosse de l’aorte","Dans les veines des jambes","Dans le ventricule droit"]'::jsonb, 1, 'Ils sont sensibles à l’étirement de la paroi artérielle.', 3),
    ('402b43dd-76a1-5e0d-a229-aa1eab7609af'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Quel nerf ralentit le cœur ?', 'mcq', '["Le nerf sympathique","Le nerf vague (parasympathique)","Le nerf optique","Le nerf sciatique"]'::jsonb, 1, 'Le sympathique, au contraire, l’accélère.', 4),
    ('5db0c2ed-2a8e-57f5-a91a-119e6684d768'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Après une hémorragie, la fréquence cardiaque :', 'mcq', '["Diminue","Augmente","Ne change pas","S’annule"]'::jsonb, 1, 'Le sympathique est stimulé : tachycardie et vasoconstriction font remonter la pression.', 5),
    ('a3477417-c391-527a-a1e9-5f36b6d95fa1'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Que représente l’onde P de l’ECG ?', 'mcq', '["La dépolarisation des ventricules","La dépolarisation des oreillettes","La repolarisation des ventricules","La fermeture des valves"]'::jsonb, 1, 'Le complexe QRS correspond aux ventricules.', 6),
    ('908cb87c-ec72-55a1-945f-1aaec910f5e8'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Deux pics R sont séparés de 0,60 s. Quelle est la fréquence cardiaque ?', 'mcq', '["60 battements/min","100 battements/min","120 battements/min","36 battements/min"]'::jsonb, 1, 'fC = 60 / 0,60 = 100 battements/min.', 7),
    ('acb7526e-1dd5-5170-a11e-d8a8588a4d56'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Quel examen utilise un produit de contraste iodé et des rayons X pour visualiser les artères ?', 'mcq', '["L’échographie","L’angiographie","La scintigraphie","L’ECG"]'::jsonb, 1, 'Appliquée aux artères du cœur, c’est la coronarographie.', 8),
    ('8caa948d-93ad-54fb-b2ee-c375ee7c5b0c'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Quelle technique mesure la vitesse du sang dans un vaisseau ?', 'mcq', '["Le Doppler","La radiographie simple","L’ECG","La spirométrie"]'::jsonb, 0, 'La fréquence des ultrasons réfléchis dépend de la vitesse des globules.', 9),
    ('dc1b86f3-cbfd-5fe3-9e2c-945fb637c032'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Une tension de 15/10 cmHg mesurée à plusieurs reprises au repos évoque :', 'mcq', '["Une hypotension","Une tension normale","Une hypertension artérielle","Une hémorragie"]'::jsonb, 2, 'Le seuil de l’hypertension est 14/9 cmHg.', 10),
    ('acd85f00-344d-5b9e-8e84-85d7165341a7'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Le centre nerveux de la régulation cardiaque se situe dans le bulbe rachidien.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il reçoit les messages des barorécepteurs et commande cœur et vaisseaux.', 11),
    ('44735699-8909-5dd0-8a21-4a41d466a98d'::uuid, '6074ac9d-617c-5621-aa2a-4fbdd0113366'::uuid, 'Quelle technique utilise un traceur radioactif et une gamma-caméra ?', 'mcq', '["La scintigraphie","Le Doppler","L’angiographie","L’IRM"]'::jsonb, 0, 'Elle repère les zones du myocarde mal irriguées.', 12),
    ('b8a2c94e-db96-51cf-9a0f-62b5c336c013'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Quelle molécule est au départ de la formation d’une plaque d’athérome ?', 'mcq', '["Le glucose","Le LDL-cholestérol","L’hémoglobine","L’urée"]'::jsonb, 1, 'En excès, il s’infiltre dans l’intima de l’artère et s’y oxyde.', 1),
    ('59047d59-56f1-5ab3-b87d-2c94e9aff9c3'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Que sont les cellules spumeuses ?', 'mcq', '["Des globules rouges déformés","Des macrophages gorgés de lipides","Des cellules musculaires cardiaques","Des plaquettes"]'::jsonb, 1, 'Elles forment la strie lipidique, premier stade de la plaque.', 2),
    ('aa4ebcae-d9ab-5439-8aaf-212a12da2cda'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Qu’est-ce qu’une sténose ?', 'mcq', '["Une rupture d’artère","Un rétrécissement de la lumière d’un vaisseau","Une dilatation d’artère","Une infection du cœur"]'::jsonb, 1, 'La plaque qui grossit réduit le passage du sang.', 3),
    ('a1c7ac7f-cc3d-5a05-8eb3-1b9b577f00e9'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Qu’est-ce que l’ischémie ?', 'mcq', '["Un excès de sang dans un organe","Un apport insuffisant de sang et de dioxygène à un organe","Une mort cellulaire","Une inflammation"]'::jsonb, 1, 'Si elle dure, elle aboutit à la nécrose.', 4),
    ('b1f5b698-7e70-587b-926b-dca8e55f42f9'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Quelle douleur évoque un angor ?', 'mcq', '["Une douleur thoracique à l’effort qui cède au repos","Une douleur thoracique de plus d’une heure au repos","Une douleur au genou","Une douleur abdominale après le repas"]'::jsonb, 0, 'L’ischémie est transitoire : quand le besoin en dioxygène baisse, la douleur disparaît.', 5),
    ('4e1a2daf-bc7a-51cb-87eb-ba005ea3b14a'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Dans l’infarctus du myocarde, la douleur cède à la trinitrine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’artère est bouchée : la trinitrine ne suffit pas, la douleur persiste.', 6),
    ('4552c701-2897-5f84-940b-264b5d9f44da'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Pourquoi dose-t-on la troponine en cas de douleur thoracique ?', 'mcq', '["Elle signe une infection","Elle est libérée par les cellules du myocarde nécrosées","Elle mesure le cholestérol","Elle mesure la glycémie"]'::jsonb, 1, 'Son élévation confirme l’infarctus.', 7),
    ('f280b845-8f3e-525d-8b88-57937a29e2b4'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Quelles artères nourrissent le muscle cardiaque ?', 'mcq', '["Les carotides","Les coronaires","Les artères pulmonaires","Les artères fémorales"]'::jsonb, 1, 'Leur obstruction provoque angor et infarctus.', 8),
    ('59824ece-df5c-5d36-bac7-69c4870c946a'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Qu’est-ce qu’un stent ?', 'mcq', '["Un médicament contre le cholestérol","Un petit ressort qui maintient une artère ouverte","Un stimulateur cardiaque","Une valve artificielle"]'::jsonb, 1, 'Il est posé lors d’une angioplastie.', 9),
    ('4131b469-b29f-5c9b-96bb-1e0fe1608df4'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Lequel est un facteur de risque modifiable de l’athérosclérose ?', 'mcq', '["L’âge","Le sexe","Le tabagisme","L’hérédité"]'::jsonb, 2, 'Arrêter de fumer réduit fortement le risque cardio-vasculaire.', 10),
    ('1a391537-db50-5d0e-b2e9-2b903cf14445'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Qu’est-ce qu’une embolie ?', 'mcq', '["L’obstruction d’un vaisseau par un caillot venu d’ailleurs","La dilatation d’une artère","La rupture du cœur","Une baisse de tension"]'::jsonb, 0, 'Le caillot migre avec le sang et bloque un vaisseau plus étroit.', 11),
    ('8f07f0c8-e0db-5f72-8129-3c20f81540aa'::uuid, '8436d890-7b9b-5c7f-8ae1-0859a388dcd1'::uuid, 'Que signifie « nécrose » ?', 'mcq', '["La mort de cellules ou d’un tissu","Un rétrécissement d’artère","Un caillot","Un trouble du rythme"]'::jsonb, 0, 'Dans l’infarctus, une partie du myocarde est nécrosée.', 12),
    ('ffa6b2d8-8fb3-5144-8376-6a3c70b06c52'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Dans quel ordre l’air traverse-t-il les voies respiratoires ?', 'mcq', '["Trachée, larynx, bronches, alvéoles","Fosses nasales, pharynx, larynx, trachée, bronches, bronchioles, alvéoles","Pharynx, bronches, trachée, larynx","Alvéoles, bronchioles, trachée, larynx"]'::jsonb, 1, 'Les voies supérieures précèdent la trachée et l’arbre bronchique.', 1),
    ('190cf521-d351-5102-b2d1-6ed2975e3421'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Pourquoi la trachée reste-t-elle toujours ouverte ?', 'mcq', '["Grâce à ses anneaux de cartilage","Grâce à la pression du sang","Grâce au mucus","Parce qu’elle est dépourvue de paroi"]'::jsonb, 0, 'Ces anneaux en forme de C l’empêchent de s’affaisser.', 2),
    ('76c4e696-ec93-5f82-921d-78e68afb4f22'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Quels éléments composent la barrière alvéolo-capillaire ?', 'mcq', '["Cartilage et muscle","Épithélium alvéolaire, lame basale et endothélium capillaire","Plèvre et diaphragme","Mucus et cils"]'::jsonb, 1, 'Très fine et très étendue, elle favorise la diffusion des gaz.', 3),
    ('35702921-77cf-52de-b573-cc4402155616'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Dans les poumons, le dioxygène diffuse :', 'mcq', '["Du sang vers l’air alvéolaire","De l’air alvéolaire vers le sang","Des tissus vers les poumons","Il ne diffuse pas"]'::jsonb, 1, 'Sa pression partielle est plus forte dans l’air alvéolaire que dans le sang veineux.', 4),
    ('1f67aefb-f2bb-51f0-aab1-c8ed05bbc5b5'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Sous quelle forme la majorité du dioxygène est-elle transportée dans le sang ?', 'mcq', '["Dissous dans le plasma","Fixé à l’hémoglobine","Sous forme d’hydrogénocarbonate","Dans les plaquettes"]'::jsonb, 1, 'Environ 98 % du dioxygène est porté par l’hémoglobine.', 5),
    ('46d7f180-9251-5a08-b126-9e0a6a7622f6'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Sous quelle forme la majorité du CO₂ est-elle transportée ?', 'mcq', '["Fixé au fer de l’hème","Sous forme d’ions hydrogénocarbonate","Dissous uniquement","Sous forme de glucose"]'::jsonb, 1, 'Environ 70 % du CO₂ voyage sous forme d’ions HCO₃⁻.', 6),
    ('de4d022a-459e-5672-b618-1d99c4f65994'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Combien de molécules de dioxygène une hémoglobine peut-elle fixer ?', 'mcq', '["1","2","4","8"]'::jsonb, 2, 'Une par hème, et elle en compte quatre.', 7),
    ('3d60e76b-7b3d-52d6-96e6-878a4606d79a'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Quel effet une baisse du pH a-t-elle sur l’hémoglobine ?', 'mcq', '["Elle augmente son affinité pour l’O₂","Elle diminue son affinité pour l’O₂, qui est davantage libéré","Elle la détruit","Aucun effet"]'::jsonb, 1, 'C’est l’effet Bohr, utile dans les muscles en activité.', 8),
    ('21ba7e19-c6f3-5301-8eba-681ed0bd9d32'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Où se déroule la respiration cellulaire ?', 'mcq', '["Dans le noyau","Dans les mitochondries","Dans les alvéoles","Dans le plasma"]'::jsonb, 1, 'Les mitochondries oxydent les nutriments et produisent l’ATP.', 9),
    ('2ef5fd2f-b4bf-5535-88c5-762768c9d43d'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Les bronchioles ne contiennent pas de cartilage mais du muscle lisse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Leur muscle lisse règle leur diamètre ; il se contracte dans la crise d’asthme.', 10),
    ('8435f497-c33e-5e71-be10-d55958315242'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Quel est le rôle des cils de l’épithélium respiratoire ?', 'mcq', '["Absorber le dioxygène","Remonter le mucus chargé de particules vers la gorge","Produire du surfactant","Contracter les bronches"]'::jsonb, 1, 'C’est l’escalator muco-ciliaire, qui nettoie les voies aériennes.', 11),
    ('5ddadc21-c1f5-5aca-9f6e-0a1315b79186'::uuid, 'f081dd2c-7775-5d53-aa2a-b317dd08748a'::uuid, 'Que signifie « dyspnée » ?', 'mcq', '["Une toux sèche","Une difficulté à respirer","Un crachat de sang","Une coloration bleue de la peau"]'::jsonb, 1, 'dys = difficulté, -pnée = respiration.', 12),
    ('e4a3619f-37dc-5437-8cd1-ca010b9176ff'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Qu’est-ce que la capacité vitale ?', 'mcq', '["Le volume d’air qui reste dans les poumons","La somme du volume courant et des volumes de réserve inspiratoire et expiratoire","Le volume d’une respiration calme","Le volume expiré en une seconde"]'::jsonb, 1, 'CV = VC + VRI + VRE, environ 4 à 5 L chez l’adulte.', 1),
    ('ac5f2b89-5b81-5483-bb71-9b721429583e'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Quel est l’ordre de grandeur du volume courant chez l’adulte au repos ?', 'mcq', '["0,05 L","0,5 L","5 L","50 L"]'::jsonb, 1, 'Un demi-litre d’air à chaque respiration calme.', 2),
    ('e176fe91-be59-51c1-9fba-284abf09dffa'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Un rapport VEMS / CV nettement inférieur à 70 % indique :', 'mcq', '["Une fonction respiratoire normale","Un trouble ventilatoire obstructif","Une anémie","Une hypertension"]'::jsonb, 1, 'L’air sort difficilement : les bronches sont rétrécies.', 3),
    ('a60f1b07-5ecb-578c-be44-9ed75a8f665c'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Le volume résiduel peut être mesuré par un spiromètre simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cet air reste toujours dans les poumons : le spiromètre ne le voit pas.', 4),
    ('ace6dfaa-b72a-592e-a087-dc0a043d69c4'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Quels phénomènes rétrécissent les bronchioles lors d’une crise d’asthme ?', 'mcq', '["Bronchoconstriction, œdème et hypersécrétion de mucus","Dilatation des bronches","Destruction des alvéoles seule","Formation d’une plaque d’athérome"]'::jsonb, 0, 'Les trois s’additionnent pour gêner le passage de l’air.', 5),
    ('be076f35-8ba2-5d8b-89c4-e8793f384bce'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Quel traitement soulage une crise d’asthme ?', 'mcq', '["Un corticoïde de fond seul","Un bronchodilatateur inhalé de courte durée","Un antibiotique","Un anticoagulant"]'::jsonb, 1, 'Il relâche le muscle lisse des bronchioles en quelques minutes.', 6),
    ('2229f266-bc74-560b-a238-fd99b0e0c191'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Quelle est une caractéristique de l’obstruction bronchique dans l’asthme ?', 'mcq', '["Elle est réversible après un bronchodilatateur","Elle est toujours définitive","Elle n’apparaît qu’à l’inspiration","Elle est due au monoxyde de carbone"]'::jsonb, 0, 'C’est ce qui la distingue de la BPCO.', 7),
    ('70512d9e-0398-5876-ba66-771964dc5786'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Lequel est un facteur déclenchant de l’asthme ?', 'mcq', '["Les acariens","Le calcium","La vitamine C","L’eau potable"]'::jsonb, 0, 'Les allergènes comme les acariens et les pollens déclenchent les crises.', 8),
    ('10dc11dd-c406-5e84-9cf1-6cef6465f642'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Quel constituant de la fumée du tabac crée la dépendance ?', 'mcq', '["Les goudrons","La nicotine","Le monoxyde de carbone","La vapeur d’eau"]'::jsonb, 1, 'Elle agit sur le cerveau et entretient le besoin de fumer.', 9),
    ('8c3b5bb6-d6e7-55a0-8079-918fdf25ac15'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Pourquoi le monoxyde de carbone réduit-il le transport du dioxygène ?', 'mcq', '["Il détruit les poumons","Il se fixe sur l’hémoglobine bien plus fortement que le dioxygène","Il bloque la trachée","Il dissout les globules rouges"]'::jsonb, 1, 'L’hémoglobine occupée par le CO ne porte plus d’O₂.', 10),
    ('649281b0-9242-5167-ba56-2bb9adfe1304'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Quels constituants du tabac sont cancérigènes ?', 'mcq', '["La nicotine","Les goudrons","L’eau","Le dioxygène"]'::jsonb, 1, 'Ils sont responsables des cancers du poumon, de la gorge, de la vessie…', 11),
    ('72f7755d-1903-53b8-9ebe-dcc985866f4e'::uuid, '2e3adbb4-3251-57a7-bb61-ff6805e8395c'::uuid, 'Que désigne l’hémoptysie ?', 'mcq', '["Un vomissement de sang","Un crachat de sang d’origine respiratoire","Une coloration bleue des lèvres","Une toux sèche"]'::jsonb, 1, 'hém(o) = sang, -ptysie = crachat.', 12),
    ('3d387c54-ef9a-52a9-a71e-f71d5eae8d20'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Qu’est-ce qu’un signe paraclinique ?', 'mcq', '["Un symptôme ressenti par le patient","Un résultat d’examen complémentaire (imagerie, bilan sanguin, ECG)","Un facteur de risque","Un traitement"]'::jsonb, 1, 'Le signe clinique se constate à l’examen du patient ; le paraclinique, par les examens.', 1),
    ('b93ac68d-3a8e-5410-b51f-0c49d477d7f9'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Que signifie le suffixe « -ite » ?', 'mcq', '["Douleur","Inflammation","Ablation","Paralysie"]'::jsonb, 1, 'Gastrite, arthrite, hépatite : des inflammations.', 2),
    ('8974bebc-e0ef-5762-8c38-b484e8d2e821'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Que signifie « cholécystectomie » ?', 'mcq', '["L’inflammation de la vésicule biliaire","L’ablation de la vésicule biliaire","L’examen de l’estomac","Une douleur du foie"]'::jsonb, 1, 'cholécyst(o) = vésicule biliaire, -ectomie = ablation.', 3),
    ('54638468-006d-5339-8a71-ccacb605b9b1'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Quelle est la bonne démarche pour analyser une courbe ?', 'mcq', '["Donner directement la conclusion","Lire titre et unités, décrire avec des valeurs, comparer, interpréter, conclure","Recopier la légende","Ne regarder que le dernier point"]'::jsonb, 1, 'Chaque étape s’appuie sur des données précises du document.', 4),
    ('3f7cab2e-294f-592a-8ee1-b4e818a5a7d1'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Comment tracer les traits de légende d’un schéma ?', 'mcq', '["À main levée, en les croisant","À la règle, sans qu’ils se croisent","En couleur vive, sans ordre","Aucun trait n’est nécessaire"]'::jsonb, 1, 'Des légendes alignées et des traits droits rendent le schéma lisible.', 5),
    ('1a9a0aef-5c76-58b8-9d03-b59e27bcbe01'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Justifier un traitement consiste à :', 'mcq', '["Citer son nom","Montrer comment il corrige le mécanisme de la maladie","Donner son prix","Le comparer à un autre au hasard"]'::jsonb, 1, 'Exemple : l’antiagrégant empêche la formation d’un nouveau caillot.', 6),
    ('ca04380e-1d4d-5c3c-a6f9-4d4d99a393b3'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Le suffixe « -émie » signifie :', 'mcq', '["Présence dans le sang","Absence de sang","Inflammation du sang","Écoulement de sang"]'::jsonb, 0, 'Glycémie : présence de glucose dans le sang.', 7),
    ('6edb9a9a-06e6-5461-960c-2d8fcc9801b0'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'La biologie et physiopathologie humaines de première est évaluée par une épreuve écrite finale en fin de première.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est évaluée en contrôle continu ; ses notions reviennent dans l’épreuve de CBPH de terminale.', 8),
    ('5fa24793-0b69-5bb9-b93e-f589a045a1e3'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Quel préfixe indique une difficulté ou une anomalie ?', 'mcq', '["Hyper-","Dys-","Hypo-","Poly-"]'::jsonb, 1, 'Dyspnée : difficulté à respirer.', 9),
    ('6f24a3f4-2fc2-5168-9366-23b857255af5'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Dans une réponse à un document, une bonne idée doit être associée à :', 'mcq', '["Une donnée chiffrée prélevée et une explication","Une opinion personnelle","Une citation d’un autre chapitre sans lien","Rien d’autre"]'::jsonb, 0, 'Une idée, une donnée, une explication : c’est ce qui rapporte les points.', 10),
    ('a3cb4111-5db2-57a4-91fe-3c2ffe16a622'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Qu’est-ce que « hypotension » ?', 'mcq', '["Une tension artérielle trop élevée","Une tension artérielle trop basse","Une tension normale","Une douleur thoracique"]'::jsonb, 1, 'hypo- = insuffisance.', 11),
    ('5901f032-cd5f-5a70-b18b-089ad76f4f6f'::uuid, '35bc44f8-b770-526d-a01e-8978763b94fd'::uuid, 'Dans le raisonnement physiopathologique, les facteurs de risque servent surtout à construire :', 'mcq', '["Le diagnostic d’imagerie","La prévention","Le schéma anatomique","Le calcul du débit"]'::jsonb, 1, 'Agir sur un facteur de risque modifiable, c’est prévenir la maladie.', 12),
    ('6c904cca-9cf4-5ee4-a664-b216ec05c142'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Quelle relation relie le volume d’un gaz à sa quantité de matière ?', 'mcq', '["V = n × Vm","V = n ÷ Vm","V = m × M","V = C × n"]'::jsonb, 0, 'Vm est le volume molaire, environ 24 L/mol à 20 °C.', 1),
    ('05b737a3-50b7-5d3c-a391-e6348888eea7'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'D’après 2 NaN₃ → 2 Na + 3 N₂, combien de moles de diazote donnent 4 mol d’azoture de sodium ?', 'mcq', '["2 mol","4 mol","6 mol","3 mol"]'::jsonb, 2, 'Les proportions sont de 2 pour 3 : 4 × 3 ÷ 2 = 6 mol.', 2),
    ('5ebf57af-5e00-5c6b-9066-d2181c69eff0'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Dans l’éthylotest chimique, que devient l’éthanol ?', 'mcq', '["Il est réduit","Il est oxydé en acide éthanoïque","Il reste inchangé","Il devient du dichromate"]'::jsonb, 1, 'Les ions dichromate, eux, sont réduits en ions chrome III verts.', 3),
    ('56c5e777-876c-549b-8988-744d8c3f82f2'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Quel changement de couleur indique la présence d’alcool dans un éthylotest chimique ?', 'mcq', '["Du vert à l’orange","De l’orange au vert","Du bleu au rouge","Du blanc au bleu"]'::jsonb, 1, 'Les ions dichromate orange deviennent des ions Cr³⁺ verts.', 4),
    ('6b4733d9-cbb4-573f-81d8-979628d63136'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Quel est le seuil légal d’alcoolémie pour un conducteur expérimenté ?', 'mcq', '["0,2 g/L de sang","0,5 g/L de sang","0,8 g/L de sang","1 g/L de sang"]'::jsonb, 1, 'Soit 0,25 mg par litre d’air expiré.', 5),
    ('2edaf75e-f885-5132-bb2b-f0b544fe388a'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Le rancissement hydrolytique du beurre est dû :', 'mcq', '["À l’hydrolyse des triglycérides","À la photosynthèse","À la congélation","À la fermentation du glucose en éthanol"]'::jsonb, 0, 'Elle libère des acides gras à l’odeur forte.', 6),
    ('d257b57c-2720-56e9-ad50-3fafb150bb04'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Quel procédé de conservation est chimique ?', 'mcq', '["La congélation","La pasteurisation","L’ajout d’un conservateur","La lyophilisation"]'::jsonb, 2, 'Les autres agissent par le froid, la chaleur ou l’élimination de l’eau.', 7),
    ('ff35dd9d-ce76-5a98-a13c-06fb6ee6461f'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Le brunissement d’une pomme coupée nécessite du dioxygène.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une enzyme oxyde les polyphénols grâce au dioxygène de l’air.', 8),
    ('82ab3b37-6c01-50a2-88c9-d44c2ba03d5b'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Que représente 1 °D (degré Dornic) ?', 'mcq', '["1 g de lactose par litre","0,1 g d’acide lactique par litre","1 mg de calcium par litre","10 g de protéines par litre"]'::jsonb, 1, 'Un lait frais titre environ 15 à 18 °D.', 9),
    ('e95cf894-2787-52d1-86f5-6f09cb34caeb'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'La DJA d’un additif est de 40 mg/kg/jour. Quelle dose maximale pour un adulte de 60 kg ?', 'mcq', '["40 mg","240 mg","2 400 mg","6 000 mg"]'::jsonb, 2, '40 × 60 = 2 400 mg par jour.', 10),
    ('a0cb5ca9-ae66-5871-a7cf-8c8bf5264e60'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Quelle différence y a-t-il entre DJA et DJT ?', 'mcq', '["Aucune","La DJA concerne une substance ajoutée volontairement, la DJT un contaminant","La DJT concerne les additifs, la DJA les contaminants","La DJA s’exprime en litres"]'::jsonb, 1, 'Toutes deux s’expriment en mg par kg de masse corporelle et par jour.', 11),
    ('9efb52b8-71d4-5cae-818b-be9c886ed39e'::uuid, '2df1b801-9b20-5114-a43b-fbe18c18b2fa'::uuid, 'Pourquoi le lait caille-t-il ?', 'mcq', '["Parce que la lumière oxyde ses vitamines","Parce que des bactéries transforment le lactose en acide lactique","Parce que le froid le coagule","Parce que l’eau s’évapore"]'::jsonb, 1, 'L’acidité fait coaguler les protéines du lait.', 12),
    ('76246ef7-8239-5b3d-8591-7c37d83705da'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Pourquoi les composés ioniques se dissolvent-ils bien dans l’eau ?', 'mcq', '["Parce que l’eau est apolaire","Parce que l’eau est polaire et hydrate les ions","Parce que les ions sont neutres","Parce que l’eau est un métal"]'::jsonb, 1, 'Les pôles de la molécule d’eau attirent les ions et les entourent.', 1),
    ('a7a4702b-b17a-5a29-9d7a-529cf29e709e'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Quelle eau a la conductivité la plus élevée ?', 'mcq', '["L’eau pure","L’eau distillée","L’eau de mer","L’eau déminéralisée"]'::jsonb, 2, 'Elle contient beaucoup d’ions sodium et chlorure.', 2),
    ('9cbd623d-acb2-52f7-afd8-7ffe54ce716b'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Comment repère-t-on l’équivalence d’un dosage conductimétrique ?', 'mcq', '["Au changement de couleur","Au changement de pente de la courbe σ = f(V)","Au dégagement gazeux","À la température maximale"]'::jsonb, 1, 'À l’équivalence, les réactifs ont été introduits dans les proportions de l’équation.', 3),
    ('96d9dbb2-d31e-5df3-95b1-8a17b8872864'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Quel est le pourcentage molaire du dioxygène dans l’air ?', 'mcq', '["Environ 78 %","Environ 21 %","Environ 1 %","Environ 0,04 %"]'::jsonb, 1, 'Le diazote représente environ 78 %.', 4),
    ('97849326-b1e9-59d5-bafa-fbd943d1ae65'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Quel test met en évidence le dioxyde de carbone ?', 'mcq', '["Le sulfate de cuivre anhydre","L’eau de chaux qui se trouble","La bûchette incandescente","Le papier pH"]'::jsonb, 1, 'Le sulfate de cuivre anhydre détecte l’eau ; la bûchette, le dioxygène.', 5),
    ('0996436a-1a9a-54ce-9f18-f36a05ca6933'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Dans la loi P × V = n × R × T, la température s’exprime en :', 'mcq', '["Degrés Celsius","Kelvins","Degrés Fahrenheit","Pascals"]'::jsonb, 1, 'T (K) = θ (°C) + 273.', 6),
    ('235855b6-1082-5b7b-90db-0af301b3a90e'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Pourquoi le monoxyde de carbone est-il dangereux ?', 'mcq', '["Il détruit les globules blancs","Il se fixe sur l’hémoglobine bien plus fortement que le dioxygène","Il acidifie l’estomac","Il bouche les artères"]'::jsonb, 1, 'Le sang transporte alors moins d’oxygène aux tissus.', 7),
    ('aa801b69-8695-50b9-b5e0-054d10bcdba2'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'L’ozone est toujours bénéfique pour la santé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Protecteur dans la stratosphère, il est un polluant irritant près du sol.', 8),
    ('9006227c-25bb-5f85-8d44-13f6e00f3d99'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'L’ozone près du sol est un polluant :', 'mcq', '["Primaire","Secondaire","Radioactif","Macropolluant"]'::jsonb, 1, 'Il se forme dans l’atmosphère à partir d’autres polluants sous l’effet du soleil.', 9),
    ('d1244e35-c4c7-521e-9ad6-dc4b1eaf0025'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Quel procédé retient des polluants à la surface d’un solide ?', 'mcq', '["L’oxydation par l’ozone","L’adsorption sur charbon actif","La distillation","La saponification"]'::jsonb, 1, 'Le charbon actif présente une surface immense.', 10),
    ('3cb522a2-337c-5aed-bf26-ff8fab7c20f0'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Quelle différence entre eau distillée et eau déminéralisée ?', 'mcq', '["Aucune","L’eau déminéralisée peut encore contenir des molécules neutres et des micro-organismes","L’eau distillée contient plus d’ions","L’eau déminéralisée est salée"]'::jsonb, 1, 'Les résines échangeuses d’ions ne retiennent que les ions.', 11),
    ('87b51ff2-78d5-56e3-b259-91baa13cc8e6'::uuid, '0c30b5b1-aa5a-5853-82ad-9db0e8b7a865'::uuid, 'Un pesticide actif à quelques microgrammes par litre est un :', 'mcq', '["Macropolluant","Micropolluant","Gaz à effet de serre","Oligoélément"]'::jsonb, 1, 'Les micropolluants agissent à très faible concentration.', 12),
    ('281dfcc2-2a98-5467-a0b5-9c74d962b34d'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Quelle différence y a-t-il entre un ultrason et une onde électromagnétique ?', 'mcq', '["L’ultrason se propage dans le vide","L’ultrason est une onde mécanique qui a besoin d’un milieu matériel","Ils ont la même vitesse","L’onde électromagnétique ne se propage pas dans le vide"]'::jsonb, 1, 'Les ondes électromagnétiques, elles, se propagent aussi dans le vide.', 1),
    ('6ee00dda-9d8b-5768-ac5b-4c3ee51ed97e'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Un écho revient 260 µs après l’émission dans un tissu où v = 1 540 m/s. À quelle profondeur est l’interface ?', 'mcq', '["Environ 10 cm","Environ 20 cm","Environ 40 cm","Environ 2 cm"]'::jsonb, 1, 'd = 1 540 × 260 × 10⁻⁶ ÷ 2 ≈ 0,20 m.', 2),
    ('b9a05e54-a8ad-5d67-b395-ac630c66eb34'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Que mesure l’échographie Doppler ?', 'mcq', '["La densité des os","La vitesse et le sens de circulation du sang","La radioactivité d’un organe","La glycémie"]'::jsonb, 1, 'Le changement de fréquence de l’onde réfléchie dépend de la vitesse des globules rouges.', 3),
    ('35ad6fd4-4aff-5fc8-8b45-f88db2ffb389'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Pourquoi les os apparaissent-ils blancs sur une radiographie ?', 'mcq', '["Ils émettent de la lumière","Ils absorbent fortement les rayons X","Ils laissent passer les rayons X","Ils contiennent de l’air"]'::jsonb, 1, 'Le calcium a un numéro atomique plus élevé que les éléments des tissus mous.', 4),
    ('443026cc-6d67-5e4a-9e03-f7c8e2125a65'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Quelle technique d’imagerie n’utilise aucun rayonnement ionisant ?', 'mcq', '["La radiographie","Le scanner","L’IRM","La scintigraphie"]'::jsonb, 2, 'Elle utilise un champ magnétique et des radiofréquences.', 5),
    ('539b018b-f83f-5215-aaac-5f0744c44276'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Quelle relation relie longueur d’onde et fréquence ?', 'mcq', '["λ = c × f","λ = c ÷ f","λ = f ÷ c","λ = c + f"]'::jsonb, 1, 'c = 3,00 × 10⁸ m/s dans le vide.', 6),
    ('252a8f64-973e-5d3e-b910-f3b08c6df239'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Qu’émet un noyau lors d’une désintégration β⁺ ?', 'mcq', '["Un électron","Un positon","Un noyau d’hélium","Un neutron"]'::jsonb, 1, 'Les positons sont à la base de la TEP.', 7),
    ('10f7ac59-1f82-5f43-9ee8-0028c2f55d73'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'La période d’un radio-isotope est de 6 h. Quelle fraction reste-t-il après 24 h ?', 'mcq', '["1/4","1/8","1/16","1/2"]'::jsonb, 2, '24 h = 4 périodes : (1/2)⁴ = 1/16.', 8),
    ('dfa6d487-3e12-565f-876e-bc7db35d8763'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'En quelle unité s’exprime l’activité d’une source radioactive ?', 'mcq', '["Le sievert","Le becquerel","Le hertz","Le pascal"]'::jsonb, 1, '1 Bq = une désintégration par seconde ; le sievert mesure la dose.', 9),
    ('34a31453-5c2f-5819-b70e-b27fa820964d'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Deux isotopes ont le même nombre de protons.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils diffèrent par leur nombre de neutrons.', 10),
    ('1e9a0abe-c7ac-5ff6-b63c-d54a178650ed'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Quel critère guide le choix d’un produit de contraste ?', 'mcq', '["Sa couleur","Sa durée d’élimination par l’organisme","Son goût","Son prix uniquement"]'::jsonb, 1, 'On cherche aussi l’efficacité et la tolérance.', 11),
    ('62ead5c3-48d6-5149-8c74-194b824c28b8'::uuid, '91cd3380-a062-5f78-8d76-d9a1b5f8bde1'::uuid, 'Quelle précaution protège le personnel d’une source radioactive ?', 'mcq', '["Se rapprocher de la source","Augmenter la durée d’exposition","Utiliser des écrans de plomb et augmenter la distance","Retirer son dosimètre"]'::jsonb, 2, 'Durée courte, distance, écrans : les trois règles de la radioprotection.', 12),
    ('3d1a68a0-6436-5131-b3cb-9a39cd463cb7'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Quelle est l’équation de dissolution du chlorure de calcium CaCl₂ ?', 'mcq', '["CaCl₂ → Ca⁺ + Cl₂⁻","CaCl₂ → Ca²⁺ + 2 Cl⁻","CaCl₂ → Ca²⁺ + Cl⁻","CaCl₂ → Ca + Cl₂"]'::jsonb, 1, 'L’électroneutralité impose deux ions chlorure pour un ion calcium.', 1),
    ('ec2231a9-5d93-5e3a-bba0-192361d6c568'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Quelle relation relie concentration en masse et concentration en quantité de matière ?', 'mcq', '["Cm = C × M","Cm = C ÷ M","Cm = n × V","Cm = M ÷ C"]'::jsonb, 0, 'M est la masse molaire du soluté, en g/mol.', 2),
    ('863ace86-c52a-5199-a10e-4286e42f9728'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Quelle masse de glucose faut-il pour préparer 250 mL à 20 g/L ?', 'mcq', '["5 g","20 g","80 g","0,5 g"]'::jsonb, 0, 'm = Cm × V = 20 × 0,250 = 5 g.', 3),
    ('eb85ef7e-8a62-5691-82dc-a791e597fe18'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'On dilue une solution 10 fois. Quel volume de solution mère faut-il pour 50 mL de solution fille ?', 'mcq', '["5 mL","10 mL","50 mL","500 mL"]'::jsonb, 0, 'V(mère) = V(fille) ÷ F = 50 ÷ 10 = 5 mL.', 4),
    ('96b1320e-dfa3-530d-b887-6cbcb21598c1'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Que dit la loi de Beer-Lambert ?', 'mcq', '["L’absorbance est proportionnelle à la concentration","L’absorbance est inversement proportionnelle à la concentration","La couleur ne dépend pas de la concentration","La concentration dépend de la température seulement"]'::jsonb, 0, 'Elle fonde le dosage par étalonnage.', 5),
    ('6d6e30d6-732d-5ec1-a3d4-aa23e2f7e383'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'À quelle longueur d’onde règle-t-on le spectrophotomètre ?', 'mcq', '["À celle où l’absorbance est maximale","À celle où l’absorbance est nulle","Toujours à 800 nm","N’importe laquelle"]'::jsonb, 0, 'La mesure y est la plus précise.', 6),
    ('611f95dc-adb7-50dd-9c1b-cbe37be6d122'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Une solution paraît bleue. Quelle couleur absorbe-t-elle surtout ?', 'mcq', '["Le bleu","L’orange","Le vert","Le violet"]'::jsonb, 1, 'La couleur perçue est la complémentaire de la couleur absorbée.', 7),
    ('06f92768-7949-5968-a3bf-8c59fc4784fc'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Une glycémie à jeun de 0,90 g/L est dans les valeurs de référence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’intervalle usuel à jeun est de 0,70 à 1,10 g/L.', 8),
    ('4c8ca7a6-1c25-5458-b0d2-0972e35839e9'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Pourquoi l’eau de pluie non polluée est-elle légèrement acide ?', 'mcq', '["À cause du dioxyde de carbone dissous","À cause du sel","À cause de l’ozone","Elle ne l’est pas"]'::jsonb, 0, 'Le couple CO₂,H₂O / HCO₃⁻ explique un pH voisin de 5,6.', 9),
    ('d34ede4a-695b-53a8-a32f-7ef363204c33'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Quelle conséquence a l’acidification des océans ?', 'mcq', '["Les coraux construisent plus vite leur squelette","Les organismes à coquille calcaire ont du mal à la former","La mer devient basique","Le sel disparaît"]'::jsonb, 1, 'Les ions carbonate deviennent moins disponibles.', 10),
    ('a3d605bc-bb8a-55c5-8ede-ddc7e85ffb43'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Qu’est-ce que la bioaccumulation ?', 'mcq', '["L’élimination rapide d’un polluant","L’accumulation d’une substance persistante dans les tissus d’un organisme","La production d’énergie par les cellules","La dilution d’un polluant dans la mer"]'::jsonb, 1, 'La substance se concentre ensuite le long de la chaîne alimentaire.', 11),
    ('85ae369f-e87f-5407-a74c-88bb6209e728'::uuid, '3813dcd6-051d-5956-a791-0bdecad86efa'::uuid, 'Le sérum physiologique contient 9 g/L de NaCl (M = 58,5 g/mol). Quelle est sa concentration en quantité de matière ?', 'mcq', '["Environ 0,15 mol/L","Environ 1,5 mol/L","Environ 9 mol/L","Environ 526 mol/L"]'::jsonb, 0, 'C = Cm ÷ M = 9 ÷ 58,5 ≈ 0,15 mol/L.', 12),
    ('e288a7b1-de25-53d4-b869-9908e9f727e9'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Qu’est-ce qu’un acide α-aminé ?', 'mcq', '["Une molécule portant les groupes amine et carboxyle sur le même carbone","Un acide gras insaturé","Un sucre simple","Un ion minéral"]'::jsonb, 0, 'Formule générale H₂N–CH(R)–COOH.', 1),
    ('dd724e4f-7ecc-50aa-ac11-40b21b68fe46'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Un carbone asymétrique est lié à :', 'mcq', '["Deux groupes identiques","Quatre groupes différents","Trois atomes d’oxygène","Une double liaison"]'::jsonb, 1, 'Sa présence rend la molécule chirale.', 2),
    ('22f366b4-5eee-5139-a157-cb84fa944eb8'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Quel acide aminé n’est pas chiral ?', 'mcq', '["L’alanine","La glycine","La valine","La leucine"]'::jsonb, 1, 'Sa chaîne latérale est un simple atome d’hydrogène.', 3),
    ('4d959b1a-b47f-542a-81a3-2d07beab8127'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'En représentation de Fischer (–COOH en haut), l’acide aminé L a son groupe –NH₂ :', 'mcq', '["À droite","À gauche","En haut","En bas"]'::jsonb, 1, 'Les protéines humaines sont faites d’acides aminés L.', 4),
    ('0e8390e8-73f5-5894-9385-2343cbbb4fe4'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Comment se forme une liaison peptidique ?', 'mcq', '["Par condensation avec élimination d’eau","Par hydrolyse","Par oxydation","Par saponification"]'::jsonb, 0, 'Le –COOH de l’un réagit avec le –NH₂ de l’autre.', 5),
    ('bb138287-44cf-5836-98d6-50ef412dae8b'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Combien de dipeptides différents peut-on former avec deux acides aminés différents, en comptant les associations d’un acide aminé avec lui-même ?', 'mcq', '["2","3","4","6"]'::jsonb, 2, 'Par exemple Gly-Gly, Gly-Ala, Ala-Gly et Ala-Ala.', 6),
    ('d8e975b8-24b7-5dde-9e3d-0462a669aa8b'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'La structure primaire d’une protéine correspond :', 'mcq', '["À son repliement dans l’espace","À la séquence de ses acides aminés","À l’association de plusieurs chaînes","À sa couleur"]'::jsonb, 1, 'Elle détermine les repliements des niveaux suivants.', 7),
    ('1d07b927-0f6e-51c8-a008-00c2094d081c'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Un acide gras saturé ne possède aucune double liaison C=C.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les acides gras insaturés en ont une ou plusieurs.', 8),
    ('931ceaec-a169-5464-b3ad-8eeb82984a92'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Un triglycéride est formé à partir :', 'mcq', '["De glucose et d’acides aminés","De glycérol et de trois acides gras","De cholestérol et d’eau","De trois glycérols"]'::jsonb, 1, 'C’est un triester.', 9),
    ('25bfba1e-4795-5336-9e35-0842398e04d6'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Quels sont les produits de la saponification d’un triglycéride par la soude ?', 'mcq', '["Du glycérol et des ions carboxylate (savon)","Du glucose et de l’eau","Des acides aminés","Du cholestérol"]'::jsonb, 0, 'La réaction est totale et se fait à chaud.', 10),
    ('6e8d8be1-2f23-574b-ab38-ead003546ecd'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'On attend au plus 3,0 mol de savon et on en obtient 2,4 mol. Quel est le rendement ?', 'mcq', '["24 %","60 %","80 %","125 %"]'::jsonb, 2, 'Rendement = 2,4 ÷ 3,0 = 0,80.', 11),
    ('d265b3b9-94b1-57f9-81e2-246d9702520e'::uuid, 'fd49042f-f20b-5446-9f63-08de40da45ac'::uuid, 'Pourquoi le cholestérol circule-t-il dans le sang lié à des lipoprotéines ?', 'mcq', '["Parce qu’il est très soluble dans l’eau","Parce qu’il est presque insoluble dans l’eau","Parce qu’il est un ion","Parce qu’il est gazeux"]'::jsonb, 1, 'Les LDL le portent vers les tissus, les HDL vers le foie.', 12),
    ('d570728a-1bd2-5c9a-9da0-d47573b76ad8'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Pourquoi faut-il des apports quotidiens de vitamine C ?', 'mcq', '["Parce qu’elle est liposoluble et stockée","Parce qu’elle est hydrosoluble et peu stockée","Parce qu’elle est fabriquée par la peau","Parce qu’elle est toxique"]'::jsonb, 1, 'L’excès est éliminé dans les urines.', 1),
    ('af0c6894-2a97-54fa-be59-06d24bdacbb3'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Quelle vitamine est liposoluble ?', 'mcq', '["La vitamine C","La vitamine A","La vitamine B9","La vitamine B1"]'::jsonb, 1, 'Les vitamines A, D, E et K sont liposolubles.', 2),
    ('5e1b5d1f-9d53-5fba-ad7d-818ffa3d134a'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Quelle maladie est due à une carence en vitamine D ?', 'mcq', '["Le scorbut","Le rachitisme","Le diabète","L’anémie"]'::jsonb, 1, 'La vitamine D permet la fixation du calcium dans les os.', 3),
    ('8db9bcb2-6642-50d1-be5c-c666ff16e9b3'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Lors du titrage de la vitamine C par le diiode, comment repère-t-on l’équivalence ?', 'mcq', '["L’empois d’amidon bleuit quand le diiode est en excès","La solution devient rouge","Un gaz se dégage","La température chute"]'::jsonb, 0, 'Tant qu’il reste de la vitamine C, le diiode est consommé.', 4),
    ('b512ee1d-ab7a-522b-9852-b95a6fb03426'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Les oligoéléments sont nécessaires :', 'mcq', '["En très grandes quantités","En très petites quantités","Seulement chez l’enfant","Jamais"]'::jsonb, 1, 'Fer, zinc, cuivre, iode, sélénium…', 5),
    ('47db5b0f-5812-56ff-bc9e-682f83d4b42d'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Quelle est la valeur de référence de la natrémie ?', 'mcq', '["3,5 à 5,0 mmol/L","135 à 145 mmol/L","0,70 à 1,10 g/L","60 à 80 g/L"]'::jsonb, 1, '3,5 à 5,0 mmol/L est la valeur de la kaliémie.', 6),
    ('01815d25-b920-5548-9c94-790245916a34'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Les additifs numérotés E200 à E299 sont des :', 'mcq', '["Colorants","Conservateurs","Antioxydants","Texturants"]'::jsonb, 1, 'Ils limitent le développement des micro-organismes.', 7),
    ('176c476d-8ed5-54a8-81ac-cc5f53ba4f56'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Une vanilline de synthèse identique à la vanilline naturelle a les mêmes propriétés.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la même molécule ; l’extrait naturel contient en plus d’autres molécules.', 8),
    ('9d6609ec-41d9-53d0-957a-2275d3c8bb83'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'De quelle plante dérive l’aspirine ?', 'mcq', '["Du pavot","Du saule","De l’if","De la digitale"]'::jsonb, 1, 'Elle dérive de la salicine de l’écorce de saule.', 9),
    ('c219eb9a-fed2-5299-b419-a9ebb695f951'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Qui a découvert la pénicilline en 1928 ?', 'mcq', '["Louis Pasteur","Alexander Fleming","Marie Curie","Robert Koch"]'::jsonb, 1, 'Elle est produite par une moisissure du genre Penicillium.', 10),
    ('a18a4931-c9e7-5ca5-b2c6-f0c4718f4536'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'L’indice SPF d’une crème solaire mesure surtout la protection contre :', 'mcq', '["Les UVA","Les UVB","Les infrarouges","La lumière visible"]'::jsonb, 1, 'Un logo spécifique signale la protection contre les UVA.', 11),
    ('80ae2060-9c9b-5510-b678-2fb9811ba46d'::uuid, '02d6531c-bf21-50ac-9230-944a8351a4f9'::uuid, 'Quel est le rôle d’un antioxydant dans un cosmétique solaire ?', 'mcq', '["Retenir l’eau dans la peau","Neutraliser les radicaux libres produits par les UV","Colorer la peau","Parfumer"]'::jsonb, 1, 'Retenir l’eau est le rôle d’un actif hydratant.', 12),
    ('88438651-3827-57f0-b18b-8b386bc5eec8'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Quelle part de la masse d’un adulte représente l’eau ?', 'mcq', '["Environ 20 %","Environ 40 %","Environ 60 %","Environ 90 %"]'::jsonb, 2, 'Deux tiers de cette eau sont dans les cellules.', 1),
    ('d7fec62b-2c1e-5a92-8ee7-549a29bf486b'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Le milieu intérieur correspond :', 'mcq', '["Au liquide intracellulaire","Au liquide extracellulaire (plasma, liquide interstitiel, lymphe)","Au contenu de l’intestin","À l’urine"]'::jsonb, 1, 'C’est le milieu dans lequel baignent les cellules.', 2),
    ('4affa145-001b-5194-9464-3949d36451be'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Quelle est l’unité fonctionnelle du rein ?', 'mcq', '["L’alvéole","Le néphron","Le neurone","L’acinus"]'::jsonb, 1, 'Chaque rein en compte environ un million.', 3),
    ('c2526150-d4fc-5dc6-9ed5-84a3a2c759cc'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Pourquoi l’urine primitive ne contient-elle pas de protéines ?', 'mcq', '["Elles sont détruites","Elles sont trop grosses pour être filtrées par le glomérule","Elles sont réabsorbées","Elles sont sécrétées dans la bile"]'::jsonb, 1, 'La filtration glomérulaire retient les grosses molécules.', 4),
    ('4ac01932-598b-5f73-bfbf-a99db6bdf16d'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Le glucose présent dans l’urine primitive disparaît de l’urine définitive par :', 'mcq', '["Filtration","Réabsorption","Sécrétion","Dégradation"]'::jsonb, 1, 'Normalement, il est réabsorbé en totalité.', 5),
    ('6c11ae9e-4496-5e53-86b4-49504155ae07'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'La concentration de l’urée passe d’environ 0,3 g/L dans le plasma à environ 20 g/L dans l’urine. Pourquoi ?', 'mcq', '["L’urée est fabriquée par le rein","L’eau est massivement réabsorbée alors que l’urée l’est peu","Le rein ajoute du sel","L’urée vient de la vessie"]'::jsonb, 1, 'L’urée est concentrée dans l’urine : c’est un déchet éliminé.', 6),
    ('0106d9d1-d164-5c99-917c-6ced94bcdd5a'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Quel volume de plasma les glomérules filtrent-ils environ par jour ?', 'mcq', '["1,5 L","18 L","180 L","1 800 L"]'::jsonb, 2, 'Plus de 99 % de cette eau est réabsorbée.', 7),
    ('4eadf4f2-cbeb-5ba1-aa68-7a119e81d1b7'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'La présence de glucose dans l’urine est normale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une glycosurie traduit une glycémie trop élevée.', 8),
    ('af64883b-bc80-5b91-8856-69b9633ef001'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Qu’est-ce qu’un xénobiotique ?', 'mcq', '["Une hormone","Une substance étrangère à l’organisme","Un globule blanc","Un ion du plasma"]'::jsonb, 1, 'Médicaments, alcool, pesticides, polluants…', 9),
    ('ef4b2bad-e0e8-5c48-ab1f-5450417bd3f9'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Quel organe transforme principalement les xénobiotiques ?', 'mcq', '["Le cœur","Le foie","La rate","Le poumon"]'::jsonb, 1, 'C’est l’étape du métabolisme.', 10),
    ('8bf96bbf-636e-5668-9152-21e5afa79cc0'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Où les xénobiotiques liposolubles sont-ils surtout stockés ?', 'mcq', '["Dans le tissu adipeux","Dans la vessie","Dans le plasma","Dans les globules rouges"]'::jsonb, 0, 'D’où des relargages lors d’un amaigrissement.', 11),
    ('af63b9ad-0bf9-52a7-aa7a-b679bccb1d71'::uuid, '6787474a-34ab-5f8f-abe5-919b5847b116'::uuid, 'Que désigne la diurèse ?', 'mcq', '["La soif excessive","Le volume d’urine émis en 24 heures","La présence de sang dans l’urine","L’inflammation du rein"]'::jsonb, 1, 'Elle est d’environ 1,5 L chez l’adulte.', 12),
    ('67d8fa1d-1c16-5483-9ade-f1207f47f701'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Quelle hormone fait baisser la glycémie ?', 'mcq', '["Le glucagon","L’insuline","L’adrénaline","La testostérone"]'::jsonb, 1, 'C’est la seule hormone hypoglycémiante.', 1),
    ('81b96515-f8bb-5e2b-9385-2da8df348354'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Quelles cellules sécrètent l’insuline ?', 'mcq', '["Les cellules α des îlots de Langerhans","Les cellules β des îlots de Langerhans","Les hépatocytes","Les globules rouges"]'::jsonb, 1, 'Le glucagon est sécrété par les cellules α.', 2),
    ('f69f4cb5-ce17-546a-9201-9263b12f2093'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'À jeun, comment le foie maintient-il la glycémie ?', 'mcq', '["En stockant du glucose","En dégradant son glycogène et en fabriquant du glucose","En sécrétant de l’insuline","En éliminant le glucose dans la bile"]'::jsonb, 1, 'Glycogénolyse et néoglucogenèse, sous l’effet du glucagon.', 3),
    ('d1197db9-1da0-5021-a909-4984b7806ee2'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Qu’est-ce qu’une hormone ?', 'mcq', '["Une enzyme digestive","Une molécule sécrétée dans le sang qui agit à distance sur des cellules cibles","Un globule blanc","Un nerf"]'::jsonb, 1, 'Les cellules cibles portent des récepteurs spécifiques.', 4),
    ('a37e58fb-814d-5e8f-bf58-bdc2bf830a3d'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Quel seuil de glycémie à jeun, constaté deux fois, définit le diabète ?', 'mcq', '["1,00 g/L","1,10 g/L","1,26 g/L","2,50 g/L"]'::jsonb, 2, 'Ou une glycémie ≥ 2 g/L à tout moment avec des symptômes.', 5),
    ('d2650f8e-15c4-52cf-b9be-4ca10930ee77'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Quelle est l’origine du diabète de type 1 ?', 'mcq', '["Une insulinorésistance liée au surpoids","La destruction auto-immune des cellules β","Un excès de glucagon","Une infection bactérienne du pancréas"]'::jsonb, 1, 'Le pancréas ne produit plus d’insuline.', 6),
    ('08e3c77c-936e-5a0b-b6a9-ab1de7584866'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Quel traitement est indispensable dans le diabète de type 1 ?', 'mcq', '["Le régime seul","L’insuline","Les antibiotiques","Le glucagon quotidien"]'::jsonb, 1, 'Il est nécessaire à vie.', 7),
    ('f4f9f997-83b8-545d-b9e7-27b1f01a797d'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Le diabète de type 2 est en grande partie évitable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Activité physique, poids et alimentation réduisent fortement le risque.', 8),
    ('b3d3eddd-f15b-5886-a294-0f7915db9680'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Pourquoi une hyperglycémie provoque-t-elle une polyurie ?', 'mcq', '["Parce que le glucose dans l’urine entraîne de l’eau","Parce que le rein fabrique de l’eau","Parce que l’insuline est diurétique","Parce que le patient boit moins"]'::jsonb, 0, 'Glycosurie puis polyurie, déshydratation et polydipsie.', 9),
    ('1ee836cf-01b2-55d6-b293-c2115451258e'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Que reflète l’hémoglobine glyquée (HbA1c) ?', 'mcq', '["La glycémie de l’instant","La glycémie moyenne des trois derniers mois","La quantité d’insuline","Le taux de cholestérol"]'::jsonb, 1, 'C’est l’examen de suivi de l’équilibre du diabète.', 10),
    ('9bed04ec-6d14-5302-91b9-5cc5b50263df'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Un diabétique traité a des sueurs et des tremblements. Que faut-il suspecter ?', 'mcq', '["Une hypoglycémie","Une hyperglycémie","Une grippe","Une allergie"]'::jsonb, 0, 'Il faut resucrer immédiatement.', 11),
    ('b24c47cf-7cf2-5810-9ce5-483d82329493'::uuid, '54d7552e-3147-5e99-9eac-b866158ee70a'::uuid, 'Lequel est un signe paraclinique ?', 'mcq', '["La soif intense","La fatigue","Une glycémie à 2,3 g/L","L’amaigrissement"]'::jsonb, 2, 'Un signe paraclinique est un résultat d’examen.', 12),
    ('a04548e7-70e6-57c6-8add-c5691cc08c53'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Quelle différence fondamentale sépare une bactérie d’un virus ?', 'mcq', '["La bactérie est une cellule, le virus n’en est pas une","Le virus est plus gros","La bactérie ne se reproduit pas","Le virus a une paroi"]'::jsonb, 0, 'Le virus ne se reproduit que dans une cellule hôte.', 1),
    ('3e93929f-094b-596d-a763-9b1a27f54a6a'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Comment se reproduit une bactérie ?', 'mcq', '["Dans une cellule hôte","Par division : une bactérie en donne deux","Par méiose","Par bourgeonnement viral"]'::jsonb, 1, 'Dans de bonnes conditions, parfois toutes les 20 minutes.', 2),
    ('e6f20e7b-ddf9-5a32-ab0f-0950b3d7c150'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Pourquoi les antibiotiques sont-ils inefficaces contre les virus ?', 'mcq', '["Les virus sont trop rapides","Les virus n’ont ni paroi, ni ribosome, ni métabolisme propre","Les antibiotiques sont détruits par le foie","Les virus sont trop gros"]'::jsonb, 1, 'Les antibiotiques visent des structures bactériennes.', 3),
    ('4cbdf236-5621-5cd2-b85f-13e056173e9a'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Quelle est la première étape d’un cycle viral ?', 'mcq', '["La libération des virus","La fixation sur un récepteur de la cellule cible","L’assemblage","La réplication"]'::jsonb, 1, 'Le virus reconnaît spécifiquement ses cellules cibles.', 4),
    ('b28bff67-d25d-5bdc-bc87-dd6220fec83c'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Quelle structure les pénicillines ciblent-elles ?', 'mcq', '["Les ribosomes","La paroi bactérienne","Le noyau","La capside virale"]'::jsonb, 1, 'Ce sont des bêta-lactamines.', 5),
    ('c13088e8-3d36-506b-8ee2-47f71923b37b'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Que signifie une grande zone d’inhibition autour d’un disque d’antibiotique ?', 'mcq', '["La bactérie est résistante","La bactérie est sensible à cet antibiotique","L’antibiotique est périmé","Il n’y a pas de bactérie"]'::jsonb, 1, 'On compare son diamètre aux valeurs critiques.', 6),
    ('ec5b0bc0-cab0-5156-ba21-369be3a9afb8'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Une résistance acquise peut provenir :', 'mcq', '["D’une mutation ou d’un transfert de gènes","D’une vaccination","D’un excès de vitamines","D’une allergie"]'::jsonb, 0, 'Les gènes de résistance sont souvent portés par des plasmides.', 7),
    ('1a51a48a-5bfd-5d41-9b97-64871b37ef68'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Prendre un antibiotique contre une grippe est utile pour guérir plus vite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La grippe est virale : l’antibiotique est inutile et favorise les résistances.', 8),
    ('53cfe628-deb0-5177-a549-cf1f09af8c87'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Comment l’usage des antibiotiques favorise-t-il les souches résistantes ?', 'mcq', '["Il crée des mutations dirigées","Il élimine les bactéries sensibles et laisse les résistantes se multiplier","Il renforce toutes les bactéries","Il n’a aucun effet"]'::jsonb, 1, 'C’est un phénomène de sélection.', 9),
    ('fd06d568-cc59-53af-91ee-87cebde907ea'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Quel agent pathogène cause le paludisme ?', 'mcq', '["Une bactérie","Un virus","Un parasite protozoaire","Un prion"]'::jsonb, 2, 'Il est transmis par la piqûre d’un moustique.', 10),
    ('e46c08a8-33d5-56f1-a702-47a21df2cea7'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'Qu’est-ce qu’une infection nosocomiale ?', 'mcq', '["Une infection contractée dans un établissement de santé","Une infection du nez","Une infection héréditaire","Une maladie des animaux"]'::jsonb, 0, 'L’hygiène des mains en est la première prévention.', 11),
    ('14a4ada0-63d8-59ae-9975-889d711d91af'::uuid, 'f1094053-2426-5d38-8820-39675481f57c'::uuid, 'À quoi sert un antibiogramme ?', 'mcq', '["À compter les globules blancs","À choisir l’antibiotique efficace contre la bactérie du patient","À dépister un cancer","À mesurer la glycémie"]'::jsonb, 1, 'Il évite un traitement inutile.', 12),
    ('74ad9ee8-5736-5ae6-b13e-a7d344f97d38'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Où trouve-t-on les molécules du CMH de classe I ?', 'mcq', '["Seulement sur les globules rouges","À la surface de toutes les cellules nucléées","Uniquement dans le thymus","Dans le plasma"]'::jsonb, 1, 'Ce sont des marqueurs du soi.', 1),
    ('f1020447-b3db-5847-a55d-7f9d358efab7'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Qu’est-ce qu’un épitope ?', 'mcq', '["Un globule blanc","La partie d’un antigène effectivement reconnue","Un organe lymphoïde","Un anticorps"]'::jsonb, 1, 'On parle aussi de déterminant antigénique.', 2),
    ('b25780c3-f6d4-59c4-bc9e-83e46f952437'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Quels sont les organes lymphoïdes primaires ?', 'mcq', '["La rate et les ganglions","La moelle osseuse rouge et le thymus","Les amygdales et le foie","Le cœur et les poumons"]'::jsonb, 1, 'Les lymphocytes y sont produits et y acquièrent leur maturité.', 3),
    ('93313846-d2cd-5836-a327-357ad483c2f0'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Dans quel organe les lymphocytes T acquièrent-ils leur maturité ?', 'mcq', '["La rate","Le thymus","Le foie","Le rein"]'::jsonb, 1, 'D’où leur nom : T comme thymus.', 4),
    ('eac2277e-2d02-555a-883c-f18f199615c3'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Quelle est la valeur normale des leucocytes chez l’adulte ?', 'mcq', '["4 000 à 10 000 par mm³","150 000 à 400 000 par mm³","4 à 5,5 millions par mm³","100 à 500 par mm³"]'::jsonb, 0, 'Les autres valeurs sont celles des plaquettes et des hématies.', 5),
    ('005f072f-f8c2-58a4-90f5-86f35747b88c'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Quels sont les quatre symptômes de la réaction inflammatoire ?', 'mcq', '["Rougeur, chaleur, gonflement, douleur","Fièvre, toux, nausée, vertige","Pâleur, froid, raideur, démangeaison","Soif, faim, fatigue, sommeil"]'::jsonb, 0, 'Ils s’expliquent par des phénomènes vasculaires et cellulaires.', 6),
    ('489934cc-69e8-5b3d-af8c-478cb3f3b451'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Qu’est-ce qui explique l’œdème de l’inflammation ?', 'mcq', '["La vasoconstriction","L’augmentation de la perméabilité des capillaires","La destruction des globules rouges","La baisse de la température"]'::jsonb, 1, 'Du plasma passe dans les tissus.', 7),
    ('0b6ee651-7f13-5707-8f23-8f50cda1ca41'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Dans quel ordre se déroule la phagocytose ?', 'mcq', '["Digestion, adhésion, ingestion","Adhésion, ingestion, digestion","Ingestion, adhésion, digestion","Adhésion, digestion, ingestion"]'::jsonb, 1, 'Puis rejet des débris et présentation de l’antigène.', 8),
    ('5f0174e4-ed47-5362-a087-f8014c6daa9b'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'L’immunité innée est spécifique d’un antigène précis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est rapide et non spécifique.', 9),
    ('885693a8-3590-5573-8240-b1c298e1e58d'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Comment le virus de la grippe se transmet-il ?', 'mcq', '["Par voie respiratoire et par les mains","Par piqûre de moustique","Par l’eau uniquement","Par voie sexuelle uniquement"]'::jsonb, 0, 'Il infecte les cellules épithéliales des voies respiratoires.', 10),
    ('5f56b91d-8398-5fbb-8195-f0631e4b87ed'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Quel terme médical désigne une fatigue intense ?', 'mcq', '["Asthénie","Polydipsie","Diurèse","Mycose"]'::jsonb, 0, 'C’est un symptôme classique de la grippe.', 11),
    ('f7b92c93-85e5-5e3f-ac3a-a0261a7c7f0b'::uuid, 'ae605934-f4ca-50d0-b567-31c6a5bb1a5d'::uuid, 'Le lysozyme des larmes est une défense :', 'mcq', '["Mécanique","Chimique","Adaptative","Hormonale"]'::jsonb, 1, 'Cette enzyme détruit la paroi de certaines bactéries.', 12),
    ('931c073f-cbad-51d4-aa1c-fb36bc771e3b'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Quel lymphocyte joue un rôle central en activant les réponses humorale et cellulaire ?', 'mcq', '["Le lymphocyte B","Le lymphocyte T4 (auxiliaire)","Le plasmocyte","Le polynucléaire neutrophile"]'::jsonb, 1, 'Il sécrète des interleukines qui activent LB et LT8.', 1),
    ('4cf61be8-3777-58d0-9c39-61413dfd6baf'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'En quelles cellules se différencient les lymphocytes B activés ?', 'mcq', '["En LT cytotoxiques","En plasmocytes et en lymphocytes B mémoire","En macrophages","En globules rouges"]'::jsonb, 1, 'Les plasmocytes sécrètent les anticorps.', 2),
    ('1b042b77-a76e-5416-91c0-b527610c40bb'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Pourquoi le réticulum endoplasmique granuleux est-il très développé dans un plasmocyte ?', 'mcq', '["Parce qu’il produit de l’énergie","Parce que le plasmocyte fabrique et exporte des anticorps en grande quantité","Parce qu’il stocke des graisses","Parce qu’il se divise souvent"]'::jsonb, 1, 'Le Golgi, très développé lui aussi, assure l’exportation.', 3),
    ('89440583-79cc-51b3-8ada-a2adc3c95641'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Où se situent les paratopes d’une immunoglobuline G ?', 'mcq', '["Au pied du Y","À l’extrémité des deux bras","Au centre de la molécule","Dans la membrane du lymphocyte uniquement"]'::jsonb, 1, 'Ils sont formés par les parties variables des chaînes.', 4),
    ('2d524948-dc5f-598a-aa67-7355ef473443'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Qu’est-ce que l’opsonisation ?', 'mcq', '["La destruction d’un anticorps","La facilitation de la phagocytose grâce à la fixation du phagocyte sur l’anticorps","La production de fièvre","La division des lymphocytes"]'::jsonb, 1, 'Le phagocyte s’accroche au fragment constant de l’anticorps.', 5),
    ('7d725cfb-2fbb-5611-8baa-4e68433f0e21'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Quelle cellule reconnaît un fragment d’antigène associé au CMH I sur une cellule infectée ?', 'mcq', '["Le LT4","Le LT8","Le lymphocyte B","L’hématie"]'::jsonb, 1, 'Il devient un LT cytotoxique.', 6),
    ('e97ce6dc-6115-582b-8dd6-f21364ae49d6'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Comment le LT cytotoxique élimine-t-il une cellule infectée ?', 'mcq', '["Par phagocytose","Par cytolyse : il perce sa membrane et déclenche sa mort","En sécrétant des anticorps","En la transformant en plasmocyte"]'::jsonb, 1, 'Il atteint ainsi les virus logés dans les cellules.', 7),
    ('e7e217e7-1877-569c-af10-bcea5094ceea'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'La réponse secondaire est plus rapide et plus forte que la réponse primaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Grâce aux cellules mémoire.', 8),
    ('03686a83-110a-510d-9b97-0942bc3495b5'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Sur quel principe repose la vaccination ?', 'mcq', '["Soigner une infection déjà installée","Provoquer une réponse primaire et créer une mémoire immunitaire sans la maladie","Tuer directement les bactéries","Remplacer les globules blancs"]'::jsonb, 1, 'Une vraie infection déclenche alors une réponse secondaire.', 9),
    ('d05e7dd9-63bf-53b5-9ae3-7c0303657bf4'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Pourquoi le vaccin contre la grippe est-il renouvelé chaque année ?', 'mcq', '["Parce que le virus varie","Parce que le vaccin est toxique","Parce que l’immunité ne dure que trois jours","Parce que la grippe est bactérienne"]'::jsonb, 0, 'Les protéines H et N changent d’une saison à l’autre.', 10),
    ('bd152845-79f7-54c8-9dbc-af326849386e'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Au sérodiagnostic, la présence d’IgM spécifiques indique :', 'mcq', '["Une infection ancienne","Une infection récente","Une absence de contact","Une allergie"]'::jsonb, 1, 'Des IgG seules évoquent une infection ancienne ou une vaccination.', 11),
    ('4735d32b-ce42-56a4-a1e0-1d1109f030c4'::uuid, '9209610d-70f0-5693-8231-7616f7db2b8b'::uuid, 'Une forte augmentation des polynucléaires neutrophiles oriente vers :', 'mcq', '["Une infection bactérienne","Une anémie","Un diabète","Une infection virale seulement"]'::jsonb, 0, 'Les lymphocytes augmentent plutôt dans les infections virales.', 12),
    ('19d88dff-b90d-54e8-8960-30cc81b1cb4b'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Quelles cellules du testicule sécrètent la testostérone ?', 'mcq', '["Les spermatozoïdes","Les cellules interstitielles de Leydig","Les cellules de la prostate","Les cellules de l’épididyme"]'::jsonb, 1, 'Elles sont situées entre les tubes séminifères.', 1),
    ('b4d9af72-a90c-5d51-90c3-e695bc4b0271'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Combien de chromosomes contient un gamète humain ?', 'mcq', '["46","23","92","47"]'::jsonb, 1, 'Les gamètes sont haploïdes grâce à la méiose.', 2),
    ('f8a04cd0-c379-53e4-96e1-e5b30d3b69f9'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Où a lieu la fécondation ?', 'mcq', '["Dans l’utérus","Dans le tiers externe de la trompe","Dans l’ovaire","Dans le vagin"]'::jsonb, 1, 'Dans l’ampoule de la trompe.', 3),
    ('dd3bf830-f07f-5e97-af99-4afa8fc82ac5'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Vers quel jour après la fécondation a lieu la nidation ?', 'mcq', '["Le 1er jour","Le 7e jour environ","Le 30e jour","Le 60e jour"]'::jsonb, 1, 'L’embryon s’implante dans l’endomètre.', 4),
    ('bfb9da70-7d7d-5863-ba2e-b1a56e05e24e'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Après l’ovulation, le follicule rompu devient :', 'mcq', '["Un ovocyte I","Le corps jaune","Un spermatocyte","Le placenta"]'::jsonb, 1, 'Il sécrète de la progestérone et des œstrogènes.', 5),
    ('93c2f03f-6db5-5780-af7b-0084f8281fae'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Quand parle-t-on de fœtus plutôt que d’embryon ?', 'mcq', '["Dès la fécondation","Après la fin du deuxième mois","Après la naissance","Seulement au 9e mois"]'::jsonb, 1, 'Les organes sont alors formés : c’est la phase de croissance.', 6),
    ('78013b24-7bba-5ea8-bc30-eaf060b6a7cf'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Au placenta, les sangs maternel et fœtal se mélangent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les échanges se font à travers la paroi des villosités.', 7),
    ('96e57961-328d-58fe-b916-f6d5b065c289'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Quelle substance passe du fœtus vers la mère ?', 'mcq', '["Le dioxygène","Le glucose","L’urée","Les anticorps"]'::jsonb, 2, 'Les déchets du fœtus sont éliminés par l’organisme maternel.', 8),
    ('5793f109-ab30-5d6b-b8cf-2200c12009f8'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Pourquoi recommande-t-on zéro alcool pendant la grossesse ?', 'mcq', '["L’alcool ne passe pas le placenta","L’alcool franchit le placenta et peut provoquer un syndrome d’alcoolisation fœtale","L’alcool protège le fœtus","Seul le vin est dangereux"]'::jsonb, 1, 'C’est la première cause évitable de handicap mental de l’enfant.', 9),
    ('6b008455-0485-5e9f-9c96-8612fcbdd83f'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Quel avantage l’échographie présente-t-elle pour suivre une grossesse ?', 'mcq', '["Elle utilise des rayons X","Elle n’expose pas à un rayonnement ionisant","Elle nécessite une anesthésie","Elle détruit les kystes"]'::jsonb, 1, 'Elle est aussi non invasive et en temps réel.', 10),
    ('c8b70fe9-4ee3-5919-9ab9-78e1e9d2d663'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'À quoi sert l’amniocentèse ?', 'mcq', '["À mesurer la glycémie","À établir le caryotype du fœtus","À déclencher l’accouchement","À vacciner le fœtus"]'::jsonb, 1, 'Elle comporte un faible risque de fausse couche.', 11),
    ('3bc20a94-9bc1-5a71-adf3-227f1167e9d4'::uuid, '0df12a8b-fcf9-5eee-9662-ed06cacf0164'::uuid, 'Comment se repère la trisomie 21 sur un caryotype ?', 'mcq', '["Un chromosome 21 manque","Trois chromosomes 21 sont présents","Le chromosome X est absent","Tous les chromosomes sont doublés"]'::jsonb, 1, 'Le caryotype compte alors 47 chromosomes.', 12),
    ('9846fad5-977a-5a24-9ba9-310912f62794'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Quelle glande sécrète la FSH et la LH ?', 'mcq', '["L’hypothalamus","L’antéhypophyse","L’ovaire","La thyroïde"]'::jsonb, 1, 'Elle est stimulée par la GnRH de l’hypothalamus.', 1),
    ('3576dd13-aa1e-5753-bf8b-61d6c4ed8b4b'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Pourquoi le taux de testostérone reste-t-il à peu près constant ?', 'mcq', '["Grâce à un rétrocontrôle négatif sur l’hypothalamus et l’hypophyse","Grâce à un rétrocontrôle positif","Parce que les testicules ne réagissent à rien","Grâce à l’insuline"]'::jsonb, 0, 'La testostérone freine sa propre stimulation.', 2),
    ('0cac3c17-5095-5548-bfe7-711e0a8f40b0'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Quel événement hormonal déclenche l’ovulation ?', 'mcq', '["La chute de la progestérone","Un pic de LH","La sécrétion d’insuline","La baisse des œstrogènes"]'::jsonb, 1, 'Il est lui-même provoqué par un pic d’œstrogènes (rétrocontrôle positif).', 3),
    ('8c9cd4e3-46a4-53c3-bec8-01b8db756e8e'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Quelle hormone domine pendant la phase lutéale ?', 'mcq', '["La testostérone","La progestérone","Le glucagon","La FSH seule"]'::jsonb, 1, 'Elle est sécrétée par le corps jaune.', 4),
    ('d5de39d7-d1e1-57b0-b433-6ecd7fa1cae1'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Qu’est-ce qui déclenche les règles en l’absence de fécondation ?', 'mcq', '["La régression du corps jaune et la chute des hormones","Un pic de LH","La nidation","L’augmentation de la progestérone"]'::jsonb, 0, 'L’endomètre n’est plus entretenu et se détache.', 5),
    ('6f2f4aa4-f6e9-56df-8c63-b71583cef56b'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Comment agit la pilule œstroprogestative ?', 'mcq', '["Elle tue les spermatozoïdes","Elle bloque l’ovulation par rétrocontrôle négatif","Elle provoque l’ovulation","Elle empêche la fabrication des spermatozoïdes"]'::jsonb, 1, 'Pas de pic de LH, donc pas d’ovulation.', 6),
    ('822cc73c-b831-5380-b2d7-a367e20f74c5'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Quel moyen de contraception protège aussi des infections sexuellement transmissibles ?', 'mcq', '["La pilule","L’implant","Le préservatif","Le stérilet au cuivre"]'::jsonb, 2, 'C’est le seul à empêcher le contact entre muqueuses.', 7),
    ('6be55f18-ff54-50ce-ba26-c3e510d80094'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Jusqu’à quand l’IVG est-elle possible en France ?', 'mcq', '["Jusqu’à la fin de la 10e semaine de grossesse","Jusqu’à la fin de la 14e semaine de grossesse","Jusqu’au 6e mois","Jusqu’à la fin de la 4e semaine"]'::jsonb, 1, 'Soit 16 semaines d’aménorrhée, depuis la loi du 2 mars 2022.', 8),
    ('079456e2-a77e-54bf-9bda-b4dd41b23c22'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Quel est le rôle de la mifépristone dans l’IVG médicamenteuse ?', 'mcq', '["Elle provoque l’ovulation","C’est un anti-progestérone qui interrompt la grossesse","C’est une hormone de croissance","C’est un antibiotique"]'::jsonb, 1, 'Le misoprostol provoque ensuite l’expulsion.', 9),
    ('7520cf70-aba4-593b-a880-8cf6f447a33c'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Calculer sa date d’ovulation est une méthode de contraception fiable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La date d’ovulation varie d’un cycle à l’autre.', 10),
    ('6f077b96-efe0-52f6-933a-3cab8f44fc99'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Quelle technique d’AMP convient à une infertilité masculine sévère ?', 'mcq', '["La stimulation ovarienne","L’ICSI","L’insémination artificielle","La pilule"]'::jsonb, 1, 'Un spermatozoïde est injecté directement dans l’ovocyte.', 11),
    ('30b56103-ce0a-56b2-8696-3ef39576ffc2'::uuid, '117ea683-7b75-513b-896e-5010d64b7646'::uuid, 'Que signifie azoospermie ?', 'mcq', '["L’absence de spermatozoïdes dans le sperme","Un excès de spermatozoïdes","Une inflammation de la prostate","L’absence de règles"]'::jsonb, 0, 'Le préfixe a- marque l’absence.', 12),
    ('fc32fcd7-7709-514b-9bfd-bb4554d5681b'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Quelles bases sont complémentaires dans l’ADN ?', 'mcq', '["A-G et T-C","A-T et G-C","A-C et G-T","A-U et G-C"]'::jsonb, 1, 'L’uracile U remplace T dans l’ARN.', 1),
    ('7a7bb834-1cbf-5252-b785-05b940442e62'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Combien de chromosomes compte une cellule humaine non reproductrice ?', 'mcq', '["23","44","46","48"]'::jsonb, 2, '22 paires d’autosomes et une paire de gonosomes.', 2),
    ('39b3d229-43e3-56d6-ac58-7624f28c2a81'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Où a lieu la transcription ?', 'mcq', '["Dans le cytoplasme","Dans le noyau","Dans les ribosomes","Dans les mitochondries"]'::jsonb, 1, 'L’ADN y est copié en ARN messager.', 3),
    ('3e9f569d-7593-58be-9d69-9c98d5907d1f'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Où a lieu la traduction ?', 'mcq', '["Dans le noyau","Dans le cytoplasme, sur les ribosomes","Dans la membrane plasmique","Dans l’ADN"]'::jsonb, 1, 'L’ARNm y est lu codon par codon.', 4),
    ('684e0f76-ca8b-5f4f-805d-437f6592b654'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Un brin d’ADN transcrit porte TAC. Quel est le codon d’ARNm correspondant ?', 'mcq', '["ATG","AUG","UAC","TUG"]'::jsonb, 1, 'A → U, T → A, G → C, C → G.', 5),
    ('b4ab1ed9-14c0-5bdd-acb9-3ef4736e40cc'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Un codon est formé de :', 'mcq', '["Une base","Deux bases","Trois bases","Quatre bases"]'::jsonb, 2, 'Chaque codon correspond à un acide aminé ou à un signal stop.', 6),
    ('e8093c0d-6476-5ef8-bba1-ddc7b0704bba'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Quel type de mutation décale la lecture de tous les codons suivants ?', 'mcq', '["Une substitution","Une insertion ou une délétion d’une base","Une mutation silencieuse","Aucune"]'::jsonb, 1, 'On parle de décalage du cadre de lecture.', 7),
    ('90dcf8f7-8324-5b42-a4c9-5871502199ba'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Dans la drépanocytose, la mutation remplace :', 'mcq', '["Toute la protéine","Un seul acide aminé de la bêta-globine","Un chromosome entier","Le groupe sanguin"]'::jsonb, 1, 'L’acide glutamique est remplacé par une valine.', 8),
    ('8c89aa7f-5232-5511-9ce6-1a8fe7db405c'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Deux parents sains ont un enfant malade. L’allèle de la maladie est :', 'mcq', '["Dominant","Récessif","Codominant","Porté par le chromosome Y"]'::jsonb, 1, 'Les parents sont porteurs sains, hétérozygotes.', 9),
    ('ad923c75-43e2-5980-ad38-54e5ccff04c2'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Deux parents hétérozygotes pour une maladie autosomique récessive. Quel est le risque qu’un enfant soit malade ?', 'mcq', '["1/2","1/4","3/4","0"]'::jsonb, 1, 'Seul le génotype m//m est malade.', 10),
    ('d5a9384d-f171-5811-a33f-993c92249495'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'L’hémophilie touche surtout des garçons car son gène est porté par le chromosome X.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un garçon n’a qu’un chromosome X : un seul allèle récessif suffit.', 11),
    ('221ce74d-2737-548f-b34c-a40e88d41adb'::uuid, '9acce1fd-5568-565a-8e04-2430c8a79501'::uuid, 'Le groupe sanguin AB illustre :', 'mcq', '["La récessivité","La codominance","Une mutation","Une maladie génétique"]'::jsonb, 1, 'Les allèles A et B s’expriment tous les deux.', 12),
    ('ab36ebf3-fc67-54e9-ae0a-6a1bcdd17705'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Qu’est-ce qu’une métastase ?', 'mcq', '["Une tumeur bénigne","Une tumeur secondaire, à distance de la tumeur primitive","Un globule blanc","Un gène protecteur"]'::jsonb, 1, 'Des cellules cancéreuses ont voyagé par le sang ou la lymphe.', 1),
    ('78c55631-0ae0-5392-8fb1-c043e64a2186'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Quelle caractéristique distingue une tumeur maligne ?', 'mcq', '["Des limites nettes","Une capsule qui l’entoure","Elle envahit les tissus voisins et peut donner des métastases","Une croissance toujours lente"]'::jsonb, 2, 'Une tumeur bénigne ne métastase jamais.', 2),
    ('12a7c80d-3ec4-57c5-8b8f-bd77128f72f1'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Pourquoi le risque de cancer augmente-t-il avec l’âge ?', 'mcq', '["Parce qu’il faut en général accumuler plusieurs mutations","Parce que les cellules ne se divisent plus","Parce que le cancer est contagieux","Parce que l’ADN disparaît"]'::jsonb, 0, 'Les mutations s’additionnent au fil du temps.', 3),
    ('f0da857d-69a8-5d3f-8c28-aca18d36fb6f'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Quelle est la première cause de cancer évitable ?', 'mcq', '["Le soleil","Le tabac","Les virus","L’hérédité"]'::jsonb, 1, 'Il est en cause dans de nombreux cancers, dont celui du poumon.', 4),
    ('65660df0-25f8-53ba-9b65-312df80204cd'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Quel virus est à l’origine de la plupart des cancers du col de l’utérus ?', 'mcq', '["Le virus de la grippe","Les papillomavirus humains","Le VIH","Le virus de la rougeole"]'::jsonb, 1, 'Une vaccination et un dépistage existent.', 5),
    ('53c1fcd3-d374-5d81-aa04-033b38c357fa'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Quel examen affirme le diagnostic de cancer ?', 'mcq', '["La prise de température","L’examen anatomopathologique d’une biopsie","Un marqueur tumoral seul","La radiographie des poumons"]'::jsonb, 1, 'On observe le tissu au microscope.', 6),
    ('ff460549-c1ae-5b8c-843f-aa5a1b856931'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Pourquoi la chimiothérapie fait-elle tomber les cheveux ?', 'mcq', '["Elle frappe toutes les cellules qui se divisent vite, dont celles des follicules pileux","Elle brûle la peau","Elle est appliquée sur le crâne","Elle provoque une allergie"]'::jsonb, 0, 'Les cellules sanguines et digestives sont touchées pour la même raison.', 7),
    ('60c50079-08b1-5c0a-8e40-6fe26adf5e08'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'La radiothérapie utilise :', 'mcq', '["Des ultrasons","Des rayonnements ionisants concentrés sur la tumeur","Des champs magnétiques","Des anticorps"]'::jsonb, 1, 'Ils lèsent l’ADN des cellules irradiées.', 8),
    ('9fb8b5de-8db4-5251-9666-e65d6206ab2e'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Les marqueurs tumoraux sanguins servent au dépistage du cancer du sein dans la population.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils servent au suivi ; le dépistage repose sur la mammographie.', 9),
    ('628076d8-77f9-5b4e-b0f9-979e43a03817'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Le dépistage organisé du cancer du sein concerne les femmes de :', 'mcq', '["25 à 65 ans","40 à 50 ans","50 à 74 ans","Plus de 80 ans"]'::jsonb, 2, 'Une mammographie tous les deux ans.', 10),
    ('cc7c3b57-30a6-5cef-be23-7475d5b29b0e'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Pourquoi un patient sous chimiothérapie est-il exposé aux infections ?', 'mcq', '["Ses globules blancs diminuent","Ses globules rouges augmentent","Il reçoit des antibiotiques","Sa peau s’épaissit"]'::jsonb, 0, 'La moelle osseuse, qui se divise vite, est touchée.', 11),
    ('b0d0c906-2dd6-5af6-9c24-d22b5ef026f8'::uuid, '1414cfa1-1faa-5dd8-ab1a-ae5d47d5730b'::uuid, 'Que signifie le suffixe -ectomie ?', 'mcq', '["Inflammation","Ablation chirurgicale","Tumeur","Examen visuel"]'::jsonb, 1, 'Une mastectomie est l’ablation du sein.', 12),
    ('ac355ebb-866c-509c-9c54-7925f8dd2b2a'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Combien de temps dure l’épreuve écrite de CBPH ?', 'mcq', '["2 heures","3 heures","4 heures","5 heures"]'::jsonb, 2, 'Environ 1 heure pour la chimie et 3 heures pour la biologie.', 1),
    ('9f40447d-93fb-5542-8248-b190dc1d8235'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Quel est le coefficient de la partie biologie et physiopathologie humaines ?', 'mcq', '["3","8","13","16"]'::jsonb, 2, 'La chimie a un coefficient 3 ; le total fait 16.', 2),
    ('9624b685-7a85-5c6d-9845-f4748f8c98b6'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Combien d’exercices comporte la partie chimie ?', 'mcq', '["Un","Deux exercices indépendants","Cinq","Dix"]'::jsonb, 1, 'Ils mobilisent documents, protocole et calculs.', 3),
    ('ed04a282-bbef-52f0-ad84-4f3f3aaa4f76'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Qu’est-ce qu’un signe paraclinique ?', 'mcq', '["Un symptôme ressenti par le patient","Un résultat d’examen complémentaire","Un traitement","Une cause de maladie"]'::jsonb, 1, 'Analyses et imagerie fournissent les signes paracliniques.', 4),
    ('fcf66772-3f25-53de-a081-824035fe79b8'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Que désigne l’étiologie d’une maladie ?', 'mcq', '["Son traitement","Sa cause","Son évolution","Son coût"]'::jsonb, 1, 'Par exemple, la destruction auto-immune des cellules β dans le diabète de type 1.', 5),
    ('0e4e5d2e-610f-51c9-a762-3a23fecaec75'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Que signifie hyperglycémie ?', 'mcq', '["Un manque de glucose dans le sang","Un excès de glucose dans le sang","Du glucose dans l’urine","Une inflammation du pancréas"]'::jsonb, 1, 'hyper- : excès ; -émie : dans le sang.', 6),
    ('5ea15e91-9b9c-5bb4-8dbc-671846667e1b'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Que signifie leucopénie ?', 'mcq', '["Une augmentation des globules blancs","Une diminution des globules blancs","Une inflammation des globules blancs","Une tumeur des globules blancs"]'::jsonb, 1, 'leuco- : blanc ; -pénie : diminution.', 7),
    ('d8458855-cfb1-5ec0-ba14-d21be96af3a4'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Le suffixe -ite signifie :', 'mcq', '["Ablation","Inflammation","Tumeur","Douleur"]'::jsonb, 1, 'Une appendicite est une inflammation de l’appendice.', 8),
    ('614b0628-7cc7-5487-a502-476625fc6f9a'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Décrire une courbe suffit pour l’interpréter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut relier le constat aux connaissances pour expliquer pourquoi.', 9),
    ('b2bc5436-911a-57db-8471-4dbcf6d4bb47'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Que faut-il faire avant de remplacer les valeurs dans un calcul de chimie ?', 'mcq', '["Écrire la formule littérale et convertir les unités","Arrondir toutes les données à l’unité","Ignorer les unités","Donner le résultat sans calcul"]'::jsonb, 0, 'Puis donner le résultat avec son unité.', 10),
    ('18e667fe-f88b-5676-a01c-c44e01090509'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Que signifie tachycardie ?', 'mcq', '["Un cœur lent","Un cœur rapide","Un cœur augmenté de volume","Une inflammation du cœur"]'::jsonb, 1, 'tachy- : rapide ; brady- : lent.', 11),
    ('617a6bc2-a945-54c7-82df-53f497a471b8'::uuid, '1925f7bc-c7a4-5e8a-98be-67e015751189'::uuid, 'Pourquoi lire tout le sujet de biologie avant de commencer ?', 'mcq', '["Parce que les questions sont souvent liées et qu’un document plus loin peut aider","Pour perdre du temps","Parce que c’est obligatoire","Pour choisir de ne traiter qu’une question"]'::jsonb, 0, 'On gagne en cohérence et en temps.', 12),
    ('abf6514a-93e7-514c-a5fb-165827739024'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Quelle relation lie la quantité de matière n, la masse m et la masse molaire M ?', 'mcq', '["n = m × M","n = m / M","n = M / m","n = m − M"]'::jsonb, 1, 'La quantité de matière se calcule en divisant la masse (g) par la masse molaire (g/mol).', 1),
    ('5d3487b6-f6b7-5cd8-9aaf-8114ffa36469'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Dans une solution aqueuse de glucose, qu’est-ce que le glucose ?', 'mcq', '["Le solvant","La solution","Le soluté","Le précipité"]'::jsonb, 2, 'Le glucose est l’espèce dissoute ; l’eau est le solvant.', 2),
    ('a20bfa1e-9a77-5699-8467-c8571fa77d7d'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Quelle est l’unité de la concentration massique ?', 'mcq', '["mol/L","g/mol","g/L","mol/g"]'::jsonb, 2, 'Cm = m / V : une masse divisée par un volume, en g/L.', 3),
    ('8a4f0c65-cc3b-5a6c-80fd-4a069eeabc59'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'On dissout 0,20 mol de soluté dans 0,50 L de solution. Quelle est la concentration molaire ?', 'mcq', '["0,10 mol/L","0,40 mol/L","2,5 mol/L","0,70 mol/L"]'::jsonb, 1, 'C = n / V = 0,20 / 0,50 = 0,40 mol/L.', 4),
    ('746be704-5f2b-5531-a9d4-3a89e425ff79'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Quelle masse de NaCl faut-il peser pour préparer 500 mL de sérum physiologique à 9,0 g/L ?', 'mcq', '["4,5 g","9,0 g","18 g","0,45 g"]'::jsonb, 0, 'm = Cm × V = 9,0 × 0,500 = 4,5 g.', 5),
    ('11d9f76d-da42-54d9-a6e4-22d905e65701'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Lors d’une dilution, la quantité de matière de soluté reste la même.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ajoute seulement du solvant : c’est pourquoi C mère × V prélevé = C fille × V fille.', 6),
    ('9e70c87f-b721-55a4-9347-af6e97d1e285'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Pour diluer 20 fois une solution et obtenir 100,0 mL, quel volume de solution mère prélève-t-on ?', 'mcq', '["20,0 mL","2,0 mL","5,0 mL","10,0 mL"]'::jsonb, 2, 'V prélevé = V fille / F = 100,0 / 20 = 5,0 mL.', 7),
    ('6932c0e6-e6d6-5324-a4eb-cfa811c1f298'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Quelle verrerie permet de prélever un volume précis de solution mère ?', 'mcq', '["Un bécher","Une éprouvette graduée","Un erlenmeyer","Une pipette jaugée"]'::jsonb, 3, 'La pipette jaugée est la verrerie de précision pour un prélèvement ; le bécher ne mesure rien avec précision.', 8),
    ('712c30a8-7659-52b1-961b-772033bb8447'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Quelle relation relie la concentration massique Cm et la concentration molaire C ?', 'mcq', '["Cm = C × M","Cm = C / M","Cm = M / C","Cm = C + M"]'::jsonb, 0, 'Une mole pèse M grammes : C mol/L correspondent à C × M g/L.', 9),
    ('30143f6a-e193-58eb-9a8e-3cd433e47f76'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Quelle est la masse molaire du glucose C₆H₁₂O₆ ? (C = 12, H = 1, O = 16 g/mol)', 'mcq', '["96 g/mol","180 g/mol","168 g/mol","342 g/mol"]'::jsonb, 1, '6 × 12 + 12 × 1 + 6 × 16 = 72 + 12 + 96 = 180 g/mol.', 10),
    ('853fa6f4-fb3a-51bb-9c11-91179526e9de'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Dans quelle verrerie prépare-t-on une solution de volume précis ?', 'mcq', '["Une fiole jaugée","Un tube à essai","Un bécher","Une burette"]'::jsonb, 0, 'La fiole jaugée, remplie jusqu’au trait de jauge, garantit le volume de la solution.', 11),
    ('62306e14-834f-5a6c-a7b1-996c02a37daa'::uuid, '4fa49010-ce7a-5cf5-8342-933a7d24fc12'::uuid, 'Le facteur de dilution F est égal au rapport C fille / C mère.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : F = C mère / C fille, toujours supérieur à 1.', 12),
    ('e9fb4299-a6e4-5a41-81b5-9c632de54770'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Une solution a un pH de 11. Elle est :', 'mcq', '["Acide","Neutre","Basique","Corrosive dans tous les cas"]'::jsonb, 2, 'À 25 °C, un pH supérieur à 7 caractérise une solution basique.', 1),
    ('adaebb53-5766-5209-b351-5a23112d80da'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Selon Brönsted, un acide est une espèce capable de :', 'mcq', '["Capter un ion H⁺","Céder un ion H⁺","Céder un électron","Capter un ion HO⁻"]'::jsonb, 1, 'Céder un H⁺ fait un acide ; le capter fait une base.', 2),
    ('5e187d40-467b-5546-9111-189c7cc38029'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Quelle relation relie le pH et la concentration en ions oxonium ?', 'mcq', '["[H₃O⁺] = 10⁻ᵖᴴ","[H₃O⁺] = 10ᵖᴴ","[H₃O⁺] = pH / 10","[H₃O⁺] = 14 − pH"]'::jsonb, 0, 'Ainsi, à pH 3, [H₃O⁺] = 10⁻³ mol/L.', 3),
    ('7bf16a9d-6a4d-53ee-b97c-d6f960ae8450'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Quand on passe d’un pH de 4 à un pH de 3, la concentration en H₃O⁺ est :', 'mcq', '["Divisée par 10","Multipliée par 10","Multipliée par 3","Inchangée"]'::jsonb, 1, 'Une unité de pH en moins correspond à dix fois plus d’ions H₃O⁺.', 4),
    ('8794291a-58e2-5061-adf7-0e539fd9f3ab'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Quelle est la formule de l’ammoniac ?', 'mcq', '["NH₄⁺","NO₃⁻","NH₃","NaOH"]'::jsonb, 2, 'L’ammoniac NH₃ est une base : il capte un H⁺ pour donner l’ion ammonium NH₄⁺.', 5),
    ('33fb3192-8cbe-5f1e-be57-51f3632c5859'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Quelle est l’équation de l’autoprotolyse de l’eau ?', 'mcq', '["H₂O → H₂ + O","2 H₂O ⇌ H₃O⁺ + HO⁻","H₂O + H⁺ → H₃O⁺ seulement","2 H₂O → 2 H₂ + O₂"]'::jsonb, 1, 'L’eau joue à la fois le rôle d’acide et de base.', 6),
    ('8d416e05-29b6-5dc5-8ed2-b1aafa49654c'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Pour diluer un acide concentré, on verse l’eau dans l’acide.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On verse l’acide dans l’eau, doucement : la dilution est exothermique et l’inverse provoque des projections.', 7),
    ('147ae321-f380-5db7-bac5-d7153ff23de5'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Que faire en premier après une projection de soude sur la peau ?', 'mcq', '["Neutraliser avec du vinaigre","Rincer abondamment à l’eau pendant au moins 15 minutes","Appliquer une crème grasse","Essuyer avec un chiffon sec et attendre"]'::jsonb, 1, 'Le rinçage immédiat et prolongé dilue et élimine le produit ; neutraliser sur la peau dégage de la chaleur.', 8),
    ('a880f6e8-e815-5974-bea4-54aed94471b1'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Quel pictogramme porte une solution concentrée d’acide chlorhydrique ?', 'mcq', '["Flamme (inflammable)","Bouteille de gaz","Corrosion (mains et surface rongées)","Poisson et arbre (environnement)"]'::jsonb, 2, 'Le pictogramme corrosif SGH05 signale les produits qui détruisent les tissus vivants.', 9),
    ('98becd79-a259-5534-94fc-16181138b110'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Dans le couple CH₃COOH / CH₃COO⁻, quelle espèce est la base ?', 'mcq', '["CH₃COOH","CH₃COO⁻","H₃O⁺","Aucune des deux"]'::jsonb, 1, 'L’ion éthanoate est la forme qui a perdu un H⁺ : c’est la base du couple.', 10),
    ('a5ee46e8-7582-5d87-b981-b79b108f2994'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Si [H₃O⁺] augmente dans une solution aqueuse à 25 °C, alors [HO⁻] :', 'mcq', '["Augmente aussi","Reste constante","Diminue","Devient nulle"]'::jsonb, 2, 'Le produit ionique Ke = [H₃O⁺] × [HO⁻] reste constant : l’une monte, l’autre baisse.', 11),
    ('a8dc1253-2ab2-5afc-8e6e-309d55126a60'::uuid, '5a391b0d-4df4-560b-867a-2b48bc5089e6'::uuid, 'Pourquoi neutralise-t-on une solution acide avant de la jeter ?', 'mcq', '["Pour augmenter son volume","Pour ramener son pH près de 7 et limiter son impact sur l’environnement","Pour la rendre plus corrosive","Pour la colorer"]'::jsonb, 1, 'Un déchet neutralisé ne dégrade plus les canalisations ni les milieux aquatiques.', 12),
    ('f62dab3b-8eff-51a8-a9c1-3c2c0d1eae73'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Un oxydant est une espèce capable de :', 'mcq', '["Céder des électrons","Capter des électrons","Céder un ion H⁺","Capter un ion H⁺"]'::jsonb, 1, 'L’oxydant capte des électrons et se transforme en son réducteur conjugué.', 1),
    ('a9e33703-ea95-59d7-9177-d167b7287e5d'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Dans la demi-équation I₂ + 2 e⁻ = 2 I⁻, quel est l’oxydant ?', 'mcq', '["I⁻","e⁻","I₂","Il n’y en a pas"]'::jsonb, 2, 'Le diiode capte deux électrons : c’est l’oxydant du couple I₂/I⁻.', 2),
    ('d174ac47-b04d-5384-aa52-a91beb2afd19'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Quelle est l’espèce active de l’eau de Javel ?', 'mcq', '["L’ion hypochlorite ClO⁻","L’ion chlorure Cl⁻","Le dichlore Cl₂","L’ion sodium Na⁺"]'::jsonb, 0, 'L’ion hypochlorite est un oxydant puissant qui détruit les micro-organismes.', 3),
    ('4df2ec6d-1123-56e8-ab8d-3e7d66701344'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Pourquoi ne faut-il jamais mélanger eau de Javel et détartrant acide ?', 'mcq', '["Le mélange devient inefficace mais sans danger","Il se forme du dichlore, un gaz toxique","Il se forme de l’eau oxygénée","Le mélange explose toujours"]'::jsonb, 1, 'En milieu acide : ClO⁻ + Cl⁻ + 2 H⁺ → Cl₂ + H₂O. Le dichlore attaque les voies respiratoires.', 4),
    ('ab3595c9-e21c-5194-a7ff-f2d451a4f4c8'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Quelle est la différence entre un antiseptique et un désinfectant ?', 'mcq', '["Aucune, ce sont des synonymes","L’antiseptique s’applique sur les tissus vivants, le désinfectant sur l’inerte","Le désinfectant s’applique sur la peau, l’antiseptique sur les sols","L’antiseptique est toujours plus concentré"]'::jsonb, 1, 'La peau reçoit un antiseptique ; une paillasse ou un sol reçoit un désinfectant.', 5),
    ('d2e3d83a-fd99-50b7-a6dd-6a47c46a165d'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Dans une réaction d’oxydoréduction, les électrons apparaissent dans l’équation bilan.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ajuste les demi-équations pour que les électrons cédés soient tous captés : ils s’éliminent.', 6),
    ('6043b604-c6a2-574e-a617-e770ac2c75a2'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Pourquoi une eau oxygénée ancienne est-elle moins efficace ?', 'mcq', '["Elle s’est transformée en eau de Javel","Le peroxyde d’hydrogène s’est décomposé en eau et dioxygène","Elle s’est concentrée par évaporation","Elle a absorbé des microbes"]'::jsonb, 1, '2 H₂O₂ → 2 H₂O + O₂ : la décomposition est accélérée par la lumière et la chaleur.', 7),
    ('8bf83a21-a390-5e5e-afdd-8fdd230951d0'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Une réaction d’oxydoréduction est un transfert :', 'mcq', '["D’ions H⁺","D’électrons","De neutrons","De molécules d’eau"]'::jsonb, 1, 'Les réactions acido-basiques échangent des H⁺, l’oxydoréduction échange des électrons.', 8),
    ('24710cd4-87ff-583e-b16c-4150570672be'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Quelle espèce active contient une teinture d’iode ?', 'mcq', '["L’ion iodure I⁻","Le diiode I₂","L’iode radioactif","L’ion hypochlorite"]'::jsonb, 1, 'Le diiode est l’oxydant qui donne à la teinture son pouvoir antiseptique.', 9),
    ('1be8145d-67e7-547e-8781-af175d168dd4'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Dans le couple Cl₂/Cl⁻, la demi-équation s’écrit :', 'mcq', '["Cl₂ = 2 Cl⁻ + 2 e⁻","Cl₂ + 2 e⁻ = 2 Cl⁻","Cl₂ + e⁻ = Cl⁻","Cl⁻ + 2 e⁻ = Cl₂"]'::jsonb, 1, 'L’oxydant Cl₂ capte deux électrons pour donner deux ions chlorure.', 10),
    ('0f3e9dda-f46c-5264-a103-c1148c8434cf'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Comment conserver un flacon d’eau oxygénée ?', 'mcq', '["Au soleil pour le stériliser","Au frais et à l’abri de la lumière","Ouvert pour laisser partir le gaz","Mélangé à de la Javel"]'::jsonb, 1, 'La chaleur et la lumière accélèrent la décomposition du peroxyde d’hydrogène.', 11),
    ('2953bf28-eb92-5ddd-b967-0703c8aa98c6'::uuid, 'f98cc47e-4b7b-5a5d-8db2-e66a5e8a4da1'::uuid, 'Un réducteur est une espèce qui gagne des électrons.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : le réducteur cède des électrons, l’oxydant en capte.', 12),
    ('a648c5a1-53cd-5fab-b840-91e34a0f7cfd'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Quelle est la fréquence de la tension du secteur en France ?', 'mcq', '["230 Hz","50 Hz","60 Hz","20 Hz"]'::jsonb, 1, 'f = 50 Hz, soit une période de 20 ms.', 1),
    ('06ccd6fe-9a11-5d2d-b2fd-4c3b0ea483bb'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'La valeur 230 V du secteur correspond à :', 'mcq', '["La tension maximale","La tension efficace","La tension minimale","La moyenne de la tension"]'::jsonb, 1, 'La tension maximale vaut 230 × √2 ≈ 325 V.', 2),
    ('f3b75b98-43eb-5439-bcce-983b8f8979fb'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Une tension sinusoïdale a une période de 20 ms. Sa fréquence est :', 'mcq', '["20 Hz","0,02 Hz","50 Hz","200 Hz"]'::jsonb, 2, 'f = 1 / T = 1 / 0,020 s = 50 Hz.', 3),
    ('a27ce806-8085-5ba3-962f-d53f286344ac'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Quelle relation relie la tension efficace et la tension maximale d’une tension sinusoïdale ?', 'mcq', '["Ueff = Umax × √2","Ueff = Umax / √2","Ueff = Umax / 2","Ueff = 2 × Umax"]'::jsonb, 1, 'Pour une tension sinusoïdale, la valeur efficace est la valeur maximale divisée par √2.', 4),
    ('2411a972-f18f-5dd4-9070-1ea8c1993004'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Quel dispositif protège les PERSONNES contre les fuites de courant ?', 'mcq', '["Le fusible seul","Le disjoncteur différentiel 30 mA","L’ampèremètre","La multiprise"]'::jsonb, 1, 'Il détecte une différence entre le courant de la phase et celui du neutre et coupe le circuit.', 5),
    ('d01d4f9a-fc6b-57f9-a951-c8406ee2a042'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Qu’est-ce qu’une électrocution ?', 'mcq', '["Toute sensation de décharge","Une électrisation qui entraîne la mort","Une brûlure superficielle","Un court-circuit dans un appareil"]'::jsonb, 1, 'L’électrisation est le passage du courant dans le corps ; l’électrocution en est l’issue mortelle.', 6),
    ('8bec85ca-8290-548d-8b90-871a25ee2043'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'À quoi sert le fil vert et jaune d’une prise ?', 'mcq', '["À amener le courant à l’appareil","À relier la carcasse métallique de l’appareil à la Terre","À mesurer la tension","À ramener le courant vers le compteur en fonctionnement normal"]'::jsonb, 1, 'En cas de défaut d’isolement, le courant de fuite s’écoule vers la Terre et non à travers l’utilisateur.', 7),
    ('1b8a6d31-57ac-5dc0-a516-4c06c4c968fc'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Le corps humain ne conduit pas l’électricité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la conduit, d’autant mieux que la peau est mouillée : c’est ce qui rend l’électrisation possible.', 8),
    ('67393cb6-81f0-5bc9-9aa9-c75cf4b69b12'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Pourquoi une multiprise surchargée est-elle dangereuse ?', 'mcq', '["Elle baisse la fréquence du secteur","L’intensité totale devient trop grande et les fils s’échauffent","Elle supprime la prise de terre","Elle transforme la tension alternative en continue"]'::jsonb, 1, 'Une surintensité échauffe les conducteurs : risque de détérioration et d’incendie.', 9),
    ('0b7940bd-cf78-572b-90a6-9e6d98f9a2b1'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Quelle borne de la prise est la plus dangereuse ?', 'mcq', '["La terre","Le neutre","La phase","Aucune"]'::jsonb, 2, 'La phase est portée à la tension du secteur par rapport à la Terre.', 10),
    ('b14ae394-79f0-57a1-98b7-7961779cf7e6'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Sur un oscillogramme, la période se lit sur :', 'mcq', '["L’axe vertical","L’axe horizontal (temps)","La luminosité de la trace","Le calibre de l’ampèremètre"]'::jsonb, 1, 'On compte les divisions d’un motif et on multiplie par la sensibilité horizontale.', 11),
    ('17b63971-89bb-51d9-ae2a-7ea8bdee348a'::uuid, '405b37e1-6c0e-5342-93ad-e242d2590914'::uuid, 'Que faire en premier face à une victime encore en contact avec un fil électrique ?', 'mcq', '["La tirer par la main","Couper le courant avant de la toucher","Lui jeter de l’eau","Attendre qu’elle lâche d’elle-même"]'::jsonb, 1, 'Toucher la victime sous tension ferait passer le courant par le sauveteur.', 12),
    ('ddb711b5-4842-5902-bec7-9a7d24985a11'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Quelles sont les limites du domaine visible dans le vide ?', 'mcq', '["De 100 nm à 400 nm","De 400 nm à 800 nm","De 800 nm à 1 mm","De 1 µm à 10 µm"]'::jsonb, 1, 'En deçà de 400 nm, ce sont les UV ; au-delà de 800 nm, les infrarouges.', 1),
    ('e89a7f64-5207-5956-9807-0f2d2b4dc7b4'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Le rayonnement principal émis par le corps humain appartient au domaine :', 'mcq', '["Des ultraviolets","Du visible","Des infrarouges","Des rayons X"]'::jsonb, 2, 'À 310 K, λmax ≈ 9 µm : c’est l’infrarouge.', 2),
    ('fecea16e-6dc6-593f-914f-6fc2cf9babe0'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Que dit la loi de Wien ?', 'mcq', '["λmax × T = constante","λmax + T = constante","λmax = T × 273","λmax / T = constante"]'::jsonb, 0, 'λmax × T = 2,90 × 10⁻³ m·K : plus le corps est chaud, plus λmax est petite.', 3),
    ('9028dd28-6f18-52b2-926a-5422ab042eeb'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Plus un corps est chaud, plus la longueur d’onde de son maximum d’émission est :', 'mcq', '["Grande","Petite","Constante","Nulle"]'::jsonb, 1, 'λmax est inversement proportionnelle à la température absolue.', 4),
    ('1a7580ea-756c-5f5b-b223-9f605ebbcd48'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Convertis 37 °C en kelvins.', 'mcq', '["37 K","236 K","310 K","373 K"]'::jsonb, 2, 'T = θ + 273 = 37 + 273 = 310 K.', 5),
    ('d047bf98-577d-5b55-ad49-cad5a9394fa0'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Les infrarouges émis par le corps humain sont dangereux pour la santé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils sont invisibles et sans danger ; ce sont les UV qui présentent un risque.', 6),
    ('6f2ca9db-3312-59c9-bb19-8f95b1c7f4f1'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Où se situe le maximum d’émission du Soleil (environ 5 800 K) ?', 'mcq', '["Dans l’infrarouge lointain","Vers 500 nm, dans le visible","Dans les rayons X","Dans les ondes radio"]'::jsonb, 1, 'λmax = 2,90 × 10⁻³ / 5 800 ≈ 5,0 × 10⁻⁷ m = 500 nm.', 7),
    ('29d69182-d9de-51e2-8db9-c818f48f9e7b'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Comment fonctionne un thermomètre frontal sans contact ?', 'mcq', '["Il émet des UV sur la peau","Il mesure le rayonnement infrarouge émis par la peau","Il mesure la pression du sang","Il chauffe le front et mesure le refroidissement"]'::jsonb, 1, 'L’intensité des IR reçus dépend de la température de la surface visée.', 8),
    ('8b57af14-dc2a-5b8d-8f0c-505bf0139a81'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Un rayonnement de longueur d’onde 300 nm appartient au domaine :', 'mcq', '["Des ultraviolets","Du visible","Des infrarouges","Des micro-ondes"]'::jsonb, 0, '300 nm est inférieur à 400 nm : c’est un rayonnement UV.', 9),
    ('2efcf76b-34df-5b78-94cf-df419f875e15'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Combien de nanomètres vaut 1 micromètre ?', 'mcq', '["10","100","1 000","1 000 000"]'::jsonb, 2, '1 µm = 10⁻⁶ m = 1 000 × 10⁻⁹ m = 1 000 nm.', 10),
    ('f0d515db-5590-5437-b06a-e362f27ef62a'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Pourquoi une caméra thermique peut-elle repérer une personne dans le noir ?', 'mcq', '["Parce que le corps humain émet de la lumière visible","Parce que le corps humain émet des infrarouges, qu’elle capte","Parce qu’elle émet des rayons X","Parce qu’elle détecte les sons"]'::jsonb, 1, 'Elle n’a pas besoin d’éclairage : elle forme l’image à partir du rayonnement IR propre des corps.', 11),
    ('feb70477-92b8-5a17-8580-1903042c7140'::uuid, '6c836d70-f3be-5db5-bb66-e7c63fff6cab'::uuid, 'Un corps plus froid que le corps humain émet un maximum à une longueur d’onde plus courte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Plus froid signifie λmax plus grande, d’après la loi de Wien.', 12),
    ('a472ba84-d72f-5688-afda-4f095a0d1cc3'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Quelle est l’expression de l’énergie cinétique ?', 'mcq', '["Ec = m × v","Ec = ½ × m × v²","Ec = m × g × h","Ec = ½ × m² × v"]'::jsonb, 1, 'Elle est proportionnelle à la masse et au carré de la vitesse.', 1),
    ('aa976879-8c04-5b2b-9ba5-0a716dab3d48'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Si la vitesse d’un véhicule double, son énergie cinétique est :', 'mcq', '["Doublée","Triplée","Multipliée par 4","Inchangée"]'::jsonb, 2, 'Ec dépend de v² : (2v)² = 4v².', 2),
    ('51b9735e-6dbe-5f5a-a26d-d5df8eb51c4f'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Convertis 72 km/h en m/s.', 'mcq', '["20 m/s","72 m/s","259 m/s","7,2 m/s"]'::jsonb, 0, 'v = 72 / 3,6 = 20 m/s.', 3),
    ('f82e7492-d0f0-5377-9039-404ec045c8fe'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Qu’est-ce que la distance de réaction ?', 'mcq', '["La distance parcourue pendant le freinage","La distance parcourue pendant le temps de réaction du conducteur","La distance de sécurité légale","La longueur du véhicule"]'::jsonb, 1, 'Pendant ce temps, le véhicule garde sa vitesse : DR = v × tR.', 4),
    ('b9782eae-e7d0-5d97-96a1-df7e053489b4'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'La distance d’arrêt est égale à :', 'mcq', '["DR − DF","DR × DF","DR + DF","DF seule"]'::jsonb, 2, 'On additionne la distance parcourue avant de freiner et celle du freinage.', 5),
    ('61a23eba-d711-51e1-a3b6-38acf8dd7740'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'L’alcool augmente surtout :', 'mcq', '["La masse du véhicule","La distance de réaction","L’adhérence des pneus","L’énergie cinétique à vitesse égale"]'::jsonb, 1, 'Il allonge le temps de réaction, donc la distance parcourue avant de freiner.', 6),
    ('94c9a171-358e-5990-a1be-15af99c316c3'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Quelle distance de réaction à 90 km/h (25 m/s) avec un temps de réaction de 1 s ?', 'mcq', '["9 m","25 m","90 m","50 m"]'::jsonb, 1, 'DR = v × tR = 25 × 1 = 25 m.', 7),
    ('6004bcf2-9878-5f84-8c1f-fa4b375b14c6'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Une route mouillée augmente la distance de freinage.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’adhérence diminue : le véhicule met plus de distance à dissiper son énergie.', 8),
    ('e34cfe5a-60d5-5068-b952-42071466e12c'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Quelle est l’énergie cinétique d’un piéton de 60 kg qui court à 5 m/s ?', 'mcq', '["150 J","300 J","750 J","1 500 J"]'::jsonb, 2, 'Ec = 0,5 × 60 × 5² = 0,5 × 60 × 25 = 750 J.', 9),
    ('36b89432-3cc2-5d7a-a48c-7611fb035311'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Pourquoi la distance de freinage est-elle proportionnelle au carré de la vitesse ?', 'mcq', '["Parce que les freins s’usent plus vite","Parce qu’il faut dissiper l’énergie cinétique, proportionnelle à v²","Parce que le temps de réaction double","Parce que la masse augmente avec la vitesse"]'::jsonb, 1, 'À force de freinage égale, la distance est proportionnelle à l’énergie à dissiper.', 10),
    ('a1d924bf-a268-5573-b9bc-932de4214bc0'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Quel facteur n’influence PAS la distance de réaction ?', 'mcq', '["La fatigue","Le téléphone au volant","L’état des pneus","La vitesse"]'::jsonb, 2, 'L’état des pneus joue sur le freinage, pas sur le temps que met le conducteur à réagir.', 11),
    ('0a4147f0-f265-5f59-9127-c2a07b603a83'::uuid, '305e26f5-e0a4-5049-b866-c5bbb5fcea0e'::uuid, 'Que devient l’énergie cinétique d’un véhicule lors d’un choc ?', 'mcq', '["Elle disparaît sans effet","Elle est dissipée en déformations et en chaleur","Elle se transforme en vitesse","Elle est stockée dans la ceinture"]'::jsonb, 1, 'D’où la gravité des chocs à grande vitesse : il y a beaucoup plus d’énergie à dissiper.', 12),
    ('3a124930-1d5f-579d-87e5-d2f93b5d6444'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Quel est le domaine des fréquences audibles par l’oreille humaine ?', 'mcq', '["De 2 Hz à 2 000 Hz","De 20 Hz à 20 000 Hz","De 200 Hz à 200 000 Hz","De 0 Hz à 20 Hz"]'::jsonb, 1, 'En dessous, ce sont les infrasons ; au-dessus, les ultrasons.', 1),
    ('944a8696-6983-55d9-99dc-c1a723e3ccad'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Un son de fréquence élevée est perçu comme :', 'mcq', '["Grave","Aigu","Fort","Faible"]'::jsonb, 1, 'La fréquence fixe la hauteur ; la force du son dépend du niveau d’intensité sonore.', 2),
    ('1f7855ba-5221-5f4c-8425-ab41f466bdb1'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Le son peut se propager dans le vide.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une onde mécanique : il lui faut un milieu matériel (air, eau, solide).', 3),
    ('df48a1d9-38f2-5a29-ad14-5c6a0ff48d39'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Dans quelle unité s’exprime le niveau d’intensité sonore ?', 'mcq', '["Le hertz","Le décibel","Le watt","Le pascal"]'::jsonb, 1, 'Le sonomètre affiche des décibels (dB).', 4),
    ('1a955b63-2e3e-53e9-ad09-732bd59d4993'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Quelles cellules transforment la vibration sonore en message nerveux ?', 'mcq', '["Les osselets","Les cellules ciliées de la cochlée","Les cellules du tympan","Les neurones du cortex"]'::jsonb, 1, 'Elles sont situées dans l’oreille interne et ne se régénèrent pas.', 5),
    ('bf901a40-1063-5415-98b6-de0dc747a769'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Comment appelle-t-on les ondes sonores de fréquence supérieure à 20 000 Hz ?', 'mcq', '["Infrasons","Ultrasons","Infrarouges","Ultraviolets"]'::jsonb, 1, 'Inaudibles pour nous, elles sont utilisées en échographie.', 6),
    ('be26f96c-5880-52c5-bfe5-0c4712e80954'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'À partir de quel niveau sonore environ une exposition prolongée présente-t-elle un risque ?', 'mcq', '["20 dB","50 dB","80–85 dB","200 dB"]'::jsonb, 2, 'Au-delà, le risque augmente avec la durée d’exposition.', 7),
    ('60cf0800-2ba5-555a-909d-29490ccc178d'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Que représente un audiogramme ?', 'mcq', '["La forme de l’oreille","Le seuil d’audition du patient pour chaque fréquence testée","La vitesse du son dans l’oreille","L’activité électrique du cœur"]'::jsonb, 1, 'Il permet de repérer une perte auditive et les fréquences touchées.', 8),
    ('d32c345e-5287-5470-93c8-d78032d5b948'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Un son a une période de 2,0 ms. Quelle est sa fréquence ?', 'mcq', '["2 Hz","50 Hz","500 Hz","2 000 Hz"]'::jsonb, 2, 'f = 1 / T = 1 / 0,0020 s = 500 Hz.', 9),
    ('39aea24e-c805-599d-896d-4eef7330785f'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Quel est le rôle d’une prothèse auditive ?', 'mcq', '["Supprimer tous les sons","Amplifier le son, surtout aux fréquences où la perte est forte","Émettre des ultrasons","Régénérer les cellules ciliées"]'::jsonb, 1, 'Micro, amplificateur, écouteur : elle compense la perte sans réparer l’oreille.', 10),
    ('14c1dbb8-c825-5ca4-9284-284c3bf6733b'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Quels éléments de l’oreille moyenne transmettent la vibration du tympan ?', 'mcq', '["Les osselets","Les cellules ciliées","Le nerf auditif","Le pavillon"]'::jsonb, 0, 'Marteau, enclume et étrier transmettent et amplifient la vibration jusqu’à l’oreille interne.', 11),
    ('38eb798e-c148-5d12-9abb-3462ef7543f1'::uuid, 'eb96bdf1-95d1-55b0-8a24-a082715e703a'::uuid, 'Vers quel niveau se situe le seuil de douleur ?', 'mcq', '["60 dB","85 dB","120 dB","0 dB"]'::jsonb, 2, 'À ce niveau, même une exposition brève peut léser l’oreille interne.', 12),
    ('91a248a2-240f-5204-b527-c1265f26b7cb'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Dans le modèle de l’œil, la rétine joue le rôle :', 'mcq', '["D’une lentille","D’un diaphragme","D’un écran","D’un miroir"]'::jsonb, 2, 'C’est sur elle que se forme l’image ; cornée et cristallin forment la lentille.', 1),
    ('9b1eb05c-8592-52a5-9a7f-f8ece83b6a5b'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Quel élément de l’œil règle la quantité de lumière qui entre ?', 'mcq', '["Le cristallin","L’iris","La rétine","Le nerf optique"]'::jsonb, 1, 'L’iris agit comme un diaphragme : la pupille se rétrécit en pleine lumière.', 2),
    ('a449c23f-792c-5550-8f2a-852771a9a462'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Quelle est la vergence d’une lentille de distance focale 25 cm ?', 'mcq', '["+ 0,25 δ","+ 4,0 δ","+ 25 δ","− 4,0 δ"]'::jsonb, 1, 'V = 1 / f’ = 1 / 0,25 m = + 4,0 δ.', 3),
    ('d5ed1894-9afd-5ef5-9503-a48a5150ec5f'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Un rayon passant par le centre optique d’une lentille :', 'mcq', '["Est dévié vers le foyer","N’est pas dévié","Ressort parallèle à l’axe","Est réfléchi"]'::jsonb, 1, 'C’est l’un des trois rayons particuliers qui servent à construire une image.', 4),
    ('66971554-28b5-59e5-a418-1b3636bc4713'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Un rayon incident parallèle à l’axe optique d’une lentille convergente ressort en passant par :', 'mcq', '["Le foyer objet F","Le foyer image F’","Le centre optique O","Aucun point particulier"]'::jsonb, 1, 'C’est la définition même du foyer image.', 5),
    ('10d399c1-d744-5296-88a3-cad82aa3de29'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Chez un œil myope, l’image d’un objet éloigné se forme :', 'mcq', '["Sur la rétine","Derrière la rétine","Avant la rétine","Sur la cornée"]'::jsonb, 2, 'L’œil myope est trop convergent : la vision de loin est floue.', 6),
    ('aa57ec63-a35b-539f-8c88-9685e44c10f0'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Quel verre corrige la myopie ?', 'mcq', '["Une lentille convergente","Une lentille divergente","Un verre plan","Un prisme"]'::jsonb, 1, 'La lentille divergente diminue la convergence totale de l’œil.', 7),
    ('46fcd939-9acd-5ee1-9e5f-f1bb8c7a3c99'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Qu’est-ce que la presbytie ?', 'mcq', '["Un œil trop long","La perte d’élasticité du cristallin avec l’âge, qui gêne la vision de près","Une opacification de la cornée","Un défaut de la rétine"]'::jsonb, 1, 'Le cristallin se bombe moins : l’accommodation devient insuffisante.', 8),
    ('0d7b14b8-4e46-5a66-b1e6-cd5be21482a0'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Quelle est la vergence de deux lentilles accolées de + 3 δ et − 1 δ ?', 'mcq', '["+ 4 δ","+ 2 δ","− 3 δ","+ 3 δ"]'::jsonb, 1, 'V = V₁ + V₂ = 3 + (− 1) = + 2 δ.', 9),
    ('db2c28af-4019-5453-b3c1-94b81ea6336a'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Une loupe donne d’un objet placé entre F et O une image :', 'mcq', '["Réelle et renversée","Virtuelle, droite et agrandie","Réelle et réduite","Virtuelle et réduite"]'::jsonb, 1, 'C’est pourquoi on la regarde à travers la lentille, sans pouvoir la projeter sur un écran.', 10),
    ('8ae29308-02df-586d-b7cf-5e28fe933b24'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'L’accommodation consiste à bomber le cristallin pour voir net de près.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le cristallin plus bombé est plus convergent.', 11),
    ('9ceb894a-0f88-568f-9128-13ac3f61a242'::uuid, 'ae4a0fed-98a6-53c0-9b35-26a88c94c253'::uuid, 'Quel verre corrige l’hypermétropie ?', 'mcq', '["Une lentille divergente","Une lentille convergente","Aucun verre n’existe","Un verre teinté"]'::jsonb, 1, 'L’œil hypermétrope ne converge pas assez : on ajoute de la convergence.', 12),
    ('e30ee35e-56eb-5344-950f-60cd65e789b4'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Quelle relation relie le débit D, la vitesse v et la section S ?', 'mcq', '["D = v / S","D = v × S","D = S / v","D = v + S"]'::jsonb, 1, 'Le débit est le volume qui traverse la section par seconde : vitesse × section.', 1),
    ('c6f82458-288e-5fd4-a544-cb297222a3f6'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Si la section d’une artère diminue à débit constant, la vitesse du sang :', 'mcq', '["Diminue","Reste la même","Augmente","S’annule"]'::jsonb, 2, 'v = D / S : moins de section, plus de vitesse.', 2),
    ('977cae09-921d-5e0a-9bca-0d93bb07e260'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'fC = 60 battements/min et VES = 80 mL. Quel est le débit cardiaque ?', 'mcq', '["4,8 L/min","140 mL/min","0,75 L/min","48 L/min"]'::jsonb, 0, 'DC = 60 × 80 = 4 800 mL/min = 4,8 L/min.', 3),
    ('8ca2ad59-6b2b-502f-82bd-f1c6ac22c43e'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Quelle est l’unité internationale de pression ?', 'mcq', '["Le newton","Le pascal","Le bar","Le cmHg"]'::jsonb, 1, '1 Pa = 1 N/m².', 4),
    ('ca3112ed-e969-50b6-9d23-afa4e1ad8381'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Une force de 20 N s’exerce sur 0,010 m². Quelle est la pression ?', 'mcq', '["0,2 Pa","200 Pa","2 000 Pa","20 Pa"]'::jsonb, 2, 'P = F / S = 20 / 0,010 = 2 000 Pa.', 5),
    ('7e5ea41f-bb58-5a4c-abbc-d151178681ba'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Dans un liquide au repos, la pression :', 'mcq', '["Diminue avec la profondeur","Augmente avec la profondeur","Est la même partout","Ne dépend que de la surface"]'::jsonb, 1, 'P₂ − P₁ = ρ × g × (z₁ − z₂) : plus on descend, plus la pression est grande.', 6),
    ('b4a9a4b2-affa-5c29-82ed-fb40d353e6a9'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Que mesure un tensiomètre ?', 'mcq', '["La pression artérielle absolue","La différence entre la pression artérielle et la pression atmosphérique","Le débit cardiaque","La fréquence respiratoire"]'::jsonb, 1, 'C’est la tension artérielle, exprimée en cmHg ou mmHg.', 7),
    ('01824360-5c11-515e-92e9-e0515043bd1b'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Une tension de « 12/8 » signifie :', 'mcq', '["12 mmHg de systolique et 8 mmHg de diastolique","12 cmHg de systolique et 8 cmHg de diastolique","12 battements pour 8 respirations","12 bar et 8 bar"]'::jsonb, 1, 'Soit 120/80 mmHg, une valeur normale.', 8),
    ('39a8fc60-769f-5bf5-b506-a2e789692dd2'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'La tension systolique correspond :', 'mcq', '["Au relâchement du cœur","À la contraction du cœur","À la pause entre deux battements","À la pression veineuse"]'::jsonb, 1, 'C’est la valeur maximale, pendant l’éjection du sang par les ventricules.', 9),
    ('59278caf-d04c-5e3e-9e36-57453d3ecff7'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Pourquoi place-t-on une poche de perfusion au-dessus du patient ?', 'mcq', '["Pour la garder au frais","Pour que la pression du liquide soit supérieure à celle du sang veineux","Pour réduire le débit à zéro","Pour la stériliser"]'::jsonb, 1, 'La différence de hauteur crée une surpression qui fait entrer le liquide dans la veine.', 10),
    ('4356b4a2-ac22-5010-b7ff-128a1acf5b1a'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Combien de pascals vaut environ 1 cmHg ?', 'mcq', '["13 Pa","133 Pa","1 333 Pa","100 000 Pa"]'::jsonb, 2, '1 mmHg ≈ 133 Pa, donc 1 cmHg ≈ 1 333 Pa.', 11),
    ('2f1ac736-eb53-5633-b17b-617a635ebf89'::uuid, 'ec228ae6-0a50-58d5-aa59-1e5436b0c60d'::uuid, 'Une tension durablement supérieure ou égale à 14/9 définit l’hypertension artérielle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Soit 140/90 mmHg : c’est le seuil habituel de l’hypertension chez l’adulte.', 12),
    ('a7bb10a0-ed67-5eec-85fb-cc2d963bcaa6'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Combien de liaisons covalentes forme un atome de carbone ?', 'mcq', '["1","2","3","4"]'::jsonb, 3, 'Le carbone est tétravalent : c’est ce qui lui permet de former de longues chaînes.', 1),
    ('090d9249-a141-5f1f-aa92-b68fdf2f153a'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Combien de liaisons covalentes forme un atome d’azote ?', 'mcq', '["1","2","3","4"]'::jsonb, 2, 'L’azote est trivalent, comme dans l’ammoniac NH₃.', 2),
    ('300013d1-f2f9-5b27-81b7-a65fffcac83a'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Quel groupe caractérise la fonction acide carboxylique ?', 'mcq', '["–OH","–CHO","–COOH","–NH₂"]'::jsonb, 2, 'On le trouve dans l’acide éthanoïque du vinaigre.', 3),
    ('e7fd2386-58e4-5d64-9dd2-2f605b1cb6b2'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'CH₃–CO–CH₃ (propanone) possède une fonction :', 'mcq', '["Aldéhyde","Cétone","Alcool","Ester"]'::jsonb, 1, 'Le groupe C=O est au milieu de la chaîne : c’est une cétone.', 4),
    ('55083dc1-9eb9-5e70-aeb5-5543f3b16c46'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Que sont deux isomères de constitution ?', 'mcq', '["Deux molécules identiques","Deux molécules de même formule brute mais de formules développées différentes","Deux molécules de même masse mais de formules brutes différentes","Deux atomes du même élément"]'::jsonb, 1, 'Même composition, enchaînement différent : ce sont deux espèces distinctes.', 5),
    ('fc500b85-313c-58e5-afb3-e34e719b436c'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Quelle est la formule brute de l’éthanol CH₃–CH₂–OH ?', 'mcq', '["C₂H₅O","C₂H₆O","C₃H₈O","CH₄O"]'::jsonb, 1, '2 carbones, 5 + 1 = 6 hydrogènes et 1 oxygène.', 6),
    ('3c2166d5-5129-5294-8425-c625b3d98054'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Quel préfixe désigne une chaîne de trois carbones ?', 'mcq', '["Méth-","Éth-","Prop-","But-"]'::jsonb, 2, 'Méth- 1, éth- 2, prop- 3, but- 4.', 7),
    ('57f7d95a-ea00-51ec-9cd3-7cacbc87fbae'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Dans une formule topologique, les atomes de carbone et les hydrogènes qui leur sont liés ne sont pas écrits.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque sommet et chaque extrémité de la ligne brisée représente un carbone.', 8),
    ('f14af386-46a0-5f23-9707-f71e44864b59'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Le groupe –CO–NH– caractérise la fonction :', 'mcq', '["Amine","Amide","Ester","Étheroxyde"]'::jsonb, 1, 'C’est aussi la liaison peptidique qui unit les acides aminés.', 9),
    ('7811bddd-976f-5426-ac8a-2737c7e6c2a9'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Quelle terminaison porte le nom d’un aldéhyde ?', 'mcq', '["-ol","-one","-al","-oïque"]'::jsonb, 2, 'Éthanal, propanal : l’aldéhyde se termine en -al.', 10),
    ('f857b1e0-6615-5c24-adb5-8ab2adc986f7'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'C–O–C, un oxygène entre deux carbones, est le groupe caractéristique :', 'mcq', '["D’un étheroxyde","D’un alcool","D’un acide","D’une amine"]'::jsonb, 0, 'Exemple : le méthoxyméthane CH₃–O–CH₃, isomère de l’éthanol.', 11),
    ('0b667aea-fa06-5932-a667-eba333e9c865'::uuid, 'e6334284-a327-52b3-a77b-1ef0ce6e9c1f'::uuid, 'Le glucose et le fructose ont la même formule brute C₆H₁₂O₆.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont deux isomères : l’un porte une fonction aldéhyde, l’autre une fonction cétone.', 12),
    ('ea7025d3-d3be-5726-a88c-3039784d6e48'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Quelle fonction chimique distingue le glucose du fructose ?', 'mcq', '["Le glucose a une fonction aldéhyde, le fructose une cétone","Le glucose a une cétone, le fructose un aldéhyde","Le glucose n’a pas de fonction alcool","Le fructose a une fonction amine"]'::jsonb, 0, 'Ce sont des isomères : un aldose et un cétose de même formule C₆H₁₂O₆.', 1),
    ('834ddc98-3d9e-58eb-ab35-1500b2998e5d'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Qu’est-ce qu’un acide gras saturé ?', 'mcq', '["Un acide gras avec au moins une double liaison C=C","Un acide gras sans double liaison C=C","Un acide gras très soluble dans l’eau","Un acide gras à deux fonctions acide"]'::jsonb, 1, 'Sa chaîne ne comporte que des liaisons simples C–C, comme l’acide palmitique.', 2),
    ('bd605ebe-de41-5c77-a699-51470f4eba0d'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'L’acide oléique (18 carbones, une double liaison) est :', 'mcq', '["Saturé","Mono-insaturé","Poly-insaturé","Un stérol"]'::jsonb, 1, 'Une seule double liaison : mono-insaturé. On le trouve dans l’huile d’olive.', 3),
    ('d4e579f6-c433-50ac-a0dc-6027b2c89476'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Un triglycéride est formé :', 'mcq', '["De trois glucoses","D’un glycérol et de trois acides gras","De trois acides aminés","D’un cholestérol et d’un acide gras"]'::jsonb, 1, 'C’est un triester, forme de stockage des graisses dans le tissu adipeux.', 4),
    ('c0520e22-c3ff-524c-8e9b-0a719afd8691'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Un acide α-aminé porte sur le même carbone :', 'mcq', '["Deux fonctions alcool","Une fonction amine et une fonction acide carboxylique","Une fonction aldéhyde et une cétone","Deux fonctions amide"]'::jsonb, 1, 'Ce carbone commun est le carbone α.', 5),
    ('8d4ecd35-a378-52c3-beca-cfe46eb9092d'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Quelle liaison unit deux acides aminés dans une protéine ?', 'mcq', '["La liaison hydrogène","La liaison peptidique –CO–NH–","La liaison ester","La liaison ionique"]'::jsonb, 1, 'Elle se forme en libérant une molécule d’eau.', 6),
    ('d88f9b57-da93-5a4a-aec1-6a6b570f7d12'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'L’urée est le produit de dégradation :', 'mcq', '["Des glucides","Des lipides","Des protéines","Des vitamines"]'::jsonb, 2, 'Le foie transforme l’ammoniac issu des acides aminés en urée, éliminée par le rein.', 7),
    ('76106860-3cd2-577d-88b5-a29504932ceb'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Quelle propriété chimique explique le rôle antioxydant de la vitamine C ?', 'mcq', '["C’est un oxydant fort","C’est un réducteur","C’est une base forte","C’est un acide gras"]'::jsonb, 1, 'Elle cède facilement des électrons : elle s’oxyde à la place d’autres molécules.', 8),
    ('c42779a3-bdf4-5c0b-806a-24ee7c0b78b7'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Le lactose est formé de glucose et de galactose.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le sucre du lait, un diholoside de formule C₁₂H₂₂O₁₁.', 9),
    ('68376efa-6bcf-5e82-a31e-b39b262cc38c'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Combien de liaisons peptidiques compte un tripeptide ?', 'mcq', '["1","2","3","4"]'::jsonb, 1, 'Trois acides aminés en chaîne sont reliés par deux liaisons.', 10),
    ('aead8aff-b06f-51f1-9bdd-3948525bf4f5'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'Quel réactif met en évidence un sucre réducteur comme le glucose ?', 'mcq', '["L’eau de chaux","La liqueur de Fehling chauffée","Le papier pH","Le sulfate de cuivre anhydre"]'::jsonb, 1, 'Elle donne un précipité rouge brique en présence d’une fonction aldéhyde.', 11),
    ('5a9e0a48-e741-5d91-99e7-29973a8d09cd'::uuid, '0805a6a4-826c-5dd7-9ff7-a4266835db4b'::uuid, 'En solution, le glucose existe uniquement sous forme linéaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il existe sous forme linéaire et cyclique, la forme cyclique étant majoritaire.', 12),
    ('2a8376f2-e07b-5cfd-95b7-a07b5fec99c4'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Pourquoi la molécule d’eau est-elle polaire ?', 'mcq', '["Parce qu’elle est linéaire","Parce que l’oxygène, plus électronégatif, attire les électrons et que la molécule est coudée","Parce qu’elle contient des ions","Parce que l’hydrogène est plus électronégatif que l’oxygène"]'::jsonb, 1, 'Les charges partielles δ⁻ sur O et δ⁺ sur H ne se compensent pas dans une molécule coudée.', 1),
    ('cdb4175d-c21b-565d-ab2a-e0a06a8d10c8'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Quelle charge partielle porte l’atome d’oxygène dans l’eau ?', 'mcq', '["δ⁺","δ⁻","Aucune","2+"]'::jsonb, 1, 'Il attire vers lui les électrons des liaisons O–H.', 2),
    ('d24e4427-8ec8-5541-a088-029932dec73d'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Qu’est-ce qu’une liaison hydrogène ?', 'mcq', '["Une liaison covalente entre deux H","Une attraction entre un H δ⁺ et un atome très électronégatif d’une molécule voisine","Une liaison ionique forte","Une réaction chimique"]'::jsonb, 1, 'Elle est beaucoup plus faible qu’une liaison covalente.', 3),
    ('460567d0-3732-5819-9805-82ca38ca1eed'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Pourquoi la glace flotte-t-elle sur l’eau liquide ?', 'mcq', '["Elle est plus dense","Les liaisons hydrogène lui donnent une structure ouverte, moins dense","Elle contient de l’air","Elle est apolaire"]'::jsonb, 1, 'À masse égale, la glace occupe plus de volume que l’eau liquide.', 4),
    ('b262bf6b-4414-511f-b4cc-fef1ec0c7bd3'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'À quelle température l’eau pure bout-elle sous pression atmosphérique normale ?', 'mcq', '["0 °C","37 °C","100 °C","273 °C"]'::jsonb, 2, 'La fusion a lieu à 0 °C, la vaporisation à 100 °C.', 5),
    ('35f3bfe7-d20f-5473-bf57-d0db23d32fc7'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Pendant la fusion de la glace pure, la température :', 'mcq', '["Augmente régulièrement","Reste constante","Diminue","Oscille"]'::jsonb, 1, 'C’est le palier de changement d’état.', 6),
    ('1da4dfd7-65b6-564a-bc1d-b89642087a56'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Pourquoi le glucose est-il très soluble dans l’eau ?', 'mcq', '["Parce qu’il est apolaire","Parce que ses nombreuses fonctions –OH forment des liaisons hydrogène avec l’eau","Parce qu’il est plus dense que l’eau","Parce qu’il est gazeux"]'::jsonb, 1, 'Il est hydrophile.', 7),
    ('0616d9d5-1c77-5ab2-bb57-fb42a1013339'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Une huile de densité 0,92 et de l’eau non miscibles sont dans une ampoule à décanter. Où est l’huile ?', 'mcq', '["En bas","En haut","Mélangée à l’eau","Au milieu d’une troisième phase"]'::jsonb, 1, 'La phase la moins dense surnage.', 8),
    ('24e5fd6a-2ecd-5bc9-973a-c17dc363145f'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Dans une micelle de savon, les queues hydrophobes sont tournées :', 'mcq', '["Vers l’eau","Vers la gouttelette de graisse","Vers l’air","Au hasard"]'::jsonb, 1, 'Les têtes hydrophiles restent au contact de l’eau et emportent la graisse.', 9),
    ('850c40f0-efaf-5e39-96f1-9e6368fc0e26'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Deux liquides miscibles forment deux phases distinctes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Miscibles, ils forment un mélange homogène à une seule phase, comme l’eau et l’éthanol.', 10),
    ('8787aa23-9e4e-5a1a-b7e4-8f7d69146c1c'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Pourquoi l’évaporation de la sueur refroidit-elle la peau ?', 'mcq', '["La vaporisation est une transformation endothermique qui prélève de la chaleur au corps","La sueur est froide","La vaporisation dégage de la chaleur","La sueur bloque les rayons du Soleil"]'::jsonb, 0, 'Pour passer à l’état gazeux, l’eau absorbe de l’énergie prise à la peau.', 11),
    ('b93b9f63-330b-55ab-b186-5b9d882fe5ed'::uuid, 'c7645549-16bf-5dd2-9f74-d0d4661530fb'::uuid, 'Quel rôle jouent les sels biliaires dans l’intestin ?', 'mcq', '["Ils hydrolysent l’amidon","Ils forment des micelles qui dispersent les lipides","Ils neutralisent les protéines","Ils dissolvent le glucose"]'::jsonb, 1, 'Comme le savon, ils ont une partie hydrophile et une partie hydrophobe.', 12),
    ('c9ac9c34-29a8-5c45-89f8-8b466dbf8ac5'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Combien de joules vaut environ 1 calorie ?', 'mcq', '["1 J","4,18 J","41,8 J","1 000 J"]'::jsonb, 1, 'Une calorie élève de 1 °C la température de 1 g d’eau, soit environ 4,18 J.', 1),
    ('65bc64c2-5a21-5535-9454-b35ac6eab410'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Qu’est-ce que le métabolisme de base ?', 'mcq', '["L’énergie dépensée pendant le sport","L’énergie nécessaire aux fonctions vitales au repos","L’énergie contenue dans un repas","La chaleur perdue par la sueur"]'::jsonb, 1, 'Il représente la plus grande part de la dépense journalière d’une personne sédentaire.', 2),
    ('42315cdc-1385-5136-bd20-5d64dc92590c'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Quel nutriment apporte le plus d’énergie par gramme ?', 'mcq', '["Les glucides","Les protides","Les lipides","Les vitamines"]'::jsonb, 2, 'Environ 38 kJ/g, plus du double des glucides et des protides.', 3),
    ('be98d765-d130-5723-bd89-0a8328fe84ec'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Le vent qui refroidit la peau illustre un transfert thermique par :', 'mcq', '["Conduction","Convection","Rayonnement","Évaporation seule"]'::jsonb, 1, 'L’air en mouvement emporte la chaleur de la surface de la peau.', 4),
    ('041fd919-df53-57ff-9444-965e5d15ce2e'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Quelle énergie apportent 20 g de glucides ?', 'mcq', '["85 kJ","340 kJ","760 kJ","20 kJ"]'::jsonb, 1, '20 × 17 = 340 kJ.', 5),
    ('b0e12787-3cc0-5e90-9b55-0e3545acdb3c'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Un muscle en activité convertit l’énergie chimique en :', 'mcq', '["Énergie mécanique uniquement","Énergie mécanique et chaleur","Énergie électrique uniquement","Énergie nucléaire"]'::jsonb, 1, 'Le rendement est faible : l’essentiel devient chaleur.', 6),
    ('2af56e0b-6017-594c-b640-4bebc65343b2'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'La combustion du glucose est une transformation :', 'mcq', '["Endothermique","Exothermique","Sans effet thermique","Physique"]'::jsonb, 1, 'Elle libère de l’énergie, que l’organisme utilise.', 7),
    ('5c02f27e-d82e-5a32-b0b9-a4e4cf94c4c3'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Sur une étiquette alimentaire, le mot « calorie » désigne en fait la kilocalorie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une barre à « 250 calories » apporte 250 kcal, soit environ 1 045 kJ.', 8),
    ('a146ecad-1212-5b14-8ca0-e0d3b9cf942d'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Comment calcule-t-on la dépense énergétique journalière à partir du métabolisme de base ?', 'mcq', '["DEJ = MB + âge","DEJ = MB × coefficient d’activité","DEJ = MB / masse","DEJ = MB − 1 000"]'::jsonb, 1, 'Le coefficient, donné dans l’énoncé, dépend du niveau d’activité physique.', 9),
    ('76af962a-2d89-5cb3-965b-c11a0196f8fd'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Le rayonnement est un transfert de chaleur qui nécessite un contact.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le rayonnement infrarouge se fait sans contact ; c’est la conduction qui en exige un.', 10),
    ('a47d5591-c553-51ce-9141-654135986f96'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Un aliment apporte 10 g de lipides et 30 g de glucides. Quelle énergie ?', 'mcq', '["890 kJ","400 kJ","1 650 kJ","550 kJ"]'::jsonb, 0, '10 × 38 + 30 × 17 = 380 + 510 = 890 kJ.', 11),
    ('246d8346-1b52-5a92-9a10-e175f6059e3b'::uuid, 'e74c1527-2de9-55ce-9574-bdb3aeb3f69b'::uuid, 'Quelles données la relation de Harris et Benedict utilise-t-elle ?', 'mcq', '["Le pH sanguin et la glycémie","La masse, la taille, l’âge et le sexe","La tension artérielle","La fréquence cardiaque seule"]'::jsonb, 1, 'Elle estime le métabolisme de base selon ces caractéristiques de la personne.', 12),
    ('0eb465d2-0660-5d95-b4fb-c28d14e596fa'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Qu’est-ce qu’une réaction d’hydrolyse ?', 'mcq', '["La coupure d’une molécule par réaction avec l’eau","La combustion d’une molécule","La formation d’eau à partir de H₂ et O₂","La dissolution d’un sel"]'::jsonb, 0, 'L’hydrolyse du lactose donne du glucose et du galactose.', 1),
    ('f705b1d3-4fd3-57dd-ba21-418e8b831241'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Quelle est l’équation de la respiration (filière aérobie) du glucose ?', 'mcq', '["C₆H₁₂O₆ → 2 C₃H₆O₃","C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O","C₆H₁₂O₆ + H₂O → 2 C₃H₆O₃","6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂"]'::jsonb, 1, 'Combustion complète : le glucose est entièrement oxydé en CO₂ et en eau.', 2),
    ('35cee2e9-7bad-5bae-b8f6-aee8bea8e72b'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Que produit la fermentation lactique du glucose ?', 'mcq', '["Du dioxyde de carbone et de l’eau","De l’éthanol","De l’acide lactique","Du glycogène"]'::jsonb, 2, 'C₆H₁₂O₆ → 2 C₃H₆O₃, sans dioxygène.', 3),
    ('a56708d9-a8ed-5dd3-847f-9d11f0ede0a2'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'L’amidon et le glycogène sont des polymères du glucose.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont des glucides complexes, végétal pour l’un, animal pour l’autre.', 4),
    ('98d67197-2329-5672-bd54-c9d936efaf1a'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Où le glycogène est-il stocké ?', 'mcq', '["Dans le sang","Dans le foie et les muscles","Dans les os","Dans les reins"]'::jsonb, 1, 'Le glycogène du foie sert à maintenir la glycémie entre les repas.', 5),
    ('5a847d08-b9fe-5df5-8154-57e42b79f020'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Quels sont les produits de l’hydrolyse du lactose ?', 'mcq', '["Deux glucoses","Glucose et fructose","Glucose et galactose","Amidon et eau"]'::jsonb, 2, 'C₁₂H₂₂O₁₁ + H₂O → glucose + galactose.', 6),
    ('f2908eb5-f1c7-5148-860c-52e56560a504'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Quel réactif permet de suivre l’hydrolyse de l’amidon ?', 'mcq', '["L’eau de chaux","L’eau iodée","La phénolphtaléine","Le nitrate d’argent"]'::jsonb, 1, 'Elle bleuit en présence d’amidon ; la couleur disparaît quand tout l’amidon est hydrolysé.', 7),
    ('18c9166b-6b8f-56a7-b823-fbdbfc6c546c'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Quelle filière libère le plus d’énergie par molécule de glucose ?', 'mcq', '["La filière anaérobie","La filière aérobie","Les deux libèrent autant","Aucune ne libère d’énergie"]'::jsonb, 1, 'L’oxydation complète en CO₂ et H₂O libère bien plus d’énergie que la fermentation.', 8),
    ('39550914-acbb-56c7-bee3-2ca4cc061658'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Quelle est la formule de l’acide pyruvique ?', 'mcq', '["C₃H₆O₃","C₃H₄O₃","C₆H₁₂O₆","C₂H₆O"]'::jsonb, 1, 'C₃H₆O₃ est l’acide lactique ; l’acide pyruvique a deux hydrogènes de moins.', 9),
    ('fd1fbdb5-7357-5a13-943e-aa1356996eda'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Pourquoi la consommation de dioxygène augmente-t-elle chez le sportif ?', 'mcq', '["Pour produire plus d’acide lactique","Pour oxyder davantage de nutriments et fournir l’énergie aux muscles","Pour stocker du glycogène","Pour éliminer l’urée"]'::jsonb, 1, 'La filière aérobie exige du dioxygène : respiration et cœur s’accélèrent.', 10),
    ('ebba6d2b-20a7-5e20-a2ef-1afe732cb610'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Quelle hormone fait baisser la glycémie ?', 'mcq', '["Le glucagon","L’insuline","L’adrénaline","La thyroxine"]'::jsonb, 1, 'L’insuline favorise l’entrée du glucose dans les cellules et son stockage en glycogène.', 11),
    ('9b8e47f4-14a0-5241-a952-9910618f70b3'::uuid, 'bd5ff720-50e8-5a96-a4af-cba9d2778e9f'::uuid, 'Combien de molécules de dioxygène faut-il pour brûler complètement 2 molécules d’acide pyruvique ?', 'mcq', '["2","3","5","6"]'::jsonb, 2, '2 C₃H₄O₃ + 5 O₂ → 6 CO₂ + 4 H₂O.', 12),
    ('f8d781d9-c44a-513c-afaf-3da51215b188'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Quelle est la limite de qualité des nitrates dans l’eau du robinet ?', 'mcq', '["0,1 mg/L","5 mg/L","50 mg/L","500 mg/L"]'::jsonb, 2, 'Au-delà de 50 mg/L, l’eau n’est pas conforme, en particulier pour les nourrissons et les femmes enceintes.', 1),
    ('fb8c153f-7541-5f50-9276-ad5f661b0f04'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Qu’est-ce que l’eutrophisation ?', 'mcq', '["La purification naturelle d’une rivière","La prolifération d’algues due à un excès de nitrates et de phosphates, puis le manque de dioxygène","La salinisation des sols","L’acidification des pluies"]'::jsonb, 1, 'Les algues en excès se décomposent et consomment le dioxygène de l’eau.', 2),
    ('98cd3082-e11f-5a3f-b593-61b89c84b50d'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Pourquoi le complexe argilo-humique retient-il les ions potassium K⁺ ?', 'mcq', '["Parce qu’il est chargé positivement","Parce qu’il est chargé négativement et attire les cations","Parce qu’il est imperméable","Parce que K⁺ est insoluble"]'::jsonb, 1, 'Il retient les cations et les échange avec la solution du sol.', 3),
    ('e97f0052-8e5b-5dad-8fda-649c226c66fa'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Les ions nitrate NO₃⁻ sont fortement retenus par le sol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Étant des anions, ils ne sont pas retenus par le complexe argilo-humique et sont lessivés vers les nappes.', 4),
    ('2c54426a-4d77-56d8-bb98-1d2058d90a74'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Quel élément d’un engrais NPK favorise surtout la croissance des feuilles ?', 'mcq', '["L’azote N","Le phosphore P","Le potassium K","Le calcium Ca"]'::jsonb, 0, 'L’azote, apporté sous forme de nitrates, est essentiel à la croissance végétative.', 5),
    ('1b18ba0e-f833-590b-ad9d-bb698a9ee505'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Un fongicide sert à lutter contre :', 'mcq', '["Les insectes","Les champignons","Les mauvaises herbes","Les rongeurs"]'::jsonb, 1, 'Du latin fungus, champignon.', 6),
    ('ae7fa19c-8f84-546e-a527-712de902ff71'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Comment interpréter le résultat d’analyse d’une eau ?', 'mcq', '["En le comparant aux valeurs de référence réglementaires","En regardant sa couleur seulement","En mesurant sa température","En le comparant à une autre eau au hasard"]'::jsonb, 0, 'Chaque paramètre a une limite de qualité à laquelle on compare la valeur mesurée.', 7),
    ('a91e6ba9-1bb9-559b-b87a-f27536f76649'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Quelle est l’origine principale des nitrates en excès dans les nappes ?', 'mcq', '["Les eaux de pluie pures","Les engrais agricoles","Les roches volcaniques","Le chlore de l’eau du robinet"]'::jsonb, 1, 'L’apport d’engrais azotés supérieur aux besoins des plantes est lessivé vers les nappes.', 8),
    ('4e2b8b79-5c3e-526c-b296-d875e0bb49a3'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Quel principe utilise le dosage par échelle de teinte ?', 'mcq', '["Comparer la couleur de l’échantillon à celle de solutions de concentrations connues","Mesurer le pH","Peser le résidu sec","Mesurer la conductivité"]'::jsonb, 0, 'L’échantillon a une concentration comprise entre celles des deux solutions qui l’encadrent.', 9),
    ('cfae49f0-bdc6-5512-a9a8-3fc42c063ced'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Une eau très riche en sodium est déconseillée en cas d’hypertension.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le sodium favorise la rétention d’eau et l’élévation de la pression artérielle.', 10),
    ('fd46ad56-5fcb-5f25-b7cf-7580d44016c8'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Quelle est la limite de qualité pour chaque pesticide dans l’eau du robinet ?', 'mcq', '["0,1 µg/L","0,1 g/L","50 mg/L","1 mg/L"]'::jsonb, 0, 'Une limite très basse, par précaution.', 11),
    ('e6787146-7e3e-59fc-ab7e-24ad2217496f'::uuid, '8db3b3d9-5aef-55fa-bf8f-b4920f14a1e4'::uuid, 'Quel problème pose la production de biocarburant à partir de céréales ?', 'mcq', '["Elle ne produit aucune énergie","Elle entre en compétition avec l’alimentation humaine pour les terres","Elle rend l’eau non potable","Elle détruit le complexe argilo-humique"]'::jsonb, 1, 'Les mêmes surfaces agricoles ne peuvent nourrir et produire du carburant à la fois.', 12),
    ('a7c2f453-4526-5c7b-9dc2-54e9140f55d7'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Comment la physique-chimie pour la santé est-elle évaluée au bac ST2S ?', 'mcq', '["Par une épreuve écrite de 4 heures en terminale","Par le contrôle continu de l’année de première","Par un oral en fin de terminale","Elle n’est pas évaluée"]'::jsonb, 1, 'C’est une spécialité suivie seulement en première : c’est ta moyenne de l’année qui compte.', 1),
    ('2b1fee15-b64a-59c2-bc93-b0b538f55b56'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Pour une série de n mesures d’écart-type σ, l’incertitude-type sur la moyenne vaut :', 'mcq', '["σ × n","σ / √n","σ + n","√σ / n"]'::jsonb, 1, 'Plus on fait de mesures, plus l’incertitude-type sur la moyenne diminue.', 2),
    ('80c9a636-d41f-5623-a11a-01d52320654d'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Que mesure l’écart-type d’une série de mesures ?', 'mcq', '["La valeur vraie","La dispersion des mesures autour de la moyenne","Le nombre de mesures","L’erreur de l’instrument seulement"]'::jsonb, 1, 'Plus il est grand, plus les mesures sont dispersées.', 3),
    ('a3f2cf96-e11a-5ac0-bbf3-559dd878c82c'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Quelle est la première étape d’un calcul bien rédigé ?', 'mcq', '["Donner directement le résultat","Écrire la relation littérale","Arrondir les données","Dessiner un schéma"]'::jsonb, 1, 'La relation littérale montre la méthode et rapporte des points même en cas d’erreur de calcul.', 4),
    ('de4a39e4-6009-56ff-8887-3d35d5920379'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Un élève trouve un débit cardiaque de 480 L/min au repos. Que doit-il faire ?', 'mcq', '["Le garder, c’est normal","Vérifier les unités : l’ordre de grandeur est absurde (≈ 5 L/min attendu)","L’arrondir à 500 L/min","Le multiplier par 60"]'::jsonb, 1, 'Le contrôle de l’ordre de grandeur repère les erreurs de conversion.', 5),
    ('80fdf5ca-a53c-5b13-80d2-5a6afce33dd5'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Comment écrire correctement un résultat de mesure ?', 'mcq', '["Valeur seule","Valeur ± incertitude, avec l’unité","Incertitude seule","Valeur avec dix décimales"]'::jsonb, 1, 'Exemple : C = 0,152 ± 0,003 mol/L.', 6),
    ('27cc262a-db0e-5fee-9e36-d275939252eb'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Face à une question « Justifier », que faut-il faire ?', 'mcq', '["Recopier le document","Donner une raison appuyée sur une donnée ou une connaissance","Répondre par oui ou non","Faire un calcul sans conclusion"]'::jsonb, 1, 'Justifier, c’est prouver : un argument, une donnée, une conclusion.', 7),
    ('244f46a7-77f2-5933-95d8-ef77c3422194'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Dans la loi de Wien, la température doit être exprimée en :', 'mcq', '["Degrés Celsius","Kelvins","Degrés Fahrenheit","Joules"]'::jsonb, 1, 'T = θ + 273 ; oublier la conversion fausse complètement le résultat.', 8),
    ('260106bd-f424-596a-88ed-622747113880'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Une réponse de calcul sans unité peut être correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans unité, un résultat de physique-chimie n’a pas de sens et perd des points.', 9),
    ('a821c484-bcde-5289-918d-cd9e1ac7ebdc'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Combien de chiffres significatifs garde-t-on en général dans un résultat ?', 'mcq', '["Le plus grand nombre de ceux des données","Le plus petit nombre de ceux des données","Toujours cinq","Autant que la calculatrice en affiche"]'::jsonb, 1, 'Le résultat ne peut pas être plus précis que la donnée la moins précise.', 10),
    ('7d5838a8-616b-5a12-b52c-54afac6a2a5a'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Que montre l’histogramme d’une série de mesures ?', 'mcq', '["La répartition des valeurs mesurées","L’équation de la réaction","La valeur vraie exacte","La date de la mesure"]'::jsonb, 0, 'Il permet de visualiser la dispersion et d’en discuter l’origine.', 11),
    ('47522563-d524-513e-823e-a49b011549c5'::uuid, 'ec87fa33-0088-553f-b8ae-cb49d287bc81'::uuid, 'Avant de répondre à une question sur un document, il faut d’abord :', 'mcq', '["Repérer le verbe de la consigne et prélever les données utiles","Recopier tout le document","Répondre de mémoire sans lire le document","Chercher la réponse dans un autre exercice"]'::jsonb, 0, 'Le verbe dit ce qu’on attend ; les données citées prouvent la réponse.', 12),
    ('4daade68-9d4f-5be8-bbc6-9b568d0df0b0'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Quelle définition de la santé l’OMS a-t-elle adoptée en 1946 ?', 'mcq', '["L’absence de maladie","Un état de complet bien-être physique, mental et social","La capacité à travailler","Le silence des organes"]'::jsonb, 1, 'Elle ne se limite pas à l’absence de maladie ou d’infirmité.', 1),
    ('2ad1070b-e2c4-52f0-8efa-e5f324ba8468'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Quelle approche définit la santé comme l’absence de maladie ou de lésion ?', 'mcq', '["L’approche globale","L’approche biomédicale","L’approche subjective","L’approche sociale"]'::jsonb, 1, 'C’est la vision médicale classique, centrée sur la maladie.', 2),
    ('45fcc8d8-dedc-55c8-a927-3a84eec87943'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Que signifie la relativité de la santé ?', 'mcq', '["La santé est la même pour tous","La perception de la santé varie selon la culture, l’époque, le groupe social","La santé ne dépend que de la génétique","La santé n’existe pas"]'::jsonb, 1, 'Ce qui est considéré comme sain change selon les sociétés et les personnes.', 3),
    ('4ebf7b63-2f9b-5656-a8ad-13d2c90a1c13'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'La santé publique s’intéresse avant tout :', 'mcq', '["À un patient particulier","À la santé des populations","Aux seuls hôpitaux","Aux maladies rares uniquement"]'::jsonb, 1, 'Elle mesure, analyse et agit collectivement.', 4),
    ('af6a77b0-84f3-5505-a75c-7305d78ac330'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Quel document de 1986 présente la santé comme une ressource de la vie quotidienne ?', 'mcq', '["La Déclaration des droits de l’homme","La charte d’Ottawa","Le serment d’Hippocrate","Le Code de la route"]'::jsonb, 1, 'Elle fonde la promotion de la santé.', 5),
    ('41b51b59-8831-55f8-82a0-eb6fc0cd42b6'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Une personne diabétique bien équilibrée peut se sentir en bonne santé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’approche subjective : la santé ressentie ne se confond pas avec l’absence de maladie.', 6),
    ('56dade72-72b5-5a2e-bff9-10d35ff8dc85'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Quelle critique adresse-t-on à la définition de l’OMS ?', 'mcq', '["Elle est trop médicale","Elle décrit un idéal difficile à atteindre","Elle oublie le bien-être social","Elle ne concerne que les enfants"]'::jsonb, 1, 'Un « complet » bien-être est rarement atteint.', 7),
    ('58d8842a-7ba8-5246-925a-7415e614be79'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Lequel est une préoccupation actuelle de santé publique en France ?', 'mcq', '["La peste","Le vieillissement et les maladies chroniques","La lèpre","Le scorbut"]'::jsonb, 1, 'Cancers, maladies cardio-vasculaires et diabète pèsent lourd dans la mortalité et les dépenses.', 8),
    ('6ef34a9f-affc-5363-ae0b-58e4554b4c6a'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Que désigne la santé collective ?', 'mcq', '["L’état de santé d’un groupe, mesuré par des indicateurs","La santé d’un seul patient","Le bien-être ressenti par une personne","Le budget de l’hôpital"]'::jsonb, 0, 'On la mesure par l’espérance de vie, la mortalité, la morbidité…', 9),
    ('73d46fd4-892f-556c-bb4d-64b92b7aefcf'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Selon Winslow, la santé publique est « la science et l’art » de :', 'mcq', '["Guérir chaque malade","Prévenir les maladies, prolonger la vie et promouvoir la santé par des efforts collectifs","Construire des hôpitaux","Former des médecins"]'::jsonb, 1, 'L’accent est mis sur l’action organisée de la collectivité.', 10),
    ('3c8a2bd7-860a-50b8-9da9-add3e424739f'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Quelle approche de la santé insiste sur la capacité à accomplir ses activités ?', 'mcq', '["Biomédicale","Fonctionnelle","Épidémiologique","Juridique"]'::jsonb, 1, 'Elle intéresse particulièrement le handicap et le vieillissement.', 11),
    ('0a0c1028-2f5f-58dd-899f-95d98fdc2995'::uuid, '4db3423d-45ba-5e20-bf02-7924dad72353'::uuid, 'Une question de santé devient une préoccupation publique seulement si elle est très coûteuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comptent aussi sa fréquence, sa gravité, son caractère évitable et la perception sociale.', 12),
    ('c546a164-5f7f-5fd5-a37e-e5f16f7b3b42'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Qu’est-ce que la socialisation ?', 'mcq', '["L’inscription à la Sécurité sociale","Le processus par lequel on intériorise les normes et valeurs de la société","L’adhésion à un parti politique","Le fait de se faire des amis en ligne"]'::jsonb, 1, 'Elle construit l’identité sociale de la personne.', 1),
    ('e60ca406-73fc-5d33-84cb-33829f52404a'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Quelle est la principale instance de socialisation primaire ?', 'mcq', '["L’entreprise","La famille","Le syndicat","Le conseil municipal"]'::jsonb, 1, 'Pendant l’enfance, la famille transmet les premières normes.', 2),
    ('e13d3532-5c64-5228-8dc2-f6677e357046'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Quelle est la différence entre une valeur et une norme ?', 'mcq', '["Aucune","La valeur est un idéal, la norme une règle de conduite qui en découle","La norme est un idéal, la valeur une règle","La valeur est une loi écrite"]'::jsonb, 1, 'La valeur « respect » se traduit par des normes concrètes comme dire bonjour.', 3),
    ('83888bb6-8a6f-5f82-b553-b8d56b12c2f7'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Le lien de citoyenneté unit :', 'mcq', '["Les parents et les enfants","Les amis","Les membres d’une même nation, égaux en droits","Les collègues de travail"]'::jsonb, 2, 'C’est l’un des quatre liens distingués par Serge Paugam.', 4),
    ('355c2f3d-2735-51ce-9ef5-47ffbc886284'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Quel lien unit les membres d’un même monde du travail ?', 'mcq', '["Le lien de filiation","Le lien de participation élective","Le lien de participation organique","Le lien de citoyenneté"]'::jsonb, 2, 'Il apporte reconnaissance par le travail et protection par l’emploi.', 5),
    ('11fe916a-70ae-5c83-8d8f-02b927d615c8'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Qu’est-ce que la cohésion sociale ?', 'mcq', '["L’obéissance aux lois","La capacité d’une société à assurer le bien-être de tous et à éviter la marginalisation","L’uniformité des opinions","La richesse d’un pays"]'::jsonb, 1, 'Elle repose sur la réduction des disparités et la participation de tous.', 6),
    ('a57a7509-bb12-546e-8696-24eaf59d5fbd'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'La socialisation s’arrête à la fin de l’enfance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La socialisation secondaire se poursuit toute la vie : travail, associations, médias.', 7),
    ('356beda9-a90b-509f-8862-24db8f4249e2'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Lequel est un facteur de fragilisation de la cohésion sociale ?', 'mcq', '["La vie associative","Le chômage de longue durée","L’école","La protection sociale"]'::jsonb, 1, 'Il affaiblit les liens de participation organique et peut conduire à l’isolement.', 8),
    ('d00eeb98-fd04-57a1-aeb7-829e3df6783d'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Comment les normes sociales influencent-elles la santé ?', 'mcq', '["Elles n’ont aucun effet","Les habitudes de vie (alimentation, sport, tabac) sont apprises dans les groupes","Elles ne concernent que la politesse","Elles déterminent le groupe sanguin"]'::jsonb, 1, 'Les comportements de santé sont en partie des comportements sociaux.', 9),
    ('058bd8a0-b86b-5951-b96b-27d23d2194cc'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Qu’est-ce que la stratification sociale ?', 'mcq', '["La division de la société en groupes hiérarchisés","L’organisation des cours au lycée","La géologie des sols","La hiérarchie des hôpitaux"]'::jsonb, 0, 'Revenu, diplôme, profession et prestige hiérarchisent les groupes.', 10),
    ('10b90a21-7073-500c-8920-04d1fc27e85a'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Le bien-être associe des éléments objectifs et subjectifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Revenus et logement d’une part, satisfaction et reconnaissance d’autre part.', 11),
    ('7da6ff71-0008-56fb-91d8-6aa28f0c3748'::uuid, 'f045bf49-bf4c-540c-90ba-40a10035c6c2'::uuid, 'Quel exemple relève d’un lien de participation élective ?', 'mcq', '["La relation entre un père et sa fille","Une amitié choisie","Le fait d’être électeur","La relation entre un salarié et son entreprise"]'::jsonb, 1, 'Ce sont les liens que l’on choisit : amis, couple, proches.', 12),
    ('86adf5cd-4555-5152-9539-f65a1b5913a6'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Comment calcule-t-on le taux de mortalité infantile ?', 'mcq', '["Décès de moins d’un an / population totale × 1 000","Décès de moins d’un an / naissances vivantes × 1 000","Naissances / décès × 100","Décès avant 65 ans / population × 1 000"]'::jsonb, 1, 'On rapporte les décès d’enfants de moins d’un an aux naissances vivantes de l’année.', 1),
    ('5e3b4167-cb1c-5409-a38c-0ab0fc1202d7'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Qu’est-ce que l’incidence d’une maladie ?', 'mcq', '["Le nombre de cas existants à un moment donné","Le nombre de nouveaux cas apparus pendant une période","Le nombre de décès dus à la maladie","Le coût de la maladie"]'::jsonb, 1, 'La prévalence, elle, compte tous les cas existants.', 2),
    ('c845fec3-978d-55ab-9d0b-cf8962eb7d1f'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Pourquoi la prévalence du diabète augmente-t-elle même à incidence stable ?', 'mcq', '["Parce qu’on en guérit plus vite","Parce que les malades vivent plus longtemps avec la maladie","Parce que les tests sont faux","Parce que la population diminue"]'::jsonb, 1, 'Les cas s’accumulent : on les soigne sans les guérir.', 3),
    ('5c73baaa-a357-54aa-9c53-61d8d6b8ab92'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Quelle est l’espérance de vie à la naissance des femmes en France au milieu des années 2020, environ ?', 'mcq', '["75 ans","80 ans","85 ans et demi","95 ans"]'::jsonb, 2, 'Celle des hommes est d’environ 80 ans.', 4),
    ('55e47b0d-7354-5ac0-99f8-0e55afdda5c2'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Qu’est-ce qu’un indicateur composite ?', 'mcq', '["Un indicateur qui combine plusieurs dimensions","Un indicateur faux","Un taux pour 1 000","Une donnée brute sans calcul"]'::jsonb, 0, 'L’IDH combine santé, éducation et niveau de vie.', 5),
    ('d1bef513-153d-56f2-9f8e-3bec758e4805'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Que mesure l’espérance de vie sans incapacité ?', 'mcq', '["Le nombre d’années vécues à l’hôpital","Les années que l’on peut espérer vivre sans limitation dans ses activités","L’espérance de vie des personnes handicapées","L’âge moyen de la retraite"]'::jsonb, 1, 'Elle associe durée de vie et qualité de vie.', 6),
    ('24a94d06-bcc2-5d9c-991e-d3164e7a37d2'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Pourquoi utilise-t-on un taux standardisé pour comparer deux régions ?', 'mcq', '["Pour gonfler les chiffres","Pour neutraliser l’effet des différences de structure par âge","Parce que le taux brut est interdit","Pour compter les naissances"]'::jsonb, 1, 'Une région âgée aurait sinon toujours une mortalité plus élevée.', 7),
    ('4c7d9dba-6c3e-5324-a651-151041c5239d'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Quel organisme produit les données démographiques officielles en France ?', 'mcq', '["L’INSEE","L’Urssaf","La CAF","L’Unédic"]'::jsonb, 0, 'Naissances, décès, espérance de vie : l’INSEE publie chaque année un bilan démographique.', 8),
    ('a8d257ab-ab94-5226-a710-2f8bb78da0e2'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Santé publique France assure la surveillance épidémiologique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle suit les épidémies, lance les alertes et diffuse les données.', 9),
    ('3ff7ba40-a959-550c-883e-b682b730e974'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Que désigne la morbidité ?', 'mcq', '["Le nombre de décès","Les maladies présentes dans une population","La natalité","Le nombre de médecins"]'::jsonb, 1, 'Elle se mesure par l’incidence et la prévalence.', 10),
    ('45107bbf-5892-51d7-8cc7-45be29f35acc'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'À quel âge fixe-t-on en France le seuil de la mortalité prématurée ?', 'mcq', '["1 an","18 ans","65 ans","85 ans"]'::jsonb, 2, 'Une grande part de ces décès est considérée comme évitable.', 11),
    ('2a56f93e-2f3b-5110-a979-b96d057fb9cb'::uuid, '2419d365-741a-5028-b4ab-a78c37417dfb'::uuid, 'Un seul indicateur suffit à décrire l’état de santé d’une population.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque indicateur éclaire une dimension : il faut les croiser.', 12),
    ('22a4ce76-c19d-572e-a998-75ef03cba495'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Qu’est-ce qu’une inégalité sociale de santé ?', 'mcq', '["Toute différence biologique entre personnes","Une différence de santé socialement construite, systématique et évitable","Une maladie génétique","Une différence de taille"]'::jsonb, 1, 'Elle est jugée injuste parce qu’elle pourrait être réduite.', 1),
    ('91a02082-738f-5152-8353-653c7c159b82'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Que désigne le gradient social de santé ?', 'mcq', '["Seuls les plus pauvres sont en mauvaise santé","L’état de santé s’améliore à chaque échelon de la hiérarchie sociale","La santé ne dépend pas du milieu social","Les riches sont toujours malades"]'::jsonb, 1, 'Chaque catégorie a une santé meilleure que celle qui est juste en dessous.', 2),
    ('20a55977-178e-5665-a4aa-247f6e896257'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Où est fixé le seuil de pauvreté monétaire en France ?', 'mcq', '["À 50 % du revenu moyen","À 60 % du niveau de vie médian","Au SMIC","Au RSA"]'::jsonb, 1, 'C’est la convention retenue par l’INSEE et Eurostat.', 3),
    ('85ee08b4-2b24-5702-9d29-e52d2b5d3192'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Quel est l’écart d’espérance de vie entre les 5 % d’hommes les plus aisés et les 5 % les plus modestes ?', 'mcq', '["Environ 2 ans","Environ 13 ans","Environ 30 ans","Aucun écart"]'::jsonb, 1, 'C’est l’une des mesures les plus frappantes du gradient social.', 4),
    ('4140343d-b433-5e44-9041-f3004a1d265d'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Qu’est-ce que le niveau de vie médian ?', 'mcq', '["La moyenne des revenus","Le niveau de vie qui partage la population en deux moitiés","Le revenu minimum légal","Le revenu des 10 % les plus riches"]'::jsonb, 1, 'La moitié de la population a un niveau de vie inférieur, l’autre moitié supérieur.', 5),
    ('989e366a-2456-522c-8b41-50cdb98703a7'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Quelle part de la population française vit sous le seuil de pauvreté monétaire, environ ?', 'mcq', '["2 %","15 %","40 %","60 %"]'::jsonb, 1, 'Plus de 9 millions de personnes, selon l’INSEE.', 6),
    ('ad0235c2-73d6-57d7-98b2-c217d70e0880'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Qu’est-ce qu’un désert médical ?', 'mcq', '["Une région sans hôpital militaire","Un territoire où l’accès aux médecins est insuffisant","Une zone sans pharmacie de garde uniquement","Un hôpital sans patient"]'::jsonb, 1, 'Il accentue les inégalités territoriales de santé.', 7),
    ('36d573df-c477-52bd-b1fd-708ee1cc725c'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Une disparité est toujours une inégalité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une disparité est une différence constatée ; elle devient inégalité quand elle est socialement construite et injuste.', 8),
    ('b29a006e-f5ba-5605-ad62-d5ec1a74af7f'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Que mesure le rapport interdécile D9/D1 ?', 'mcq', '["Le taux de chômage","L’écart entre les niveaux de vie des plus aisés et des plus modestes","La mortalité infantile","Le nombre de médecins"]'::jsonb, 1, 'Plus il est élevé, plus les niveaux de vie sont inégaux.', 9),
    ('ea3a409a-44af-5a44-b350-15a8ac556376'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Pourquoi le taux de pauvreté monétaire doit-il être complété par d’autres indicateurs ?', 'mcq', '["Parce qu’il est illégal","Parce qu’il ignore le patrimoine, les aides en nature et le ressenti","Parce qu’il ne concerne que les enfants","Parce qu’il est toujours faux"]'::jsonb, 1, 'On le croise avec la privation matérielle et sociale.', 10),
    ('37fcd3a4-95b6-5cf0-8537-12b77110e90b'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Le renoncement aux soins est plus fréquent chez les personnes à faibles revenus.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le coût, la distance et le manque d’information freinent l’accès aux soins.', 11),
    ('3dcc9afb-acec-59ef-90a8-42e793956a59'::uuid, '4c25904c-625b-5011-8a9b-9f7a83a09d43'::uuid, 'Quel indicateur mesure la part des personnes qui ne peuvent s’offrir des éléments de la vie courante ?', 'mcq', '["Le taux de natalité","Le taux de privation matérielle et sociale","Le PIB","L’IMC"]'::jsonb, 1, 'Il complète la mesure monétaire de la pauvreté.', 12),
    ('74e914af-a562-57a9-ab91-05f31255f619'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Qu’est-ce qu’un déterminant de santé ?', 'mcq', '["Un médicament","Un facteur qui influence l’état de santé","Un professionnel de santé","Une maladie"]'::jsonb, 1, 'Il peut agir positivement ou négativement.', 1),
    ('dfe1ed8d-13f2-556c-ad61-a94590af55da'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Lequel est un facteur de protection ?', 'mcq', '["Le tabagisme","L’activité physique régulière","La sédentarité","La pollution de l’air"]'::jsonb, 1, 'Elle diminue le risque de maladies cardio-vasculaires, de diabète, de certains cancers.', 2),
    ('5f13a701-336e-5fea-a5a0-b1c9d615b3e4'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Combien de champs de déterminants distingue le modèle de Lalonde ?', 'mcq', '["2","3","4","6"]'::jsonb, 2, 'Biologie humaine, environnement, habitudes de vie et organisation des soins.', 3),
    ('268da9f4-d686-5756-997a-dc01af669db1'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Dans le modèle de Dahlgren et Whitehead, que trouve-t-on au centre ?', 'mcq', '["Le système de soins","L’âge, le sexe et les facteurs héréditaires","Le contexte économique général","Le logement"]'::jsonb, 1, 'Ce sont les déterminants non modifiables.', 4),
    ('9d117a5c-bc0a-5c12-9b49-1ab99cb78755'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Lequel est un déterminant social de santé ?', 'mcq', '["Le groupe sanguin","Le niveau de diplôme","La couleur des yeux","L’âge"]'::jsonb, 1, 'Le diplôme influence l’emploi, le revenu et les comportements de santé.', 5),
    ('8be0bca6-453d-577d-8792-0c5a97eb771a'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Que montre le rapport Lalonde de 1974 ?', 'mcq', '["Que les soins expliquent toute la santé","Que l’essentiel des dépenses va aux soins alors que d’autres champs pèsent davantage","Que la génétique ne compte pas","Que la santé est un droit"]'::jsonb, 1, 'Il a encouragé la prévention et l’action sur les modes de vie.', 6),
    ('8c669220-d65b-5cca-b6f3-4b6cb56ca871'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'La pollution de l’air est un déterminant environnemental de santé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les particules fines provoquent chaque année de nombreux décès prématurés.', 7),
    ('5a5715a4-6e6d-5903-bec0-344580faa8ba'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Dans quelle couche du modèle arc-en-ciel se trouve le soutien de la famille et des amis ?', 'mcq', '["Le mode de vie personnel","Les réseaux sociaux et communautaires","Le centre","Les conditions générales"]'::jsonb, 1, 'Le soutien social protège la santé, en particulier la santé mentale.', 8),
    ('37caccf3-cf5c-5ae5-94cb-b9ae2ce31e92'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Pourquoi dit-on que les déterminants interagissent ?', 'mcq', '["Parce qu’ils sont indépendants","Parce qu’ils se renforcent : faible revenu, logement, travail et comportements se combinent","Parce qu’un seul suffit à tout expliquer","Parce qu’ils changent chaque jour"]'::jsonb, 1, 'Agir sur un seul déterminant a donc un effet limité.', 9),
    ('ec40c8a7-9baf-590d-aace-51aedced8f04'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Un facteur de risque rend la maladie certaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en augmente seulement la probabilité.', 10),
    ('923dcb95-1cc8-54b0-8747-80809c11412c'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Lequel est un déterminant non modifiable ?', 'mcq', '["Le tabagisme","L’âge","Le logement","L’alimentation"]'::jsonb, 1, 'On ne peut agir ni sur l’âge, ni sur le sexe, ni sur l’hérédité.', 11),
    ('3434eda4-89c7-5a34-af0b-c4a9b8a68201'::uuid, 'b4a1a261-f657-596e-bb28-f31282b1c06f'::uuid, 'Dans quelle couche du modèle arc-en-ciel classer les conditions de travail ?', 'mcq', '["Le centre","Le mode de vie personnel","Les conditions de vie et de travail","Les réseaux sociaux"]'::jsonb, 2, 'Avec l’éducation, l’emploi, le logement et l’accès aux services.', 12),
    ('ebe1af30-29a0-5da3-9edc-c423b9a649ba'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Qu’est-ce qu’une alerte sanitaire ?', 'mcq', '["Un bilan annuel de santé","Un signal annonçant une menace et appelant une réaction rapide","Une campagne de publicité","Une loi de santé"]'::jsonb, 1, 'Elle est repérée par les systèmes de veille, comme Santé publique France.', 1),
    ('47fb68e6-26f3-5d63-bff6-6a30229ec2f9'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Lequel n’est pas un critère de reconnaissance d’un problème de santé publique ?', 'mcq', '["L’ampleur","La gravité","La couleur du logo de la campagne","La perception sociale"]'::jsonb, 2, 'Ampleur, gravité, coût, possibilité d’agir et perception sociale comptent.', 2),
    ('3ff4f2e8-dabf-5d46-ae71-f3a8b41b696f'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Quel rôle joue l’épidémiologie dans la reconnaissance d’un problème ?', 'mcq', '["Elle le rend invisible","Elle objective le problème en mesurant fréquence et facteurs de risque","Elle vote les lois","Elle soigne les malades"]'::jsonb, 1, 'Mais la mesure seule ne suffit pas : il faut des acteurs pour porter le problème.', 3),
    ('b99b52dc-e914-565e-9d78-fecd9bb4f798'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Combien de décès en excès la canicule d’août 2003 a-t-elle provoqués en France, environ ?', 'mcq', '["150","1 500","15 000","150 000"]'::jsonb, 2, 'Elle a conduit à créer le plan canicule.', 4),
    ('9fcad4e6-d31d-506d-82a7-87c921564f2e'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Quelle agence est née de l’affaire du Mediator ?', 'mcq', '["L’ANSM","La CAF","L’INSEE","France Travail"]'::jsonb, 0, 'L’Agence nationale de sécurité du médicament et des produits de santé a été créée par la loi de 2011.', 5),
    ('60038b0b-322e-577a-900a-0c2cb451708f'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Quelle affaire des années 1980 est à l’origine de la sécurité sanitaire moderne ?', 'mcq', '["La canicule","Le sang contaminé","Le Covid-19","La vache folle uniquement"]'::jsonb, 1, 'Des hémophiles et transfusés ont été contaminés par le VIH.', 6),
    ('62120996-e40d-519e-b51e-58c59e7d161e'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Un problème de santé bien mesuré est toujours reconnu immédiatement par la collectivité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut qu’il soit porté par des acteurs et mis à l’agenda politique.', 7),
    ('f5881db1-7165-5ad5-b54d-56d0052c04af'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Qui a joué un rôle de lanceuse d’alerte dans l’affaire du Mediator ?', 'mcq', '["Simone Veil","Irène Frachon","Marie Curie","Olympe de Gouges"]'::jsonb, 1, 'Cette pneumologue a documenté les atteintes des valves cardiaques.', 8),
    ('12c2a4a5-3eb3-5893-be74-6fad5d74b959'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Qu’est-ce qu’un risque ?', 'mcq', '["Un dommage certain","La probabilité qu’un danger provoque un dommage","Une maladie contagieuse","Un médicament"]'::jsonb, 1, 'Le danger est la source ; le risque, la probabilité qu’elle nuise.', 9),
    ('89d4fc2a-9b42-5093-8977-ca1a3d61f6e2'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Laquelle est une composante d’une crise sanitaire ?', 'mcq', '["L’absence de médias","L’incertitude scientifique et la pression médiatique","Une situation parfaitement maîtrisée","L’absence de décision"]'::jsonb, 1, 'S’y ajoutent l’urgence et la mise en cause des autorités.', 10),
    ('a914caba-1a26-547f-b022-813c49f55d29'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Quels acteurs peuvent faire émerger un problème de santé ?', 'mcq', '["Uniquement le gouvernement","Associations, médecins, chercheurs, médias, élus","Uniquement les médecins","Personne : il émerge seul"]'::jsonb, 1, 'Leur mobilisation met la question à l’agenda.', 11),
    ('4d9a9346-0356-5e36-b30a-64f63e98934a'::uuid, '29222c8d-6c21-512d-a785-3ce77a0cf79d'::uuid, 'Chaque crise sanitaire laisse souvent de nouvelles lois ou de nouvelles agences.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sang contaminé, canicule, Mediator : chaque crise a transformé le système.', 12),
    ('a02497bc-6e4c-5e71-bc4e-76a65b48c34e'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Comment définit-on la précarité selon Joseph Wresinski ?', 'mcq', '["L’absence d’une ou plusieurs sécurités permettant d’assumer ses responsabilités et de jouir de ses droits","Le fait de vivre sous le seuil de pauvreté","La rupture totale des liens sociaux","Le fait d’être au chômage"]'::jsonb, 0, 'Cumulée et durable, elle peut conduire à la grande pauvreté.', 1),
    ('67dc0443-e4a5-5251-ad06-44bbeffd4de2'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Qu’est-ce que l’exclusion ?', 'mcq', '["Un revenu faible","La rupture des liens sociaux et la mise à l’écart de la vie sociale","Un contrat de travail court","Un déménagement"]'::jsonb, 1, 'La précarité est une fragilité, la pauvreté un manque, l’exclusion une rupture.', 2),
    ('87bfaf98-228e-5a3b-929e-345855e33d87'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Pourquoi dit-on que l’exclusion est un processus ?', 'mcq', '["Parce qu’elle arrive d’un coup","Parce qu’elle résulte d’un enchaînement de ruptures qui s’alimentent","Parce qu’elle est décidée par un juge","Parce qu’elle ne dure jamais"]'::jsonb, 1, 'Perte d’emploi, séparation, perte du logement, isolement peuvent s’enchaîner.', 3),
    ('45b330a0-3b78-56ce-b3ee-310a0d02d2db'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Quelles sont les trois zones décrites par Robert Castel ?', 'mcq', '["Riche, moyenne, pauvre","Intégration, vulnérabilité, désaffiliation","Ville, banlieue, campagne","Enfance, âge adulte, vieillesse"]'::jsonb, 1, 'Elles combinent la situation d’emploi et la solidité des liens.', 4),
    ('16989452-31f6-5b0f-92a4-790714e809d4'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Quelle prestation a remplacé le RMI en 2009 ?', 'mcq', '["L’APA","Le RSA","La PCH","L’ASPA"]'::jsonb, 1, 'Le revenu de solidarité active.', 5),
    ('b2b95908-6326-57d4-8ad5-1815cfc29977'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'En quelle année le RMI a-t-il été créé ?', 'mcq', '["1945","1988","2009","2016"]'::jsonb, 1, 'Il faisait suite au rapport Wresinski sur la grande pauvreté.', 6),
    ('39e09876-390d-55a8-a195-4ea7c83cffd8'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Quelle loi de 2007 reconnaît un droit au logement pouvant être invoqué en justice ?', 'mcq', '["La loi DALO","La loi Veil","La loi Kouchner","La loi Evin"]'::jsonb, 0, 'Le droit au logement opposable, obtenu après la mobilisation des associations.', 7),
    ('439f2185-576e-583f-968d-dc97117ac6d4'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Un problème social existe dès qu’une situation difficile existe, même si personne ne la dénonce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut une mobilisation et une reconnaissance par la collectivité.', 8),
    ('b9f0a9a3-ae38-5ca4-911e-486d3c0b9dfb'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Quel sociologue parle de « disqualification sociale » ?', 'mcq', '["Émile Durkheim","Serge Paugam","Pierre Laroque","Marc Lalonde"]'::jsonb, 1, 'Il décrit un parcours de la fragilité à la dépendance puis à la rupture.', 9),
    ('122ed430-7b48-56ce-80d0-fe278ffd22ca'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Quelle association a été fondée par Coluche en 1985 ?', 'mcq', '["Emmaüs","Les Restos du cœur","ATD Quart Monde","La Croix-Rouge"]'::jsonb, 1, 'Elle a contribué à rendre visible la pauvreté alimentaire.', 10),
    ('4ed8f4eb-1d6c-5492-b906-d6da33338bc7'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'En quelle année la loi d’orientation relative à la lutte contre les exclusions a-t-elle été votée ?', 'mcq', '["1975","1988","1998","2016"]'::jsonb, 2, 'Elle affirme l’accès de tous aux droits fondamentaux.', 11),
    ('4b8b2bc5-801a-51aa-84ab-9a79ed81ed72'::uuid, '41838cd7-31af-585a-b8a5-b4db1b9552d3'::uuid, 'Les inégalités territoriales peuvent fragiliser la cohésion sociale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Quartiers relégués et zones rurales isolées cumulent souvent les difficultés.', 12),
    ('78e0dbe6-02cf-531f-bebb-fb0feacae6b9'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Qu’est-ce qu’un risque social ?', 'mcq', '["Un danger pour l’environnement","Un événement qui peut réduire les revenus ou augmenter les dépenses","Une maladie contagieuse uniquement","Un risque financier en Bourse"]'::jsonb, 1, 'Maladie, vieillesse, chômage, charges de famille en sont des exemples.', 1),
    ('cc5e8fd0-781d-5997-987a-c077f6ce1a88'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Quel est le principe du modèle bismarckien ?', 'mcq', '["Une protection financée par l’impôt pour tous les citoyens","Une protection liée au travail, financée par des cotisations","Une protection uniquement privée","L’absence de protection"]'::jsonb, 1, 'Né en Allemagne dans les années 1880, c’est une logique d’assurance.', 2),
    ('3f781753-ed6d-55e6-a7a0-9c4658f92e2d'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Que désignent les « trois U » de Beveridge ?', 'mcq', '["Utilité, unité, urgence","Universalité, uniformité, unicité","Union, usage, usure","Urbanisme, université, usine"]'::jsonb, 1, 'Tous couverts, prestations identiques, une seule organisation.', 3),
    ('fc8ddca8-7dcc-5dd4-96da-4ab61e8b8dd0'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'En quelle année la Sécurité sociale a-t-elle été créée en France ?', 'mcq', '["1898","1945","1968","1988"]'::jsonb, 1, 'Par les ordonnances des 4 et 19 octobre 1945.', 4),
    ('67c3c30a-b2b1-5a29-8dce-c03ee18d0356'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Quelle est la cinquième branche de la Sécurité sociale, créée en 2021 ?', 'mcq', '["La branche chômage","La branche autonomie","La branche logement","La branche éducation"]'::jsonb, 1, 'Elle couvre la perte d’autonomie des personnes âgées et handicapées.', 5),
    ('0f15425a-c1e7-5fcd-abeb-6acb9c355398'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Le système français de protection sociale est :', 'mcq', '["Purement bismarckien","Purement beveridgien","Mixte","Entièrement privé"]'::jsonb, 2, 'D’origine assurantielle, il a intégré universalité et financement fiscal.', 6),
    ('a10bab39-f5f4-56f5-b3d3-fbd00dba2808'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Qu’est-ce que le non-recours ?', 'mcq', '["Le refus d’une aide par l’administration","Le fait de ne pas demander une aide à laquelle on a droit","Une fraude aux prestations","Un recours devant le juge"]'::jsonb, 1, 'Méconnaissance, complexité et crainte de la stigmatisation l’expliquent.', 7),
    ('a9c69480-d27d-5a4a-8682-a3aa454912f3'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Quel texte garantit à tous la protection de la santé et la sécurité matérielle ?', 'mcq', '["Le Code civil de 1804","Le Préambule de la Constitution de 1946","La loi de 1898","Le traité de Rome"]'::jsonb, 1, 'Il fait partie du bloc de constitutionnalité.', 8),
    ('c1a82eab-decc-5987-b46f-85bb967f88cc'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Quelle loi de 1898 fonde la protection contre les accidents du travail ?', 'mcq', '["Une loi qui rend l’employeur responsable des accidents du travail","La loi sur les allocations familiales","La loi sur la retraite à 60 ans","La loi sur le RSA"]'::jsonb, 0, 'Elle instaure une responsabilité sans faute de l’employeur.', 9),
    ('5eee7616-d265-5d8a-896b-0579a09d6dbd'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'La protection universelle maladie (PUMa) date de 2016.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle garantit la prise en charge des frais de santé à toute personne qui travaille ou réside de façon stable et régulière en France.', 10),
    ('9a204f72-a619-5128-b055-282e6e5b3dd1'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Quel prélèvement créé en 1991 finance la protection sociale sur l’ensemble des revenus ?', 'mcq', '["La TVA","La CSG","L’impôt sur les sociétés","La taxe foncière"]'::jsonb, 1, 'La contribution sociale généralisée a fiscalisé une partie du financement.', 11),
    ('3e475763-e9fb-597d-b704-652eb8945dec'::uuid, '53821c3c-737c-5481-a3d3-727fb6a91b75'::uuid, 'Avant la protection collective, on faisait face aux risques par :', 'mcq', '["La prévoyance individuelle, la famille et la charité","La Sécurité sociale","Le RSA","La PUMa"]'::jsonb, 0, 'La protection collective organise la solidarité à l’échelle de la société.', 12),
    ('96efbc3f-d1e6-58c4-89de-cf5f86dbe977'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Quelle technique de protection sociale repose sur des cotisations ouvrant des droits ?', 'mcq', '["L’assistance","L’assurance sociale","La charité","L’épargne individuelle"]'::jsonb, 1, 'C’est une logique contributive : on reçoit parce qu’on a cotisé.', 1),
    ('382645d0-a412-5cff-8110-3f7833f7ca27'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Le RSA relève de quelle logique ?', 'mcq', '["L’assurance","L’assistance","La prévoyance privée","L’épargne salariale"]'::jsonb, 1, 'Il est versé sous condition de ressources, sans cotisation préalable.', 2),
    ('539d010e-f7b7-59a8-9a58-f170035beec1'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Comment l’assistance est-elle principalement financée ?', 'mcq', '["Par les cotisations salariales","Par l’impôt","Par les mutuelles","Par les dons uniquement"]'::jsonb, 1, 'Elle exprime la solidarité nationale envers les plus démunis.', 3),
    ('b886491a-f16c-5f26-a63f-452a21eee801'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Laquelle est une prestation en nature ?', 'mcq', '["Une pension de retraite","Le remboursement de soins","L’allocation chômage","Les indemnités journalières"]'::jsonb, 1, 'Elle prend en charge un bien ou un service.', 4),
    ('02c35d50-0a95-55e8-9a85-20ce1bd3bdd5'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Que garantit la protection universelle maladie ?', 'mcq', '["Une retraite à tous","La prise en charge des frais de santé à toute personne qui travaille ou réside de façon stable et régulière en France","Un revenu minimum","Une mutuelle gratuite pour tous"]'::jsonb, 1, 'Elle a supprimé la condition d’activité professionnelle.', 5),
    ('db7dc873-72b9-5007-be85-c0b4445baf56'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Qu’est-ce que la complémentaire santé solidaire (C2S) ?', 'mcq', '["Une mutuelle privée obligatoire","Une prise en charge de la part non remboursée par l’assurance maladie pour les personnes aux faibles ressources","Une aide au logement","Une allocation familiale"]'::jsonb, 1, 'Gratuite ou à participation limitée selon les revenus.', 6),
    ('4b90bf44-3362-54e2-91c4-b5e7bc445b4a'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Les allocations familiales sont versées sans condition d’activité professionnelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles relèvent d’une logique universelle, même si leur montant est modulé selon les revenus depuis 2015.', 7),
    ('6b2971fe-2f5e-5a57-adf2-6eed193f71ce'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Qu’est-ce que la fiscalisation du financement de la protection sociale ?', 'mcq', '["La suppression des impôts","La part croissante des impôts (dont la CSG) au détriment des cotisations","La hausse des cotisations patronales","Le financement par les mutuelles"]'::jsonb, 1, 'Elle accompagne l’universalisation des droits.', 8),
    ('e87ed25c-c945-54ae-80ba-4eb5ad46ceaa'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Quel est le principe de l’assurance sociale ?', 'mcq', '["La mutualisation du risque entre cotisants","L’aide aux plus démunis sans contrepartie","L’épargne personnelle","La charité religieuse"]'::jsonb, 0, 'Les cotisations de tous financent les prestations de ceux qui subissent le risque.', 9),
    ('05cec58a-ff1c-57ad-83b4-d3aadde563cc'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Quelle part de la richesse nationale les dépenses de protection sociale représentent-elles environ ?', 'mcq', '["5 %","Un tiers","Les trois quarts","100 %"]'::jsonb, 1, 'Santé et vieillesse en sont les deux premiers postes.', 10),
    ('df38b2db-0b99-57aa-903f-1f8438e847a6'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Une prestation d’assistance est versée sans condition de ressources.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’assistance est justement soumise à des conditions de ressources.', 11),
    ('8067761e-c942-5081-b4af-2504bc4bff17'::uuid, '09dd4f18-b65b-57c2-beed-e91fd0bee5a3'::uuid, 'Quel est l’exemple d’une prestation d’assurance proportionnelle aux revenus antérieurs ?', 'mcq', '["Le RSA","La pension de retraite de base","L’ASPA","L’aide sociale à l’hébergement"]'::jsonb, 1, 'Son montant dépend des salaires et des durées de cotisation.', 12),
    ('38cde80b-2f86-5e0d-b040-d3c406feb5ff'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quelle caisse locale gère l’assurance maladie ?', 'mcq', '["La CAF","La CPAM","La Carsat","L’Urssaf"]'::jsonb, 1, 'La caisse primaire d’assurance maladie rembourse les soins et verse les indemnités journalières.', 1),
    ('9daf3f56-895b-554a-8b65-47aa441a96ca'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quel organisme verse les prestations familiales ?', 'mcq', '["La CPAM","La CAF","France Travail","La MSA uniquement"]'::jsonb, 1, 'Les caisses d’allocations familiales dépendent de la CNAF.', 2),
    ('87c5d782-08f1-53ae-b49f-c24e599d5791'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quel organisme collecte les cotisations sociales ?', 'mcq', '["L’Urssaf","La CAF","La CNSA","L’INSEE"]'::jsonb, 0, 'La branche recouvrement est pilotée par l’Urssaf Caisse nationale.', 3),
    ('723d3489-07e2-59ef-9f77-c5ca2ce94a0b'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quelle caisse nationale gère la branche autonomie ?', 'mcq', '["La CNAV","La CNSA","La CNAF","L’Unédic"]'::jsonb, 1, 'La Caisse nationale de solidarité pour l’autonomie gère la cinquième branche depuis 2021.', 4),
    ('93ee8712-7eb8-50d2-9f55-a89df2f74946'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quel organisme verse les allocations chômage depuis le 1er janvier 2024 ?', 'mcq', '["Pôle emploi","France Travail","La CAF","La CPAM"]'::jsonb, 1, 'Pôle emploi est devenu France Travail ; l’Unédic gère l’assurance chômage.', 5),
    ('3e30b762-8438-5f9b-b5aa-f5f0a2623edf'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Qu’est-ce que le ticket modérateur ?', 'mcq', '["Le prix d’une mutuelle","La part des dépenses de santé qui reste après le remboursement de l’assurance maladie","Une amende pour retard","Le tarif d’une consultation"]'::jsonb, 1, 'La complémentaire santé le prend en charge en tout ou partie.', 6),
    ('c92b298b-6b39-5a5c-a2a4-d693094cba6e'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Que signifie le caractère subsidiaire de l’aide sociale ?', 'mcq', '["Elle intervient en premier","Elle n’intervient qu’en dernier recours","Elle est facultative pour la collectivité","Elle est financée par les mutuelles"]'::jsonb, 1, 'On mobilise d’abord les revenus, la famille et les autres droits.', 7),
    ('df381aa3-4679-50d1-85b0-49ff243dea62'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quelle collectivité est chef de file de l’aide sociale ?', 'mcq', '["La commune","Le département","La région","L’Europe"]'::jsonb, 1, 'Elle gère le RSA, l’ASE, l’APA et la PCH.', 8),
    ('96f04340-cc2b-501d-8144-b02ffea09643'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Pour une consultation à 30 € remboursée à 70 %, combien rembourse l’assurance maladie avant déduction de la participation forfaitaire ?', 'mcq', '["9 €","21 €","30 €","28 €"]'::jsonb, 1, '70 % de 30 € = 21 € ; la participation forfaitaire de 2 € en est ensuite déduite.', 9),
    ('ca265964-eddb-564c-a286-18b2a34ece61'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'La participation forfaitaire peut être remboursée par la complémentaire santé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle reste à la charge du patient.', 10),
    ('78370f51-1926-5653-8876-680e5938770d'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quel exemple illustre une couverture supplémentaire ?', 'mcq', '["Le remboursement du ticket modérateur","La prise en charge de dépassements d’honoraires ou d’une chambre particulière","Le RSA","Les allocations familiales"]'::jsonb, 1, 'Elle va au-delà du tarif de base.', 11),
    ('dcdb6b8c-16f6-59bf-8b7d-21cef8bfe51d'::uuid, '8609ed1f-e966-5a2e-ade5-7128d8664a9d'::uuid, 'Quels organismes proposent des complémentaires santé ?', 'mcq', '["Les CAF","Les mutuelles, institutions de prévoyance et sociétés d’assurance","Les Urssaf","Les mairies uniquement"]'::jsonb, 1, 'Ce sont les trois familles d’organismes complémentaires.', 12),
    ('cd599357-13dd-56ee-ad6b-fb02e70d0485'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'La vaccination relève de quel niveau de prévention ?', 'mcq', '["Primaire","Secondaire","Tertiaire","Aucun"]'::jsonb, 0, 'Elle empêche l’apparition de la maladie et réduit l’incidence.', 1),
    ('c06cf229-c2e7-58e2-bceb-c3480558efce'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Le dépistage organisé du cancer du sein relève de la prévention :', 'mcq', '["Primaire","Secondaire","Tertiaire","Quaternaire"]'::jsonb, 1, 'Il détecte la maladie tôt pour limiter son évolution.', 2),
    ('fc706834-ef07-519b-b89e-cce8391db985'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'La rééducation après un AVC relève de la prévention :', 'mcq', '["Primaire","Secondaire","Tertiaire","Universelle"]'::jsonb, 2, 'Elle limite les séquelles et les complications.', 3),
    ('162a0372-9244-5238-998d-4b6ef94df0e4'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Quel est l’objectif de la prévention primaire ?', 'mcq', '["Réduire la prévalence","Réduire l’incidence","Réduire les séquelles","Augmenter les soins"]'::jsonb, 1, 'Elle agit avant l’apparition de la maladie.', 4),
    ('64a4ec76-cd9d-5d7a-a3d2-6c167809b8a1'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Combien d’axes la charte d’Ottawa propose-t-elle ?', 'mcq', '["3","4","5","10"]'::jsonb, 2, 'Politique publique saine, milieux favorables, action communautaire, aptitudes individuelles, réorientation des services.', 5),
    ('01fc189a-6d78-5909-acee-3d500affe580'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Qu’est-ce que l’éducation pour la santé ?', 'mcq', '["Former des médecins","Aider chacun à acquérir connaissances et compétences pour des choix favorables à sa santé","Soigner les maladies","Construire des hôpitaux"]'::jsonb, 1, 'Elle vise l’autonomie de la personne face à sa santé.', 6),
    ('53865ca6-3396-5974-9bc3-a8ea5ab2f106'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Quelle est la différence entre prévention et promotion de la santé ?', 'mcq', '["Aucune","La prévention vise une maladie, la promotion vise la santé globale et ses déterminants","La promotion ne concerne que l’hôpital","La prévention est toujours individuelle"]'::jsonb, 1, 'La promotion agit sur l’environnement et les conditions de vie.', 7),
    ('d19ea494-7e6e-54b1-b257-c47fa55e6451'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Créer des espaces verts et des pistes cyclables relève de la promotion de la santé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’axe « créer des milieux favorables » de la charte d’Ottawa.', 8),
    ('05a279ca-fd77-55d7-a20a-3d7b5237021d'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Depuis quelle année le médecin traitant est-il le pivot du parcours de soins ?', 'mcq', '["1945","1998","2004","2020"]'::jsonb, 2, 'La réforme de l’assurance maladie de 2004 a instauré le parcours de soins coordonnés.', 9),
    ('3e3914ec-2419-5a0b-831a-db033cdba87a'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'La veille sanitaire a pour rôle de :', 'mcq', '["Soigner les patients","Surveiller et détecter les menaces pour la santé","Rembourser les soins","Former les infirmiers"]'::jsonb, 1, 'Santé publique France en est l’acteur principal.', 10),
    ('78e440b2-aecb-5022-9e3f-8dcd689d909a'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'L’éducation thérapeutique d’un patient diabétique relève de la prévention tertiaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle vise à éviter les complications d’une maladie déjà installée.', 11),
    ('ff006ee5-0bee-50fd-b5e2-4885ef149237'::uuid, '614416c0-0fdc-5a61-9252-0c38651d78aa'::uuid, 'Qu’est-ce que la restauration de la santé ?', 'mcq', '["La rénovation des hôpitaux","Les soins, la réadaptation et la réinsertion","La vaccination","La collecte des cotisations"]'::jsonb, 1, 'C’est le mode curatif de l’action en santé.', 12),
    ('4b702607-91c4-59a3-ad90-ee9922ad042e'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Quels organismes pilotent la santé au niveau régional ?', 'mcq', '["Les CAF","Les agences régionales de santé (ARS)","Les Urssaf","Les mairies"]'::jsonb, 1, 'Créées en 2010, elles organisent l’offre de soins et la prévention dans chaque région.', 1),
    ('a1002224-93a0-597e-89ae-ad837868b416'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Quelle loi de 2002 rassemble les droits des malades ?', 'mcq', '["La loi Evin","La loi du 4 mars 2002, dite loi Kouchner","La loi Veil","La loi DALO"]'::jsonb, 1, 'Elle porte sur les droits des malades et la qualité du système de santé.', 2),
    ('61fde8e7-5f80-5112-bb60-6fa15fc39e27'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Que signifie un consentement « libre et éclairé » ?', 'mcq', '["Donné sous la pression du médecin","Donné sans contrainte, après une information claire","Donné par écrit uniquement","Donné par la famille à la place du patient"]'::jsonb, 1, 'Il peut être retiré à tout moment.', 3),
    ('228c6606-da21-5ee0-b6be-f5cb1baf75ff'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Quel est le rôle de la personne de confiance ?', 'mcq', '["Payer les soins","Accompagner le patient et être consultée s’il ne peut plus exprimer sa volonté","Remplacer le médecin","Signer les ordonnances"]'::jsonb, 1, 'Le patient la désigne librement.', 4),
    ('0da16097-cc83-55c7-b47b-9168eae8394d'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Un patient peut accéder directement à son dossier médical.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un droit reconnu par la loi du 4 mars 2002.', 5),
    ('b08c433c-c321-59ee-9a8a-483c0ea7cada'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Quelle loi de 2016 rend les directives anticipées sur la fin de vie contraignantes pour le médecin ?', 'mcq', '["La loi Claeys-Leonetti","La loi Kouchner","La loi HPST","La loi Veil"]'::jsonb, 0, 'Les directives anticipées s’imposent au médecin, sauf exceptions prévues par la loi.', 6),
    ('8b6826fc-3333-5958-b7ff-dd66ec076b90'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Qu’est-ce que la démocratie sanitaire ?', 'mcq', '["L’élection des médecins","La participation des usagers aux instances et décisions du système de santé","La gratuité totale des soins","Le vote des lois de santé par référendum"]'::jsonb, 1, 'Des représentants des usagers siègent dans les établissements et instances.', 7),
    ('f91afdf9-a860-58ee-b65e-c41edbea9a6e'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Quelle agence nationale évalue les médicaments, les actes et la qualité des soins ?', 'mcq', '["La Haute Autorité de santé","La CNAF","France Travail","L’INSEE"]'::jsonb, 0, 'La HAS émet des recommandations et certifie les établissements.', 8),
    ('813a0548-60d8-5997-a39a-f14cf53ead7a'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Lequel est un acteur de la société civile en santé ?', 'mcq', '["Une association de patients","Le ministère de la santé","L’ARS","L’Assurance maladie"]'::jsonb, 0, 'Les associations informent, accompagnent et représentent les usagers.', 9),
    ('41f98b0f-5ed2-53d5-b2a8-821857b27cdf'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Qu’est-ce qu’un patient expert ?', 'mcq', '["Un médecin spécialiste","Un patient qui, fort de son expérience de la maladie, aide d’autres patients","Un juge des tutelles","Un pharmacien"]'::jsonb, 1, 'Il participe par exemple à l’éducation thérapeutique.', 10),
    ('366f9b37-cc39-5963-8feb-0b32bd4a474c'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Le secret médical peut être levé librement par le médecin pour informer l’employeur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le secret professionnel protège la vie privée du patient ; ses exceptions sont strictement prévues par la loi.', 11),
    ('67ba15a3-ca84-500d-8b6d-47681c2fc453'::uuid, '04735a5b-5fe0-55b7-91fe-864664d5d53c'::uuid, 'Quelle collectivité gère la protection maternelle et infantile (PMI) ?', 'mcq', '["La commune","Le département","La région","L’État directement"]'::jsonb, 1, 'La PMI suit la santé des femmes enceintes et des jeunes enfants.', 12),
    ('7b6e065a-ffe3-58be-b0d8-3731eee681a8'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Qu’est-ce que le diagnostic social ?', 'mcq', '["Un examen médical","Un état des lieux des ressources, difficultés et besoins d’une personne ou d’un territoire","Une décision de justice","Une prestation en espèces"]'::jsonb, 1, 'Il précède toute intervention sociale.', 1),
    ('da62295f-6207-560d-96cf-cc963910e38e'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Quelle collectivité est chef de file de l’action sociale ?', 'mcq', '["La région","Le département","La commune","L’Union européenne"]'::jsonb, 1, 'Elle gère le RSA, l’ASE, l’aide aux personnes âgées et handicapées.', 2),
    ('4f8d1b94-9970-5200-8e0c-e2e49d4e3e9f'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Qu’est-ce que le développement social local ?', 'mcq', '["Une aide individuelle d’urgence","Une démarche qui mobilise les ressources d’un territoire et fait des habitants des acteurs","Une subvention européenne","Une construction de logements sociaux uniquement"]'::jsonb, 1, 'L’intervention vise le territoire dans son ensemble.', 3),
    ('6b8677ab-4aa1-5bdd-b347-fb1288aac80a'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Dans quelles communes le CCAS est-il obligatoire ?', 'mcq', '["Toutes les communes","Les communes de 1 500 habitants et plus","Les villes de plus de 100 000 habitants","Aucune"]'::jsonb, 1, 'En dessous, la commune peut exercer ces missions directement ou via un centre intercommunal.', 4),
    ('754cfb09-600d-5b0f-849b-4521bee4bb77'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Quelle loi de 2002 place l’usager au centre de l’action sociale et médico-sociale ?', 'mcq', '["La loi du 4 mars 2002","La loi du 2 janvier 2002","La loi DALO","La loi de 1975"]'::jsonb, 1, 'Elle impose livret d’accueil, contrat de séjour, conseil de la vie sociale…', 5),
    ('793db7df-a178-50b8-9386-380a5ade1255'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'À quoi sert le conseil de la vie sociale ?', 'mcq', '["À juger les usagers","À faire participer les usagers au fonctionnement de l’établissement","À recruter le personnel","À fixer les prix"]'::jsonb, 1, 'C’est un outil de participation prévu par la loi de 2002.', 6),
    ('caa1e04d-915a-56a6-becc-07a5d854bb7f'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Un assistant de service social qui aide une famille à gérer son budget pratique :', 'mcq', '["Un accompagnement social individuel","Un développement social local","Une action de veille sanitaire","Une prévention tertiaire"]'::jsonb, 0, 'L’intervention porte sur une personne ou une famille.', 7),
    ('d66b60ef-a8b8-5a7f-88e2-5460f93a2c8e'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'L’insertion vise à permettre à une personne de retrouver sa place dans la société.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Par l’emploi, le logement, la formation, les liens sociaux.', 8),
    ('a0be42cb-71fb-5c9f-92bd-6cedf84c2440'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Lequel est un minimum social ?', 'mcq', '["La pension de retraite de base","L’allocation aux adultes handicapés (AAH)","Le salaire minimum","Les indemnités journalières"]'::jsonb, 1, 'Comme le RSA et l’ASPA, elle garantit un revenu minimum.', 9),
    ('3167e9b1-d9eb-5b34-b3c0-c44f5a003ec9'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Quel outil formalise les objectifs définis avec la personne accompagnée ?', 'mcq', '["Le projet personnalisé","Le bulletin de salaire","La carte Vitale","Le permis de conduire"]'::jsonb, 0, 'Il est construit avec la personne et révisé régulièrement.', 10),
    ('432dad0a-2733-5c21-8608-8fcadc5c17bf'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Les prestations sociales n’ont aucun effet sur le taux de pauvreté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles le réduisent fortement : sans elles, il serait nettement plus élevé.', 11),
    ('cebb61cd-44b7-55df-8430-2fba6029c8b7'::uuid, 'f9cfd476-4741-5af5-82ab-7a7a4a97be4b'::uuid, 'Quel professionnel du social est spécialiste du budget et de la vie quotidienne des familles ?', 'mcq', '["Le conseiller en économie sociale et familiale","Le kinésithérapeute","Le pharmacien","Le notaire"]'::jsonb, 0, 'Il accompagne sur le budget, le logement, l’alimentation.', 12),
    ('8dcead19-f077-54ad-951a-3d84a774afd4'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Quel opérateur de recherche élargit les résultats ?', 'mcq', '["ET","OU","SAUF","Les guillemets"]'::jsonb, 1, 'OU cherche l’un ou l’autre des mots : plus de résultats.', 1),
    ('908c1ecf-e18e-52c2-8bf0-8ad75f7bbff8'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Quel opérateur rend une recherche plus précise en exigeant les deux mots ?', 'mcq', '["ET","OU","SAUF","Aucun"]'::jsonb, 0, 'Les résultats doivent contenir les deux termes.', 2),
    ('d19ebbe7-8ede-5a81-9f4e-b6de945c5a34'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Quel site publie les textes officiels (lois, décrets) ?', 'mcq', '["Légifrance","Wikipédia","Un blog de santé","Un forum"]'::jsonb, 0, 'C’est le service public de diffusion du droit.', 3),
    ('0fb996d0-e6f4-5a90-b3b9-13dd2c79c84b'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Qu’est-ce qu’une source primaire ?', 'mcq', '["Un résumé d’article","Un document original, comme une enquête ou une loi","Un avis sur un forum","Une publicité"]'::jsonb, 1, 'Une source secondaire en fait la présentation ou l’analyse.', 4),
    ('af39fc64-f0ae-5bfb-8a85-d9f3c6c8d9e9'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Lequel est un critère de fiabilité d’une source ?', 'mcq', '["Sa mise en page colorée","L’identification de l’auteur et la présence de références","Son nombre de partages","Sa longueur"]'::jsonb, 1, 'Auteur, producteur, date, objectivité et références comptent.', 5),
    ('932ceec2-e477-5bef-bb6b-7ba4bc919fd7'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Que signifie QQOQCP ?', 'mcq', '["Qui, quoi, où, quand, comment, pourquoi","Quantité, qualité, origine, quantité, coût, prix","Questionnaire, quota, observation, question, corpus, projet","Aucun sens"]'::jsonb, 0, 'Ces questions aident à délimiter un sujet.', 6),
    ('eac0281a-3ace-50b8-9e0a-e519380ae84a'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Pour une source en ligne, il faut indiquer la date de consultation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le contenu d’une page peut changer.', 7),
    ('b1265bd8-8e4a-5ca1-965c-4a4cb0e24cda'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Quel producteur publie les statistiques sur la santé et la protection sociale pour le ministère ?', 'mcq', '["La DREES","La SNCF","Météo-France","L’Urssaf"]'::jsonb, 0, 'La direction de la recherche, des études, de l’évaluation et des statistiques.', 8),
    ('46b49d85-c1c4-506c-bf76-8e8abd88ac6e'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Qu’est-ce qu’un corpus documentaire ?', 'mcq', '["Un seul livre","L’ensemble des documents retenus pour une étude","Un questionnaire","Un tableau de chiffres"]'::jsonb, 1, 'On le structure par thèmes ou sous-questions.', 9),
    ('42f85203-db26-5b02-8733-9d86cbcd246b'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Un chiffre trouvé sur un réseau social sans source peut être utilisé tel quel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans source vérifiable, ce n’est qu’une affirmation.', 10),
    ('9e7f65df-ee46-53bd-b765-ea16a7415091'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Pourquoi faire une recherche documentaire avant une étude ?', 'mcq', '["Pour recopier une étude existante","Pour éviter de refaire l’existant, comparer et formuler des hypothèses","Pour allonger le rapport","Ce n’est pas utile"]'::jsonb, 1, 'C’est un préalable à toute étude.', 11),
    ('4731bf4f-76a5-5920-b132-8e214df81e56'::uuid, 'df6b9c04-86ac-545f-b0a3-e5091032359e'::uuid, 'Quel critère interroge un document qui cherche à vendre un produit ?', 'mcq', '["La date","L’objectivité","La longueur","La police de caractères"]'::jsonb, 1, 'Un document commercial cherche à convaincre plutôt qu’à informer.', 12),
    ('59813425-9bb5-5213-8601-e5d42ad44310'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Quel est l’objectif d’une méthode quantitative ?', 'mcq', '["Comprendre le vécu des personnes","Mesurer, compter et comparer","Raconter une histoire","Observer un seul individu"]'::jsonb, 1, 'Elle produit des chiffres, des pourcentages, des graphiques.', 1),
    ('f90dd62a-f843-5572-8dae-9df7cbf5d574'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Quel outil est typique d’une méthode qualitative ?', 'mcq', '["Le questionnaire à questions fermées","L’entretien semi-directif","Le tableau statistique de l’INSEE","Le recensement"]'::jsonb, 1, 'Une grille liste les thèmes, mais la personne s’exprime librement.', 2),
    ('b35e99d1-434d-58f7-9065-f75bb2edac1e'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Qu’est-ce qu’une hypothèse dans une étude ?', 'mcq', '["Une conclusion certaine","Une réponse provisoire à vérifier","Un outil de recueil","Une source documentaire"]'::jsonb, 1, 'L’étude la confirme ou l’infirme.', 3),
    ('900d915e-ca39-5c58-b798-d56475aa7cfa'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Qu’est-ce qu’un échantillon représentatif ?', 'mcq', '["Un groupe choisi au hasard sans règle","Un groupe qui reproduit les caractéristiques de la population étudiée","Tous les habitants d’un pays","Les amis de l’enquêteur"]'::jsonb, 1, 'Il permet de généraliser les résultats.', 4),
    ('0bf3d30a-8446-508b-a17e-1269b3d25e2c'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Quel est le principe de la méthode des quotas ?', 'mcq', '["Tirer les personnes au sort","Reproduire dans l’échantillon la structure de la population (âge, sexe…)","Interroger uniquement des volontaires","Interroger une seule personne"]'::jsonb, 1, 'C’est la méthode la plus utilisée par les instituts de sondage.', 5),
    ('f24837ed-c7e1-5a47-b649-085db971577e'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Pourquoi teste-t-on un questionnaire avant de le diffuser ?', 'mcq', '["Pour gagner du temps","Pour vérifier que les questions sont comprises et pertinentes","Pour connaître les réponses à l’avance","Ce n’est pas utile"]'::jsonb, 1, 'Une question mal comprise fausse tous les résultats.', 6),
    ('75a247ce-a0c7-5968-b65d-044955e8095e'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Quel organisme contrôle le respect de la protection des données personnelles en France ?', 'mcq', '["La CNIL","La CAF","L’ARS","La HAS"]'::jsonb, 0, 'Elle veille à l’application du RGPD.', 7),
    ('2aa47138-e629-5dd9-9441-d7cf62a97b1d'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Les données de santé sont des données sensibles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles bénéficient d’une protection renforcée.', 8),
    ('9ad75e87-72b5-52f5-be92-882d08d841f9'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Quel graphique convient pour représenter une évolution dans le temps ?', 'mcq', '["Un diagramme en secteurs","Une courbe","Un tableau de noms","Une carte mentale"]'::jsonb, 1, 'Les secteurs montrent une répartition, les barres des comparaisons.', 9),
    ('14e45011-e536-5bb2-950d-307d05553470'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Pourquoi combine-t-on souvent méthodes quantitatives et qualitatives ?', 'mcq', '["Pour doubler le coût","Pour mesurer l’ampleur d’un phénomène et en comprendre les raisons","Parce que la loi l’impose","Pour éviter l’analyse"]'::jsonb, 1, 'Les deux approches sont complémentaires.', 10),
    ('b273fc7d-31e0-5794-b639-c91929cc8cd5'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Une étude peut publier le nom des personnes interrogées sans leur accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Anonymat, confidentialité et consentement sont des exigences éthiques.', 11),
    ('30ec9bac-5d5c-5d71-af02-daa0f25f87f4'::uuid, 'f9b66591-f2e1-5fa2-b260-fb9bb02d8d84'::uuid, 'Quelle est la première étape d’une démarche d’étude ?', 'mcq', '["Le traitement des données","L’analyse de la commande ou du besoin","La rédaction du rapport","La diffusion"]'::jsonb, 1, 'Il faut savoir qui demande l’étude, pourquoi et dans quel contexte.', 12),
    ('3318142c-9ac0-58b2-a5ed-ea8ea11c098f'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Comment l’épreuve écrite de STSS de terminale est-elle organisée ?', 'mcq', '["Un oral de 20 minutes","Une question de connaissances (6 points) et une analyse de documents (14 points), en 3 heures","Un QCM de 1 heure","Un dossier à rendre en première"]'::jsonb, 1, 'Elle porte sur les programmes de première et de terminale.', 1),
    ('ac20c05e-ab77-595d-bd26-92dc683c7bdb'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Une valeur passe de 200 à 250. Quel est le taux d’évolution ?', 'mcq', '["+ 50 %","+ 25 %","+ 20 %","+ 125 %"]'::jsonb, 1, '(250 − 200) / 200 × 100 = 25 %.', 2),
    ('ba02a3a4-363f-5ad2-9915-69afc922ab34'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Un taux passe de 12 % à 15 %. Comment qualifier l’écart ?', 'mcq', '["+ 3 %","+ 3 points","+ 15 %","+ 25 points"]'::jsonb, 1, 'L’écart entre deux pourcentages s’exprime en points ; le taux d’évolution serait + 25 %.', 3),
    ('821590ad-54fd-596d-9197-67be79ba3b8f'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Quelle est la première chose à identifier dans un document statistique ?', 'mcq', '["La couleur du graphique","Le titre, la source, la date, le champ et l’unité","Le nombre de pages","Le nom du professeur"]'::jsonb, 1, 'Sans eux, on ne peut pas lire correctement les données.', 4),
    ('eeb3608a-8095-5162-b5d3-6d2151acc07f'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, '30 personnes sur 120 déclarent renoncer aux soins. Quelle part cela représente-t-il ?', 'mcq', '["4 %","25 %","30 %","40 %"]'::jsonb, 1, '30 / 120 × 100 = 25 %.', 5),
    ('82328eec-602b-59e2-aeda-2d94c1ebb365'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Paraphraser un document suffit à l’analyser.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut expliquer ce qu’il montre et le relier au cours.', 6),
    ('69fc8d83-fdab-5dd9-804e-6cddb2bda016'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Quelle structure de paragraphe est attendue dans une argumentation ?', 'mcq', '["Idée, document cité, explication","Chiffre seul","Liste de mots-clés","Citation sans commentaire"]'::jsonb, 0, 'Chaque paragraphe développe une idée appuyée et expliquée.', 7),
    ('ffaae608-33f1-5372-a312-752bc67074d2'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Comment calcule-t-on un coefficient multiplicateur ?', 'mcq', '["Valeur d’arrivée / valeur de départ","Valeur de départ − valeur d’arrivée","Valeur d’arrivée × 100","Valeur de départ / 100"]'::jsonb, 0, 'Un coefficient de 1,25 correspond à une hausse de 25 %.', 8),
    ('8d01602e-0c73-5f8c-85a3-d62aec001fe8'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Dans une réponse de connaissances, que faut-il faire en premier ?', 'mcq', '["Donner un exemple","Définir les notions du sujet","Conclure","Citer un document"]'::jsonb, 1, 'Les définitions montrent la maîtrise du vocabulaire du programme.', 9),
    ('e405b3c8-1795-5c5a-a072-ab27545d42a4'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Comment la spécialité STSS de première est-elle évaluée ?', 'mcq', '["Par l’épreuve écrite de terminale uniquement, sans rien en première","En contrôle continu en première, puis par l’épreuve écrite de terminale qui reprend les deux années","Par un oral en fin de première","Elle n’est pas évaluée"]'::jsonb, 1, 'Les notions de première sont aussi au programme de l’épreuve de terminale.', 10),
    ('6ade7ea4-5996-5b7f-b0de-66ede0b8b3c0'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Quelle formulation d’une donnée est correcte ?', 'mcq', '["« Il y a beaucoup de pauvres. »","« Selon l’INSEE, en 2023, environ 15 % de la population vit sous le seuil de pauvreté. »","« Les chiffres montrent des choses. »","« 15. »"]'::jsonb, 1, 'Une donnée bien citée a une source, une date, une unité et un champ.', 11),
    ('d5ba5d25-070e-5784-b902-90f4e557c4a2'::uuid, '323db284-9541-5007-a3db-b688ea9963f9'::uuid, 'Quel est le coefficient de l’épreuve de STSS au bac ST2S ?', 'mcq', '["2","6","16","20"]'::jsonb, 2, 'C’est l’une des deux épreuves de spécialité, au coefficient 16 chacune.', 12),
    ('287b7a97-dcb4-54f7-aba4-0c7a6ad08b0b'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Quelle loi a créé les agences régionales de santé ?', 'mcq', '["La loi HPST de 2009","La loi Kouchner de 2002","La loi Évin de 1991","Les ordonnances de 1945"]'::jsonb, 0, 'La loi « hôpital, patients, santé, territoires » les a créées ; elles sont installées depuis 2010.', 1),
    ('2cfab0b7-a7c1-5afd-b544-ebd3ea744c9f'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Quel courant du XIXe siècle a lutté contre les épidémies par l’eau potable, les égouts et la vaccination ?', 'mcq', '["Le libéralisme","L’hygiénisme","Le taylorisme","Le mutualisme"]'::jsonb, 1, 'L’hygiénisme répondait aux maladies infectieuses liées à l’insalubrité.', 2),
    ('1c1a0ded-edeb-5a17-9185-ba914c4633f6'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Depuis les ordonnances Juppé de 1996, le Parlement vote chaque année :', 'mcq', '["Le budget des hôpitaux privés","Le numerus clausus","La loi de financement de la Sécurité sociale et l’ONDAM","La liste des maladies à déclaration obligatoire"]'::jsonb, 2, 'L’ONDAM fixe l’objectif national de dépenses d’assurance maladie.', 3),
    ('c7e69d93-5102-5e58-b533-c93acbe9154b'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Qu’appelle-t-on la transition épidémiologique ?', 'mcq', '["La hausse du nombre de médecins","La fermeture des hôpitaux","L’apparition de la Sécurité sociale","Le passage d’une prédominance des maladies infectieuses à celle des maladies chroniques"]'::jsonb, 3, 'Elle explique le recentrage des politiques sur la prévention et le suivi au long cours.', 4),
    ('d2e0c8b7-44ee-5ae6-b2ab-c6719fb3c73e'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'La loi du 4 mars 2002 porte principalement sur :', 'mcq', '["Les droits des malades et la démocratie sanitaire","Le tabac","Le financement des hôpitaux","La vaccination obligatoire"]'::jsonb, 0, 'Elle est souvent appelée loi Kouchner.', 5),
    ('be626c16-7cb9-5f0a-9c29-b6813a18f754'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Quelle loi de 2016 a créé Santé publique France et les groupements hospitaliers de territoire ?', 'mcq', '["La loi HPST","La loi de modernisation de notre système de santé","La loi Évin","La loi Veil"]'::jsonb, 1, 'Elle a aussi instauré la stratégie nationale de santé et le paquet neutre du tabac.', 6),
    ('090c6464-3582-5ebb-95a1-1e215a6e389c'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Une politique de santé se limite à l’organisation des soins hospitaliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle inclut la prévention, l’éducation pour la santé, l’environnement et la coordination des acteurs.', 7),
    ('35c72eac-e135-5723-9af0-636966866b68'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Quelle loi de 1902 a rendu obligatoire la vaccination contre la variole ?', 'mcq', '["La loi Évin","La loi hospitalière","La loi relative à la protection de la santé publique","La loi HPST"]'::jsonb, 2, 'C’est la première grande loi de santé publique française.', 8),
    ('64bca025-c2e1-5b72-a39a-983741a7c964'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Dans les années 1980-1990, la politique de santé s’est surtout préoccupée :', 'mcq', '["De construire les premiers hôpitaux","De lutter contre la peste","De supprimer la Sécurité sociale","De maîtriser la hausse des dépenses"]'::jsonb, 3, 'Budgets, planification et ONDAM datent de cette période.', 9),
    ('156aeef1-1a3f-5b9d-9dd2-e9c580073453'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Que signifie « décloisonner » le système de santé ?', 'mcq', '["Relier la ville, l’hôpital et le médico-social autour du parcours du patient","Supprimer les hôpitaux","Séparer strictement les professions","Privatiser les soins"]'::jsonb, 0, 'Le patient atteint de maladie chronique passe d’un acteur à l’autre : il faut les coordonner.', 10),
    ('71fe21e1-926c-502c-a4ba-528953a7910a'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'Quelle mesure de la loi de 2019 concerne la formation des médecins ?', 'mcq', '["La création du médecin traitant","La fin du numerus clausus","La création des CHU","L’interdiction de fumer"]'::jsonb, 1, 'Le numerus clausus, instauré en 1971, limitait le nombre d’étudiants admis en deuxième année.', 11),
    ('c91d08f9-a6e6-57ba-8bc4-c09d0f3f94ce'::uuid, 'e74c3833-7a7f-5727-b459-9db6670b7af9'::uuid, 'La loi Évin de 1991 vise principalement :', 'mcq', '["Les droits des patients","La vaccination","Le tabac et l’alcool","La tarification hospitalière"]'::jsonb, 2, 'Elle encadre la publicité pour l’alcool et le tabac et interdisait déjà de fumer dans les lieux collectifs.', 12),
    ('e3dcd31a-d474-5a39-b92a-be51f45649e8'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Quel organisme élabore le projet régional de santé ?', 'mcq', '["Le conseil départemental","L’agence régionale de santé","L’OMS","La caisse d’allocations familiales"]'::jsonb, 1, 'L’ARS décline la politique nationale dans sa région.', 1),
    ('10505c8b-d4dd-5680-8b01-b284452492c2'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Quelle est la différence entre un règlement et une directive européens ?', 'mcq', '["Aucune","La directive s’applique directement, le règlement doit être transposé","Le règlement s’applique directement, la directive doit être transposée en droit national","Seule la directive est obligatoire"]'::jsonb, 2, 'Le règlement vaut loi dans tous les États membres dès son entrée en vigueur.', 2),
    ('b30f83bc-ecb7-51de-bb98-cf16a4cbf45f'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Que comprend le projet régional de santé ?', 'mcq', '["Le seul budget des hôpitaux","La liste des médecins de la région","Le calendrier vaccinal","Un cadre d’orientation stratégique, un schéma régional de santé et un PRAPS"]'::jsonb, 3, 'Le PRAPS vise l’accès à la prévention et aux soins des plus démunis.', 3),
    ('bcdce58e-014e-575d-a977-b0902d4c3c41'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Quel outil adapte les priorités de santé aux besoins d’une commune ou d’une intercommunalité ?', 'mcq', '["Le contrat local de santé","Le Règlement sanitaire international","La loi de financement de la Sécurité sociale","La carte Vitale"]'::jsonb, 0, 'Il est signé entre l’ARS et la collectivité.', 4),
    ('c5ab2d2f-27c0-5ac1-b498-89d461408f00'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'L’OMS a été créée en :', 'mcq', '["1902","1945","1948","1996"]'::jsonb, 2, 'Son siège est à Genève ; elle compte presque tous les États du monde.', 5),
    ('e6e5bda9-106c-5871-92c4-c60bd11297ed'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Le besoin de santé est ce que la population exprime spontanément.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce que la population exprime est la demande ; le besoin est établi à partir de critères de santé.', 6),
    ('8b1d3994-07a9-5917-9f29-807a0ccaedcd'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Quelle agence européenne évalue les médicaments ?', 'mcq', '["L’ECDC","L’EMA","L’ANSM","La HAS"]'::jsonb, 1, 'L’Agence européenne des médicaments ; l’ECDC s’occupe de la prévention des maladies.', 7),
    ('2473b4f6-ef58-5f12-8621-a65205b8c8df'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Quelle loi a instauré la stratégie nationale de santé ?', 'mcq', '["La loi de 1902","La loi Évin","La loi de 2016 de modernisation de notre système de santé","La loi HPST"]'::jsonb, 2, 'La SNS fixe le cadre pluriannuel de la politique de santé.', 8),
    ('9fa92d13-eda3-5bd6-aa06-d8edda646cb0'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Dans l’organisation des soins, l’Union européenne a surtout une compétence :', 'mcq', '["Exclusive","Nulle","Supérieure à celle des États","D’appui"]'::jsonb, 3, 'Les États organisent et financent leurs systèmes de soins ; l’UE agit sur le médicament et les menaces transfrontalières.', 9),
    ('e527e717-b611-58c8-8fa9-2136d3572657'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Qui évalue les politiques de santé publique en France ?', 'mcq', '["Le Haut Conseil de la santé publique","La caisse d’allocations familiales","Le conseil de la vie sociale","L’OMS seule"]'::jsonb, 0, 'La Cour des comptes y contribue aussi.', 10),
    ('d2b33754-3722-596f-8cca-7f6b497a08e7'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Quelle est la première étape de l’élaboration d’une politique de santé ?', 'mcq', '["Le financement","Le constat, fondé sur des données","L’évaluation","La communication"]'::jsonb, 1, 'Les indicateurs révèlent les besoins et permettent de fixer des priorités.', 11),
    ('b7fcd14b-4e76-5914-aeda-c9b3387b959e'::uuid, '3818fbea-8134-5cd3-bcf5-9e23df59b6f9'::uuid, 'Quelle mesure relève de la politique de santé mentale récente ?', 'mcq', '["Le paquet neutre","La vaccination contre la variole","Le numéro national de prévention du suicide 3114","La carte sanitaire de 1970"]'::jsonb, 2, 'Il répond jour et nuit aux personnes en détresse et à leurs proches.', 12),
    ('cdf73ab0-1fe1-5ed6-bcac-bd5a2e94e033'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Qu’est-ce que la démocratie sanitaire ?', 'mcq', '["Le vote des médecins","L’élection du ministre de la santé","L’association de tous les acteurs, dont les usagers, aux décisions de santé","La gratuité des soins"]'::jsonb, 2, 'Elle combine droits individuels et participation collective.', 1),
    ('82d24c48-754b-5c40-b9cb-78ad395a544e'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Quelle instance donne son avis sur le projet régional de santé ?', 'mcq', '["La commission des usagers","Le conseil de la vie sociale","La caisse primaire","La conférence régionale de la santé et de l’autonomie"]'::jsonb, 3, 'La CRSA réunit usagers, professionnels, élus et financeurs.', 2),
    ('35ebdd5c-edbb-5fce-99d2-40541722bdce'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Dans un hôpital, qui examine les plaintes des patients ?', 'mcq', '["La commission des usagers","Le conseil territorial de santé","L’OMS","Le Parlement"]'::jsonb, 0, 'Elle propose des améliorations de la qualité et de l’accueil.', 3),
    ('c9216ed1-32e7-53a5-91c5-9c00f768630f'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Quelle loi a posé les droits des malades en 2002 ?', 'mcq', '["La loi Évin","La loi du 4 mars 2002","La loi HPST","La loi Leonetti"]'::jsonb, 1, 'Information, consentement, accès au dossier, personne de confiance…', 4),
    ('978e2b43-726e-5792-9549-8b6d60c598c8'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Quelle association fédère au niveau national les associations d’usagers du système de santé ?', 'mcq', '["Les Restos du cœur","La Croix-Rouge","France Assos Santé","L’Ordre des médecins"]'::jsonb, 2, 'Elle a été créée par la loi de 2016.', 5),
    ('2d3eecef-c70e-5fdd-8339-ef10800359d6'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Les avis des instances de démocratie sanitaire s’imposent toujours au ministre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles sont consultatives : c’est l’une de leurs limites.', 6),
    ('79a78313-e94d-53fa-93f3-666967df771b'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Quelle épidémie a fait émerger la mobilisation des associations de malades dans les années 1980 ?', 'mcq', '["La grippe","La tuberculose","La rougeole","Le sida"]'::jsonb, 3, 'Elles ont revendiqué information et participation aux décisions.', 7),
    ('0790fd92-9b07-5097-91e5-d65d6b374ecb'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Les directives anticipées permettent de :', 'mcq', '["Exprimer ses volontés sur sa fin de vie","Choisir son médecin traitant","Refuser la Sécurité sociale","Désigner un héritier"]'::jsonb, 0, 'Elles sont prévues par la loi Leonetti de 2005, renforcée en 2016.', 8),
    ('26c91516-e4a0-580c-b35b-170ac0112c1c'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Quel est un intérêt de la démocratie sanitaire ?', 'mcq', '["Réduire le nombre de soignants","Des décisions mieux adaptées et mieux acceptées","Supprimer les agences","Éviter tout débat"]'::jsonb, 1, 'Ceux qui vivent le système en connaissent les défaillances.', 9),
    ('3149211b-10cb-58a4-a6a9-29150a5bd074'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Pour siéger comme représentant des usagers, il faut être membre :', 'mcq', '["D’un parti politique","Du personnel de l’hôpital","D’une association agréée","D’une mutuelle"]'::jsonb, 2, 'Les associations agréées désignent des représentants formés.', 10),
    ('51c691a0-b94b-546e-a443-96794f77ad00'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Quelle instance nationale organise le débat public sur la politique de santé ?', 'mcq', '["La commission des usagers","La MDPH","Le CCAS","La Conférence nationale de santé"]'::jsonb, 3, 'Elle rend des avis au ministre.', 11),
    ('8ea5ce78-3726-5988-9fc3-121de3ec62e9'::uuid, 'a18684ca-bba4-5085-9dae-f82f39814fc2'::uuid, 'Le consentement libre et éclairé fait partie des droits collectifs des usagers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un droit individuel de chaque patient.', 12),
    ('3d3059db-fcad-5d8a-aaf1-296f677bd4eb'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Quelle différence y a-t-il entre système de santé et système de soins ?', 'mcq', '["Aucune","Le système de santé est une composante du système de soins","Le système de soins ne concerne que la prévention","Le système de soins est une composante du système de santé"]'::jsonb, 3, 'Le système de santé inclut aussi la prévention, la sécurité sanitaire, la recherche.', 1),
    ('0316e364-516b-513e-826a-9cddf49bd100'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Quelle agence surveille l’état de santé de la population et alerte les pouvoirs publics ?', 'mcq', '["Santé publique France","La HAS","L’Agence de la biomédecine","L’EFS"]'::jsonb, 0, 'Elle a été créée en 2016 par regroupement de plusieurs agences.', 2),
    ('9cdd2702-dd2d-5ce4-9827-026700b80bf8'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Quelle agence autorise et surveille les médicaments en France ?', 'mcq', '["L’Anses","L’ANSM","La CNAF","L’INCa"]'::jsonb, 1, 'Elle a remplacé l’Afssaps en 2012.', 3),
    ('fd4fe134-52ca-5a17-a918-379c1a1c4876'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Quelle institution certifie les établissements de santé et émet des recommandations de bonne pratique ?', 'mcq', '["Santé publique France","Le conseil départemental","La Haute Autorité de santé","La DREES"]'::jsonb, 2, 'La HAS est une autorité publique indépendante.', 4),
    ('f70996dc-1b4e-5f3b-a22d-0f6eb764a37f'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Combien y a-t-il d’agences régionales de santé ?', 'mcq', '["13","18","22","101"]'::jsonb, 1, '13 en métropole et 5 outre-mer.', 5),
    ('2e9c4ed5-0e65-5dc0-a960-cfe4f2545ada'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Quelle agence est compétente pour les greffes et les dons d’organes ?', 'mcq', '["L’ANSM","L’Anses","Santé publique France","L’Agence de la biomédecine"]'::jsonb, 3, 'Elle s’occupe aussi de procréation et de génétique.', 6),
    ('c6731382-01b7-55c3-9149-9fb35e223eb1'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Pourquoi dit-on que la gouvernance du système de santé est partagée ?', 'mcq', '["Parce que l’État, l’assurance maladie, les collectivités et les professionnels se partagent le pouvoir","Parce qu’un seul acteur décide","Parce que les patients votent le budget","Parce que l’OMS gère le système français"]'::jsonb, 0, 'Cela rend la coordination indispensable.', 7),
    ('bd1dd066-c67e-5ddc-8d8f-8d08c8b59d11'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'L’assurance maladie négocie avec les professionnels libéraux :', 'mcq', '["Leur diplôme","Des conventions qui fixent leurs tarifs","Leur lieu d’installation obligatoire","Leur temps de travail"]'::jsonb, 1, 'Ces conventions encadrent aussi certaines missions de prévention.', 8),
    ('328d6577-421a-5bd9-967c-0279752e47ed'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'On peut améliorer la santé d’une population sans passer par le système de soins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Eau potable, sécurité routière ou éducation agissent sur les déterminants de santé.', 9),
    ('55fedc6d-b436-5304-ba10-020f6249674f'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Quelle agence est chargée de la sécurité sanitaire de l’alimentation et de l’environnement ?', 'mcq', '["L’ANSM","L’EFS","L’Anses","La HAS"]'::jsonb, 2, 'Agence nationale de sécurité sanitaire de l’alimentation, de l’environnement et du travail.', 10),
    ('7de28362-9a35-504d-817c-145c5c9377b5'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Qui évalue le service médical rendu d’un médicament avant son remboursement ?', 'mcq', '["L’ANSM","L’INCa","L’Agence de la biomédecine","La HAS"]'::jsonb, 3, 'Cet avis conditionne le taux de remboursement.', 11),
    ('58e5f266-aea7-534f-9120-20e58932f9bc'::uuid, 'e6a2f704-c5fe-52b0-857a-0679888d145d'::uuid, 'Quelle direction du ministère prépare la politique de santé publique ?', 'mcq', '["La Direction générale de la santé","La Direction générale des finances publiques","La caisse d’allocations familiales","La préfecture de police"]'::jsonb, 0, 'La DGS coordonne aussi la réponse aux alertes sanitaires.', 12),
    ('60e19b94-0845-58c3-8086-5490d5cafa8b'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Que mesure la consommation de soins et de biens médicaux (CSBM) ?', 'mcq', '["La valeur des soins et biens médicaux consommés dans l’année","Le budget de l’État","Le nombre de médecins","Les cotisations sociales"]'::jsonb, 0, 'Soins hospitaliers, soins de ville, médicaments, transports et autres biens médicaux.', 1),
    ('6964fcad-53d5-5896-99f1-3d638f095969'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Quel financeur prend en charge la plus grande part de la CSBM ?', 'mcq', '["Les ménages","La Sécurité sociale","Les organismes complémentaires","L’État"]'::jsonb, 1, 'Environ 80 % de la CSBM.', 2),
    ('ce8d8550-2307-53ba-ba15-8ad39a861652'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Que signifie ONDAM ?', 'mcq', '["Office national des dépenses de l’assurance maladie","Organisation nationale des médecins","Objectif national de dépenses d’assurance maladie","Ordonnance nationale de diagnostic médical"]'::jsonb, 2, 'Il est voté chaque année dans la loi de financement de la Sécurité sociale.', 3),
    ('4fe395a0-40e3-58f9-bb5f-80dcf92dc92f'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Quel indicateur sert aux comparaisons internationales de dépenses de santé ?', 'mcq', '["La CSBM","L’ONDAM","Le reste à charge","La DCSi"]'::jsonb, 3, 'La dépense courante de santé au sens international.', 4),
    ('3a97526a-eebf-5e68-b5d2-65541f5046d7'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Quel poste représente près de la moitié de la CSBM ?', 'mcq', '["Les soins hospitaliers","Les médicaments","Les transports sanitaires","L’optique"]'::jsonb, 0, 'L’hôpital est le premier poste de dépense.', 5),
    ('c2fce5f3-5445-5755-be5f-91e16db349e3'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Quelle ressource de l’assurance maladie est prélevée sur presque tous les revenus ?', 'mcq', '["La TVA","La CSG","Le forfait journalier","L’impôt sur les sociétés"]'::jsonb, 1, 'La contribution sociale généralisée existe depuis 1991.', 6),
    ('0a6d1eea-1f53-5dcd-995e-79a0921c7ec7'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Depuis 2004, les hôpitaux sont financés en grande partie :', 'mcq', '["Par un budget global fixe","Par les patients seuls","Selon leur activité (T2A)","Par l’OMS"]'::jsonb, 2, 'La tarification à l’activité est complétée par des dotations.', 7),
    ('c893df45-90b7-549f-8ef4-4666db2e7dbb'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Le reste à charge des ménages en France est l’un des plus faibles des pays riches.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il représente environ 7 à 8 % de la CSBM.', 8),
    ('421ac3dc-5507-59df-942e-8d3120f45e94'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Lequel N’EST PAS une participation du patient ?', 'mcq', '["Le ticket modérateur","La franchise médicale","Le forfait journalier hospitalier","La tarification à l’activité"]'::jsonb, 3, 'La T2A est un mode de financement des hôpitaux.', 9),
    ('5a88a228-dd54-513f-ae89-ad6a5e2f9316'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Qui publie chaque année les comptes de la santé ?', 'mcq', '["La DREES","L’INSEE seul","L’OMS","La CAF"]'::jsonb, 0, 'C’est le service statistique des ministères sanitaires et sociaux.', 10),
    ('6b5e8b33-cd71-573a-9f85-8b8d56e7067c'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Quel facteur explique la hausse des dépenses de santé ?', 'mcq', '["La baisse du nombre de personnes âgées","Le vieillissement et les maladies chroniques","La disparition des médicaments","La fin des progrès techniques"]'::jsonb, 1, 'Le progrès technique et la demande de soins y contribuent aussi.', 11),
    ('deb4b3ae-7ffe-5892-9770-0eb61d2d5fc4'::uuid, '32262dd6-8a2b-5d6d-a8b4-cbbfd8654af8'::uuid, 'Dépenses de santé et dépenses de l’assurance maladie désignent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les dépenses de santé incluent aussi ce que paient les complémentaires et les ménages.', 12),
    ('c6c8d4a3-d2b8-59ce-9a41-6da77376b823'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Qu’est-ce que la veille sanitaire ?', 'mcq', '["Le travail de nuit des soignants","La collecte et l’analyse continues de données pour détecter les menaces pour la santé","La vaccination obligatoire","Le remboursement des soins"]'::jsonb, 1, 'Elle vise une détection précoce pour alerter.', 1),
    ('2d4066bb-2f0b-54b5-bc99-bbeea90f8e30'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'À qui le médecin signale-t-il d’abord une maladie à déclaration obligatoire ?', 'mcq', '["À la mairie","À l’OMS","À l’agence régionale de santé","À la CAF"]'::jsonb, 2, 'Puis il notifie de façon anonymisée à Santé publique France.', 2),
    ('5d154d77-1c87-553d-bcc1-d2e0aabdc913'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Quelle vigilance surveille les effets indésirables des médicaments ?', 'mcq', '["L’hémovigilance","La matériovigilance","La toxicovigilance","La pharmacovigilance"]'::jsonb, 3, 'Elle est pilotée par l’ANSM avec des centres régionaux.', 3),
    ('2f5e6692-a635-58b0-8f5a-8d5a5ce76f6e'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Quelle vigilance concerne les transfusions sanguines ?', 'mcq', '["L’hémovigilance","La pharmacovigilance","L’addictovigilance","La nutrivigilance"]'::jsonb, 0, 'Du donneur au receveur, chaque produit sanguin est tracé.', 4),
    ('533bb5fb-6641-596f-91f8-a07a9577c4c0'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Le principe de précaution consiste à :', 'mcq', '["Attendre une preuve certaine avant d’agir","Agir face à un risque grave même sans certitude scientifique","Supprimer tout risque","Informer seulement les médecins"]'::jsonb, 1, 'Il est inscrit dans la Charte de l’environnement de 2005.', 5),
    ('a4b56914-0c7a-5e0f-876c-86cc772bfd9a'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Quel réseau de médecins généralistes surveille notamment les syndromes grippaux ?', 'mcq', '["Le réseau des CCAS","La réserve sanitaire","Le réseau Sentinelles","Les conseils territoriaux de santé"]'::jsonb, 2, 'Il estime chaque semaine l’activité de plusieurs maladies.', 6),
    ('8486e103-bed4-5aef-b7d1-6ced7d0c2959'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Quel texte international encadre la coopération mondiale face aux menaces sanitaires ?', 'mcq', '["La charte d’Ottawa","La loi Évin","Le traité de Rome","Le Règlement sanitaire international"]'::jsonb, 3, 'Il est appliqué sous l’égide de l’OMS.', 7),
    ('80d0f6f7-0c1f-5b47-a45e-aafee11cad0f'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'La veille sanitaire agit directement sur les causes des maladies.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle détecte et alerte ; la prévention agit ensuite sur les causes.', 8),
    ('e4387afe-a5e4-54f0-ae33-501cbb2b3b35'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Quelle agence gère la réserve sanitaire ?', 'mcq', '["Santé publique France","La HAS","L’EFS","L’Anses"]'::jsonb, 0, 'Des professionnels volontaires mobilisables en cas de crise.', 9),
    ('fe986a17-1004-596c-95a0-9e4e32bfaa73'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Un citoyen peut-il déclarer un effet indésirable d’un médicament ?', 'mcq', '["Non, seuls les médecins le peuvent","Oui, sur le portail de signalement des événements sanitaires indésirables","Seulement par courrier au ministre","Seulement à l’étranger"]'::jsonb, 1, 'Patients et associations peuvent déclarer directement.', 10),
    ('b7e4c9c1-35db-5fec-9ca5-181d52bd0b86'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Dans quel ordre se déroule la réponse à une menace sanitaire ?', 'mcq', '["Alerte → signal → vérification","Réponse → signal → alerte","Signal → vérification → évaluation → alerte → réponse","Évaluation → réponse → signal"]'::jsonb, 2, 'On vérifie un signal avant d’alerter et d’agir.', 11),
    ('c421ec49-fa28-53de-b10b-6d88b88866ab'::uuid, 'fda120b4-f84b-58b7-bb86-4c80a221150a'::uuid, 'Quel outil récent permet de suivre la circulation d’un virus dans une ville sans tester les habitants ?', 'mcq', '["Le recensement","La carte Vitale","Le contrat local de santé","L’analyse des eaux usées"]'::jsonb, 3, 'Elle a été développée pendant l’épidémie de Covid-19.', 12),
    ('03f86e00-0176-5e8f-bc03-12cc7520a2f1'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Quelles sont les trois missions d’un CHU ?', 'mcq', '["Soins, publicité, commerce","Prévention, police, justice","Soins, enseignement, recherche","Hébergement, restauration, loisirs"]'::jsonb, 2, 'Il est lié à une faculté de médecine.', 1),
    ('43753c8c-c33b-55f6-90e1-d97cf6033cd8'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Que regroupe une communauté professionnelle territoriale de santé (CPTS) ?', 'mcq', '["Des hôpitaux d’une même région","Les caisses d’assurance maladie","Les associations d’usagers","Les professionnels de santé d’un territoire autour d’un projet commun"]'::jsonb, 3, 'Créées en 2016, elles améliorent l’accès aux soins et la coordination.', 2),
    ('2b802c63-bb92-5c74-816b-1f7bf67b1808'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Un établissement de santé privé d’intérêt collectif (ESPIC) est :', 'mcq', '["Privé à but non lucratif","Privé à but lucratif","Public","Une maison de santé"]'::jsonb, 0, 'Il participe au service public hospitalier.', 3),
    ('377b8225-604a-5c90-ad9b-dcecfdaae681'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Que sont les groupements hospitaliers de territoire (GHT) ?', 'mcq', '["Des cliniques privées","Des regroupements d’hôpitaux publics autour d’un projet médical partagé","Des maisons de retraite","Des centres de vaccination"]'::jsonb, 1, 'Ils existent depuis la loi de 2016.', 4),
    ('6bd9f45a-21fc-5c1f-b2be-ea8037b32cb8'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Quel professionnel relève du premier recours ?', 'mcq', '["Le chirurgien cardiaque d’un CHU","Le centre de référence des maladies rares","Le médecin traitant","Le service de réanimation"]'::jsonb, 2, 'Le premier recours est la porte d’entrée dans le système de soins.', 5),
    ('40b56a68-b46a-5a72-afc4-4a7485f77970'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Dans un centre de santé, les médecins sont en général :', 'mcq', '["Libéraux payés à l’acte","Bénévoles","Fonctionnaires de l’OMS","Salariés"]'::jsonb, 3, 'C’est une différence avec la maison de santé, où exercent des libéraux.', 6),
    ('9f503f75-11b9-5876-8eaa-83941d7d9d2b'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Les déserts médicaux ne concernent que les zones rurales.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Certains quartiers urbains et certaines spécialités sont aussi touchés.', 7),
    ('a2954982-c57d-5d0b-9e93-157e6f75955e'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Un EHPAD relève :', 'mcq', '["Du secteur médico-social","Des soins de ville","Du troisième recours","De la médecine du travail"]'::jsonb, 0, 'Il accueille des personnes âgées dépendantes.', 8),
    ('8f9521d8-e5c3-54a9-871a-189427b537e3'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Que signifie la complémentarité des acteurs du système de soins ?', 'mcq', '["Tous font la même chose","Chacun intervient au bon niveau, en lien avec les autres","L’hôpital remplace la médecine de ville","Le patient choisit toujours le CHU"]'::jsonb, 1, 'Elle permet la continuité et la pertinence des soins.', 9),
    ('90949de1-a7d5-5ac1-941e-05f54bfe867d'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Quelle loi a créé les hôpitaux de proximité ?', 'mcq', '["La loi de 1970","La loi de 2002","La loi de 2019","La loi de 1902"]'::jsonb, 2, 'Ils assurent le premier recours en lien avec la médecine de ville.', 10),
    ('1982fc6b-e0e5-5f79-8f1d-8a4bb1f0f1e8'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Lequel est un auxiliaire médical ?', 'mcq', '["Le pharmacien","Le chirurgien-dentiste","La sage-femme","L’infirmier"]'::jsonb, 3, 'Sages-femmes et chirurgiens-dentistes sont des professions médicales.', 11),
    ('c0b1b552-fbce-5edb-966f-4c2e68f2576d'::uuid, 'f59f2464-f9ce-5a7e-a9fb-e9205ef8a20b'::uuid, 'Qu’est-ce que l’offre de soins ?', 'mcq', '["L’ensemble des professionnels, établissements et services qui produisent des soins","Le recours exprimé par la population","Le budget de la Sécurité sociale","Les remboursements"]'::jsonb, 0, 'La demande est le recours exprimé par la population.', 12),
    ('c09c440d-1e71-5903-8f22-fd22446d74b7'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Qui coordonne le parcours de soins d’un assuré ?', 'mcq', '["Le pharmacien","L’infirmier scolaire","La CAF","Le médecin traitant"]'::jsonb, 3, 'Chaque assuré de 16 ans et plus le déclare à l’assurance maladie.', 1),
    ('d01949cf-be7b-58b9-afca-816c1b6d9f7b'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Que se passe-t-il pour un patient qui consulte hors du parcours de soins coordonnés ?', 'mcq', '["Il est moins bien remboursé","Il n’est pas soigné","Il paie une amende","Il perd sa carte Vitale"]'::jsonb, 0, 'Le remboursement passe de 70 % à 30 % du tarif de base.', 2),
    ('554eaf68-bb87-5bc2-abe0-b7d34f0b31de'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Lequel de ces spécialistes est en accès direct ?', 'mcq', '["Le cardiologue","Le gynécologue","Le dermatologue","Le rhumatologue"]'::jsonb, 1, 'Gynécologue, ophtalmologue, dentiste et psychiatre (jusqu’à 25 ans) sont en accès direct.', 3),
    ('202837ba-3641-52f9-9c15-156455ab86a8'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Qu’est-ce que la permanence des soins ?', 'mcq', '["L’hospitalisation de longue durée","Le travail de nuit des pharmaciens seulement","L’accès à un médecin aux heures de fermeture des cabinets","La vaccination permanente"]'::jsonb, 2, 'Nuits, week-ends et jours fériés.', 4),
    ('f582e62f-d2eb-5009-b89a-02619eee1c8c'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Quel numéro permet la régulation médicale ?', 'mcq', '["Le 17","Le 18 seulement","Le 3114","Le 15"]'::jsonb, 3, 'Le SAMU oriente vers la réponse adaptée ; le 116 117 existe aussi pour la permanence des soins.', 5),
    ('e2be3fda-e627-56e3-b955-bc6040533330'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Que contient Mon espace santé ?', 'mcq', '["Le dossier médical partagé et une messagerie sécurisée","Le compte bancaire","Le bulletin scolaire","Le dossier de retraite"]'::jsonb, 0, 'Il a été ouvert à tous en 2022.', 6),
    ('7ab5066d-908d-5993-ae2a-31135a46e30c'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Le parcours de santé est plus large que le parcours de soins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il inclut la prévention et le médico-social.', 7),
    ('b312f90e-d604-5901-90aa-4a67876b1343'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'À quoi sert l’éducation thérapeutique du patient ?', 'mcq', '["À former les médecins","À rendre le malade chronique autonome dans la gestion de sa maladie","À remplacer les médicaments","À choisir une mutuelle"]'::jsonb, 1, 'Elle améliore le suivi du traitement et la qualité de vie.', 8),
    ('d0e17dac-49fa-51e6-9d57-3c15e5b8f3b0'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'La permanence des soins est destinée avant tout aux urgences vitales.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle répond aux besoins de soins non programmés ; l’urgence vitale relève du SAMU et des urgences.', 9),
    ('b65dd4c9-15a8-5eba-8bd7-dd76d0b1a0ec'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Quel dispositif associe SAMU et médecins libéraux pour les soins non programmés ?', 'mcq', '["La commission des usagers","Le PRAPS","Le service d’accès aux soins","La CPAM"]'::jsonb, 2, 'Il évite des passages inutiles aux urgences.', 10),
    ('59b48ae1-c95b-5200-867b-7a035ec06847'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Pourquoi a-t-on développé la notion de parcours ?', 'mcq', '["Pour supprimer les hôpitaux","Pour réduire le nombre de médecins","Pour interdire l’accès direct","Parce que les patients chroniques voient de nombreux professionnels pendant longtemps"]'::jsonb, 3, 'Il faut coordonner une trajectoire au long cours.', 11),
    ('e0a811bf-6c9c-557b-9bce-6e157c64670d'::uuid, '4d2ea4bb-78dd-56d4-b3f2-12d9c5d90ae9'::uuid, 'Quelle loi a créé le médecin traitant ?', 'mcq', '["La loi du 13 août 2004","La loi Évin","La loi de 1945","La loi HPST"]'::jsonb, 0, 'Le dispositif est entré en vigueur en 2005.', 12),
    ('96e3a196-8f49-54af-9009-c119afdc5844'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Qu’est-ce que la complémentaire santé solidaire (C2S) ?', 'mcq', '["Une complémentaire gratuite ou à moins d’un euro par jour pour les personnes aux ressources modestes","Une mutuelle réservée aux fonctionnaires","Une aide au logement","Une assurance obligatoire pour les étudiants"]'::jsonb, 0, 'Elle existe depuis 2019.', 1),
    ('d2399620-d5cf-56f4-9d70-6f3ab2ceeae4'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'À qui s’adresse l’aide médicale de l’État ?', 'mcq', '["À tous les retraités","Aux étrangers en situation irrégulière résidant en France depuis plus de trois mois, sous condition de ressources","Aux fonctionnaires","Aux enfants de moins de 6 ans"]'::jsonb, 1, 'Elle est financée par l’État.', 2),
    ('3b0236c0-62f1-58ef-9d8a-2a98049dbed2'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Que garantit la protection universelle maladie (PUMa) ?', 'mcq', '["Un revenu minimum","Une place en EHPAD","La prise en charge des frais de santé de toute personne qui travaille ou réside en France de façon stable et régulière","La gratuité totale des soins"]'::jsonb, 2, 'Elle a remplacé la CMU de base en 2016.', 3),
    ('2a2d8a11-bef0-5ce3-8aab-8da5e64ba823'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Où trouve-t-on les permanences d’accès aux soins de santé (PASS) ?', 'mcq', '["À la mairie","À la CAF","À l’école","À l’hôpital"]'::jsonb, 3, 'Elles soignent et aident à ouvrir les droits.', 4),
    ('f9df96f7-9e75-5209-a995-5c223f3935c1'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Quel obstacle à l’accès aux soins est géographique ?', 'mcq', '["Les déserts médicaux","Le reste à charge","La barrière de la langue","Le non-recours"]'::jsonb, 0, 'L’offre de soins est inégalement répartie.', 5),
    ('631bca94-1785-5b8f-9a2a-70bd3626d75c'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Qu’est-ce que le non-recours ?', 'mcq', '["Le refus de soigner","Le fait de ne pas utiliser un droit auquel on est éligible","L’absence d’hôpital","Le refus d’une mutuelle"]'::jsonb, 1, 'Méconnaissance, complexité ou crainte de stigmatisation l’expliquent.', 6),
    ('67a8f222-a670-5923-8bc2-5c376b93835e'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Le dispositif 100 % santé concerne :', 'mcq', '["Les consultations de généraliste","Les hospitalisations","Les lunettes, les prothèses dentaires et les aides auditives","Les médicaments contre le cancer"]'::jsonb, 2, 'Une sélection d’équipements est sans reste à charge.', 7),
    ('8ce1b440-33cd-571b-8831-8b457083fd7c'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Les soins liés à une affection de longue durée sont pris en charge à 100 % du tarif de base.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le cas du diabète ou du cancer, par exemple.', 8),
    ('a03f0407-1e25-5aaa-b059-c9b17c1f0266'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Que désigne l’universalisme proportionné ?', 'mcq', '["Agir seulement pour les plus pauvres","Donner la même chose à tous","Supprimer les aides","Agir pour tous avec une intensité croissante selon le désavantage"]'::jsonb, 3, 'C’est la réponse au gradient social de santé.', 9),
    ('31e531c3-ee9a-5e47-bf48-54545551697c'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Depuis 2016, les employeurs du privé doivent :', 'mcq', '["Proposer une complémentaire santé collective et en financer au moins la moitié","Soigner leurs salariés","Payer le reste à charge","Choisir le médecin traitant"]'::jsonb, 0, 'C’est la généralisation de la complémentaire d’entreprise.', 10),
    ('9ff5c90b-5016-59df-a2d7-1bc0a58675fe'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Quelle mesure agit sur la répartition de l’offre de soins ?', 'mcq', '["La hausse du ticket modérateur","Les aides à l’installation en zone sous-dense","La suppression du tiers payant","La fermeture des centres de santé"]'::jsonb, 1, 'Maisons de santé et téléconsultation y contribuent aussi.', 11),
    ('551df9cf-051a-54db-8fdb-9a9be2e52c98'::uuid, '1ba4f8d2-ac24-515b-b1fa-9a0fc4de0073'::uuid, 'Le tiers payant permet au patient :', 'mcq', '["De choisir son hôpital","D’obtenir un arrêt de travail","De ne pas avancer les frais","De ne pas déclarer de médecin traitant"]'::jsonb, 2, 'Le professionnel est payé directement par l’assurance maladie et la complémentaire.', 12),
    ('6340eea5-bedd-5422-a67e-a649fb3befba'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Le dépistage organisé du cancer du sein concerne :', 'mcq', '["Les femmes de 25 à 65 ans","Les femmes de 50 à 74 ans","Toutes les femmes dès 18 ans","Les hommes et les femmes de 50 à 74 ans"]'::jsonb, 1, 'Une mammographie est proposée tous les deux ans.', 1),
    ('399b7fa8-7c01-596c-b9c4-b3e3468bff15'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Un dépistage organisé relève de quel type de prévention ?', 'mcq', '["Primaire","Tertiaire","Secondaire","Aucune"]'::jsonb, 2, 'Il détecte la maladie à un stade précoce.', 2),
    ('d9838ec4-67e4-59f9-b716-52e10b4318fa'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Quel test est utilisé pour le dépistage organisé du cancer colorectal ?', 'mcq', '["Une coloscopie pour tous","Une prise de sang","Une radiographie","Un test immunologique de recherche de sang dans les selles"]'::jsonb, 3, 'Il est proposé tous les deux ans de 50 à 74 ans.', 3),
    ('18cb0852-9648-5e05-a2b4-30a8f1c336fd'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Mois sans tabac a lieu chaque année en :', 'mcq', '["Novembre","Janvier","Mai","Juillet"]'::jsonb, 0, 'Depuis 2016, les fumeurs sont invités à arrêter ensemble pendant trente jours.', 4),
    ('38fac2cb-66f6-5ffd-b956-b9bba79619dc'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Mois sans tabac est une action de prévention :', 'mcq', '["Secondaire","Primaire","Tertiaire","Palliative"]'::jsonb, 1, 'Elle agit sur un facteur de risque avant l’apparition de la maladie.', 5),
    ('f491c0ec-3235-5d9f-8f61-a7cb77b7d09b'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Pourquoi vaccine-t-on contre les HPV directement dans les collèges ?', 'mcq', '["Parce que c’est obligatoire","Parce que les médecins refusent de vacciner","Pour aller vers le public et réduire les inégalités de couverture vaccinale","Pour vacciner les parents"]'::jsonb, 2, 'C’est une stratégie d’« aller vers ».', 6),
    ('ebf6d7e1-9955-5835-bfc3-541889c569c4'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Le taux de participation à un dépistage est un indicateur de :', 'mcq', '["Moyens","Résultats sur la mortalité","Financement","Processus"]'::jsonb, 3, 'Il mesure la façon dont l’action touche son public.', 7),
    ('29d86c03-a6f9-5319-a856-8cb019e91588'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'La promotion de la santé agit sur l’environnement et donne aux personnes les moyens d’agir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’esprit de la charte d’Ottawa de 1986.', 8),
    ('3914f4fd-39c2-590c-b432-4373874197a5'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'À partir de 30 ans, le dépistage du cancer du col de l’utérus repose sur :', 'mcq', '["Un test HPV tous les cinq ans","Une mammographie","Une coloscopie","Une échographie annuelle"]'::jsonb, 0, 'Entre 25 et 29 ans, on réalise un examen cytologique.', 9),
    ('fb43fb6a-7da1-587d-8dd3-a5c5c501a64f'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Quel numéro correspond à Tabac info service ?', 'mcq', '["39 89","3114","115","119"]'::jsonb, 0, 'Des tabacologues y accompagnent l’arrêt.', 10),
    ('2d2c165d-40de-5c8c-9729-d85854c03b61'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Lequel est un indicateur de résultat d’une action contre le tabac ?', 'mcq', '["Le budget de la campagne","La baisse de la prévalence du tabagisme","Le nombre d’affiches imprimées","Le nombre de réunions"]'::jsonb, 1, 'Il mesure l’effet sur les comportements.', 11),
    ('6e50b981-bd66-5a51-a35e-2dcef471d3b0'::uuid, '59d5f0ae-bf8a-57c2-8d08-8792f1aad452'::uuid, 'Les bilans de prévention gratuits créés en 2024 sont proposés :', 'mcq', '["Chaque année à tous","Seulement aux enfants","À quatre âges clés de la vie","Seulement aux fumeurs"]'::jsonb, 2, '18-25, 45-50, 60-65 et 70-75 ans.', 12),
    ('b71fb152-4970-5270-983a-9e90c75d671f'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Qu’est-ce qu’une politique sociale ?', 'mcq', '["Une action humanitaire privée","Une politique de santé","L’ensemble des interventions publiques pour améliorer les conditions de vie et renforcer la cohésion sociale","Un programme électoral"]'::jsonb, 2, 'Elle couvre l’emploi, le logement, la famille, le handicap, la pauvreté…', 1),
    ('10acfea1-d5ce-51b0-8325-aa41bd5d4cf7'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Quelle institution de 1945 a fait de la protection un droit lié au travail ?', 'mcq', '["L’Hôpital général","Le RMI","La MDPH","La Sécurité sociale"]'::jsonb, 3, 'Elle repose sur la logique d’assurance et les cotisations.', 2),
    ('2a39062a-525f-5e58-8534-e3c7aac25802'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'En quelle année le RMI a-t-il été créé ?', 'mcq', '["1945","1975","1988","2009"]'::jsonb, 2, 'Il a été remplacé par le RSA en 2009.', 3),
    ('a26a60bb-9eb4-5a9a-ab41-86c4178d2d6b'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Quelle loi a rénové l’action sociale et médico-sociale en posant les droits des usagers des établissements ?', 'mcq', '["La loi du 2 janvier 2002","La loi du 11 février 2005","La loi de 1893","La loi HPST"]'::jsonb, 0, 'Livret d’accueil, charte, contrat de séjour, conseil de la vie sociale…', 4),
    ('4dfb1cda-2173-5772-a6b1-2362a0bd6e79'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Quelle loi a créé les maisons départementales des personnes handicapées ?', 'mcq', '["La loi de 1975","La loi du 11 février 2005","La loi de 1998","La loi de 1988"]'::jsonb, 1, 'Elle pose aussi le droit à compensation et l’accessibilité.', 5),
    ('ee8b3f4a-6208-5e60-9432-a861948142b4'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Que change le passage de l’assistance à l’aide sociale ?', 'mcq', '["L’aide devient une faveur","L’aide disparaît","L’aide devient un droit défini par la loi","L’aide est réservée aux salariés"]'::jsonb, 2, 'On peut la faire valoir, et contester un refus.', 6),
    ('2138b2c3-cbdb-5c79-b5ff-8a037fa6fe21'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Les lois de décentralisation de 1982 ont confié une grande part de l’aide sociale :', 'mcq', '["Aux communes seules","À l’Union européenne","Aux associations","Aux départements"]'::jsonb, 3, 'Le département est devenu le principal acteur de l’aide sociale.', 7),
    ('d58f0e15-0fa3-54dc-8d64-e112173bf862'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Depuis 2025, les allocataires du RSA sont inscrits et accompagnés par :', 'mcq', '["France Travail","La MDPH","La CNSA","L’hôpital"]'::jsonb, 0, 'France Travail a remplacé Pôle emploi le 1er janvier 2024.', 8),
    ('183a9903-dbac-5365-98e7-c91e60491eab'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'La logique de charité ouvre des droits que l’on peut faire valoir en justice.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est discrétionnaire : c’est l’aide sociale qui ouvre des droits.', 9),
    ('7f26ea7d-d4aa-5c28-bdc1-b7e3dfc0a928'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Quel organisme gère la branche autonomie depuis 2021 ?', 'mcq', '["La CNAF","La CNSA","La CNAM","L’URSSAF"]'::jsonb, 1, 'La Caisse nationale de solidarité pour l’autonomie.', 10),
    ('7db9d333-be68-578c-9c5c-a295de4094da'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Comment a évolué la place de l’usager dans les politiques sociales ?', 'mcq', '["D’acteur à simple assisté","Elle n’a pas changé","D’assisté à usager-acteur qui participe","Il a été exclu des décisions"]'::jsonb, 2, 'Contrats, projets personnalisés et instances de participation en témoignent.', 11),
    ('38dc9bbb-989d-5555-afd5-31d9e51313da'::uuid, '6ed66eab-4818-5748-adcc-56cb56cf1de6'::uuid, 'Quelle loi de 1998 porte sur la lutte contre les exclusions ?', 'mcq', '["La loi Évin","La loi de modernisation de 2016","La loi sur l’assistance médicale gratuite","La loi d’orientation relative à la lutte contre les exclusions"]'::jsonb, 3, 'Elle a notamment créé les PASS et renforcé l’accès aux droits.', 12),
    ('01ded700-5efc-5da1-aaff-0323f3931fac'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Qu’est-ce qu’une politique sociale catégorielle ?', 'mcq', '["Une politique pour tous","Une politique sans financement","Une politique européenne","Une politique qui vise un public particulier"]'::jsonb, 3, 'Par exemple la politique en faveur des personnes âgées.', 1),
    ('76be14cf-9b71-5225-97c9-87a21fa661c9'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Une aide sociale légale est :', 'mcq', '["Obligatoire et fixée par la loi","Décidée librement par chaque commune","Réservée aux associations","Toujours versée par l’Europe"]'::jsonb, 0, 'RSA, APA ou aide sociale à l’enfance en sont des exemples.', 2),
    ('fb8c4626-4868-594d-b2df-94c5e976fd70'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Que signifie le principe de subsidiarité de l’aide sociale ?', 'mcq', '["Elle est versée avant tout autre revenu","Elle intervient après les autres ressources, dont la solidarité familiale","Elle est réservée aux salariés","Elle ne peut jamais être récupérée"]'::jsonb, 1, 'L’obligation alimentaire familiale passe d’abord.', 3),
    ('3a81b855-5c6e-5c92-9b96-0d9efb9cc3cd'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Quel événement a fait de l’isolement des personnes âgées un problème public en 2003 ?', 'mcq', '["Une épidémie de grippe","Une crise financière","La canicule","Une grève"]'::jsonb, 2, 'Elle a provoqué environ 15 000 décès en excès.', 4),
    ('dc7110b9-2a07-5407-8b06-6ddf24b04060'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Une prestation sous condition de ressources est dite :', 'mcq', '["Universelle","Contributive","Facultative","Sélective"]'::jsonb, 3, 'Le RSA en est un exemple.', 5),
    ('203a0b6d-c884-5c97-a7d8-9b8a0a89c21b'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Quelle est la différence entre prestation en espèces et prestation en nature ?', 'mcq', '["L’une verse de l’argent, l’autre fournit un service ou un bien","Aucune","L’une est légale, l’autre facultative","L’une est européenne, l’autre nationale"]'::jsonb, 0, 'Une place d’hébergement est une prestation en nature.', 6),
    ('696969d2-bf28-5ec6-a73f-740430921586'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'La politique de la ville est une politique :', 'mcq', '["Catégorielle","Transversale","Assurantielle","Médicale"]'::jsonb, 1, 'Elle traite un ensemble de problèmes sur des quartiers prioritaires.', 7),
    ('b535c964-ce32-59ce-b35c-480faa19c1b1'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Un problème social existe dès qu’une situation difficile touche des personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut qu’elle soit perçue, portée et mise sur l’agenda.', 8),
    ('d26ecc00-eb55-574c-a71e-64aecc504c9c'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Le seuil de pauvreté monétaire en France est fixé à :', 'mcq', '["50 % du revenu moyen","100 % du SMIC","60 % du revenu médian","40 % du revenu médian"]'::jsonb, 2, 'Environ 15 % de la population vivait sous ce seuil en 2023.', 9),
    ('0a104a44-b2aa-5123-b85f-c01dfb8e9964'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Quel dispositif vise à soutenir l’autonomie des personnes âgées ?', 'mcq', '["Le RSA","L’allocation de rentrée scolaire","Le contrat d’engagement jeune","L’allocation personnalisée d’autonomie"]'::jsonb, 3, 'Elle est versée par le département.', 10),
    ('9c4224a7-2386-5014-97aa-0df952c145b7'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Qui peut contribuer à rendre visible une situation sociale ?', 'mcq', '["Les statistiques, les médias, les associations et les travailleurs sociaux","Seulement le Président","Personne","Seulement les tribunaux"]'::jsonb, 0, 'La visibilité est la première étape vers la mise sur l’agenda.', 11),
    ('531773b9-0317-5a3c-9c86-61c0e86c7c38'::uuid, 'c8d12fa7-c002-5a7e-be22-5fae2129710a'::uuid, 'Une aide facultative d’un CCAS relève d’une politique :', 'mcq', '["Légale et nationale","Décidée localement","Européenne","Assurantielle"]'::jsonb, 1, 'Chaque commune fixe ses aides facultatives.', 12),
    ('e63457e0-3f1c-5c8f-8570-6114c6fdfd9b'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Quel acteur est le chef de file de l’action sociale ?', 'mcq', '["Le département","L’État","La région","La commune"]'::jsonb, 0, 'La loi du 13 août 2004 lui a confié ce rôle.', 1),
    ('689b04d8-ff06-5c4d-82a9-1cafe755beb4'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Quelle est la différence entre aide sociale et action sociale ?', 'mcq', '["Aucune","L’action sociale est plus large : elle inclut accompagnement et prévention","L’aide sociale est plus large","L’aide sociale est facultative"]'::jsonb, 1, 'L’aide sociale désigne les prestations légales.', 2),
    ('af1719c7-f215-5a65-b7c0-518c338c30cf'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Qu’est-ce que le CCAS ?', 'mcq', '["Une caisse de Sécurité sociale","Un hôpital","Le centre communal d’action sociale","Une association privée"]'::jsonb, 2, 'Il gère les aides facultatives de la commune et réalise l’analyse des besoins sociaux.', 3),
    ('502d8156-68f8-5d31-a8a3-91e5d2d8ba86'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Qui verse le RSA à l’allocataire ?', 'mcq', '["Le département directement","La mairie","L’ARS","La CAF ou la MSA"]'::jsonb, 3, 'Le département finance et décide ; la CAF ou la MSA versent.', 4),
    ('7cd597a0-dd76-5982-99c6-7ed294f6424a'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Quel fonds européen finance des actions d’insertion ?', 'mcq', '["Le FSE+","La BCE","Le FMI","L’ONDAM"]'::jsonb, 0, 'Le Fonds social européen plus.', 5),
    ('1afc40ff-be63-5bc1-97d9-7a6b6b1def4f'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Laquelle de ces missions relève du département ?', 'mcq', '["La formation des travailleurs sociaux","L’aide sociale à l’enfance","L’hébergement d’urgence","La délivrance des passeports"]'::jsonb, 1, 'Il gère aussi la PMI, le RSA, l’APA et la PCH.', 6),
    ('dd2928bc-bb73-5551-8151-c336d172f8f7'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'La région est chargée :', 'mcq', '["Du RSA","De l’aide sociale à l’enfance","De la formation des travailleurs sociaux","Des CCAS"]'::jsonb, 2, 'Elle finance et organise les formations sociales.', 7),
    ('daf6878f-2608-594b-a961-92c6d5387a9f'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Les associations gèrent une grande partie des établissements sociaux et médico-sociaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles sont des partenaires essentiels des pouvoirs publics.', 8),
    ('a6d3aee9-3817-5364-8459-792d597e3ce5'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Quelle limite présente la décentralisation de l’action sociale ?', 'mcq', '["Des décisions trop éloignées du terrain","L’absence totale de financement","L’interdiction des associations","Des inégalités entre départements"]'::jsonb, 3, 'Ressources et choix diffèrent d’un département à l’autre.', 9),
    ('31363a37-8f8a-5e44-99b1-01bcbdb97af9'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Qui finance l’hébergement d’urgence ?', 'mcq', '["Principalement l’État","Uniquement les communes","Les mutuelles","L’OMS"]'::jsonb, 0, 'C’est une compétence de l’État.', 10),
    ('c876c0ad-92c2-5da6-b096-192b89e510e2'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Que désigne la contractualisation dans l’action sociale ?', 'mcq', '["Le contrat de travail des usagers","La signature de conventions et contrats entre financeurs et opérateurs","L’achat de médicaments","La fin des partenariats"]'::jsonb, 1, 'Conventions, contrats pluriannuels et appels à projets en sont les formes.', 11),
    ('442ef2bf-883a-55cf-8b00-b887fd84722f'::uuid, '96df5cad-3335-5c84-aca4-1d15a0e25b37'::uuid, 'Les CAF mènent aussi une action sociale, par exemple :', 'mcq', '["En délivrant des ordonnances","En gérant les hôpitaux","En finançant crèches et centres sociaux","En contrôlant les médicaments"]'::jsonb, 2, 'C’est l’action sociale de la branche famille.', 12),
    ('aab12ed5-d8b9-5a53-8e79-7ecf2266396f'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Quel organisme doit réaliser une analyse des besoins sociaux ?', 'mcq', '["L’ARS","Le CCAS","La CNSA","L’hôpital"]'::jsonb, 1, 'Dans l’année qui suit le renouvellement du conseil municipal.', 1),
    ('259ea523-728d-5457-9670-967d82c17bea'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Quelle est la première étape d’un diagnostic des besoins sociaux ?', 'mcq', '["Le financement","L’évaluation","Le recueil de données","La communication"]'::jsonb, 2, 'Données de l’INSEE, de la CAF, des services sociaux, enquêtes…', 2),
    ('654904af-7e5d-5535-b660-a75d6ea0fb18'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Quels sont les deux volets du RSA ?', 'mcq', '["Un logement et une voiture","Une bourse et une formation obligatoire","Une retraite et une mutuelle","Une allocation et un accompagnement vers l’insertion"]'::jsonb, 3, 'L’allocation complète les ressources ; l’accompagnement vise l’insertion.', 3),
    ('f70b250e-75ee-571b-b947-21a7574ba4b2'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'À quel numéro appelle-t-on pour un hébergement d’urgence ?', 'mcq', '["Le 115","Le 15","Le 119","Le 3114"]'::jsonb, 0, 'Il est géré par le SIAO du département.', 4),
    ('0ffd5114-a8dc-5089-863d-2737c242b879'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Que signifie SIAO ?', 'mcq', '["Système international d’aide aux orphelins","Service intégré d’accueil et d’orientation","Service d’insertion des adultes âgés","Syndicat des infirmiers et aides-soignants"]'::jsonb, 1, 'Une porte d’entrée unique pour orienter les personnes sans abri.', 5),
    ('51bad330-bd89-5527-9671-2a3d559b8047'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Quel est le principe du « Logement d’abord » ?', 'mcq', '["Passer par toutes les étapes d’hébergement avant un logement","Construire uniquement des centres d’hébergement","Proposer directement un logement accompagné","Supprimer l’accompagnement"]'::jsonb, 2, 'Le logement est le point de départ de l’insertion, non sa récompense.', 6),
    ('e289902c-ecb2-5352-a970-1e01a7ea31bb'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'La loi DALO de 2007 permet :', 'mcq', '["Un revenu minimum","Une place en crèche","Un emploi garanti","Un recours si l’on n’obtient pas de logement"]'::jsonb, 3, 'Droit au logement opposable.', 7),
    ('942cece4-a684-5d7e-876d-ea1fe19fa995'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Un diagnostic partagé associe habitants, associations et professionnels.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il prend en compte des points de vue différents sur les besoins.', 8),
    ('77b02166-d18e-5de7-b202-802a036be657'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Qu’est-ce que la domiciliation ?', 'mcq', '["Une adresse pour recevoir son courrier et accéder à ses droits","Un logement gratuit","Une aide au déménagement","Un contrat de location"]'::jsonb, 0, 'Sans adresse, de nombreux droits sont impossibles à ouvrir.', 9),
    ('91f75c83-5c59-56ef-b05d-f78b01af656b'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Depuis 2025, l’allocataire du RSA signe :', 'mcq', '["Un contrat de travail","Un contrat d’engagement avec un plan d’action","Un bail","Un contrat de mariage"]'::jsonb, 1, 'Il prévoit en principe au moins quinze heures d’activité par semaine, adaptées à sa situation.', 10),
    ('b1e0d965-56ba-5f8b-a480-7f9020854b91'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Quelle limite peut-on relever pour le SIAO ?', 'mcq', '["Il ne coordonne rien","Il est réservé aux salariés","Il oriente mais ne crée pas de places","Il est payant"]'::jsonb, 2, 'La pénurie de places et de logements bloque l’orientation.', 11),
    ('a3febf2f-ff82-52f4-9418-e73b37b396d8'::uuid, 'b0384aa8-2457-5a7d-b947-668d16181f66'::uuid, 'Un atelier cuisine à petit budget dans un centre social est une intervention :', 'mcq', '["Individuelle","Judiciaire","Hospitalière","Collective"]'::jsonb, 3, 'Elle réunit un groupe autour d’un objectif commun.', 12),
    ('dc46f90a-ffe8-5583-aeda-30facefed46e'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Quelles sont les quatre phases de la démarche de projet ?', 'mcq', '["Financement, publicité, vente, bilan","Diagnostic, soin, guérison, sortie","Étude, conception, mise en œuvre, évaluation","Idée, vote, loi, décret"]'::jsonb, 2, 'C’est l’ordre prévu par le programme.', 1),
    ('b0f440f3-ab57-51a3-b712-11ab34e4d397'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Sur quoi repose la phase d’étude ?', 'mcq', '["Sur le budget final","Sur la valorisation","Sur la communication","Sur le diagnostic de la situation et des besoins"]'::jsonb, 3, 'Elle permet de choisir une priorité fondée.', 2),
    ('31f2e19c-2fbb-5dd0-879f-eea3734d67ad'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Qu’est-ce qu’un indicateur ?', 'mcq', '["Une donnée qui mesure un critère","La qualité que l’on juge","Le chef de projet","Le financeur"]'::jsonb, 0, 'Par exemple le nombre de participants mesure la participation.', 3),
    ('41ef345c-2610-5a56-a083-c0ad53dc0920'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'L’efficience compare :', 'mcq', '["Les résultats et les besoins","Les résultats obtenus et les moyens utilisés","Les objectifs et le calendrier","Les partenaires entre eux"]'::jsonb, 1, 'Elle répond à la question : à quel coût ?', 4),
    ('b17f2b94-aae1-5b02-a2f8-985f2a59e476'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Quel objectif est opérationnel ?', 'mcq', '["Améliorer la santé des jeunes","Réduire l’isolement des aînés","Organiser deux ateliers par semaine au centre social d’ici juin","Promouvoir le bien-être"]'::jsonb, 2, 'Il est précis, mesurable et daté.', 5),
    ('369187bb-e497-5e06-bf3f-3426a71bfa83'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Qui valide les grandes étapes d’un projet ?', 'mcq', '["Le public seul","Le journaliste","Le fournisseur","Le comité de pilotage"]'::jsonb, 3, 'Il décide des orientations ; le comité technique met en œuvre.', 6),
    ('7a751683-2c03-5a23-82c7-d55aee794e8a'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'L’évaluation se prépare seulement à la fin du projet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les indicateurs se fixent dès la conception.', 7),
    ('b749eda1-f28e-5419-8038-9ec463b417bf'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Quel outil sert à planifier les actions dans le temps ?', 'mcq', '["Le diagramme de Gantt","L’antibiogramme","La pyramide des âges","Le caryotype"]'::jsonb, 0, 'Il visualise les tâches et leur durée.', 8),
    ('a974aa6c-f331-52b9-ab99-93373285909c'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Quelle est une spécificité d’un projet en santé-social ?', 'mcq', '["Il ignore la population cible","Il associe la population cible et respecte une éthique","Il n’a pas de cadre juridique","Il est toujours individuel"]'::jsonb, 1, 'Confidentialité, consentement et non-stigmatisation sont essentiels.', 9),
    ('aeda8f6e-7558-5ff2-a1bd-dc3e76137716'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Que signifie évaluer la pertinence d’un projet ?', 'mcq', '["Calculer son coût","Compter les réunions","Vérifier qu’il répond bien au besoin identifié","Vérifier l’orthographe du rapport"]'::jsonb, 2, 'Un projet efficace mais hors sujet n’est pas pertinent.', 10),
    ('13199027-f65e-56ed-9dbc-6b6805ad41ab'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Qu’appelle-t-on la valorisation d’un projet ?', 'mcq', '["Son financement initial","Sa suppression","Son diagnostic","La diffusion et le partage de ses résultats"]'::jsonb, 3, 'Elle permet aussi de décider de pérenniser l’action.', 11),
    ('846e7f87-a18c-5a0f-b757-265c650475c5'::uuid, 'e253e789-2c6b-51de-bd95-d8d56a57f9ee'::uuid, 'Laquelle est une contrainte fréquente d’un projet ?', 'mcq', '["Le budget limité","L’absence de besoins","L’interdiction d’évaluer","L’absence de public"]'::jsonb, 0, 'Temps, partenaires et cadre réglementaire en sont d’autres.', 12),
    ('1e3816c7-2a1a-58e4-a4f6-d12af4800600'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Combien de temps dure l’épreuve écrite de STSS ?', 'mcq', '["2 heures","4 heures","1 heure 30","3 heures"]'::jsonb, 3, 'Elle est notée sur 20 points.', 1),
    ('e4588567-510e-5934-88cb-747daa37defc'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Combien de points vaut la partie « mobilisation des connaissances » ?', 'mcq', '["4","6","10","14"]'::jsonb, 1, 'Elle comprend une ou deux questions sans document.', 2),
    ('2435a204-4ee3-5dfa-ab6f-7c830b543942'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Combien de documents au plus comporte le dossier de la seconde partie ?', 'mcq', '["Cinq","Trois","Huit","Dix"]'::jsonb, 0, 'Cinq documents sur cinq pages au plus.', 3),
    ('3fa8dd5a-247f-521e-8c20-549aa8dd7545'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Quel plan est à éviter dans la seconde partie ?', 'mcq', '["Un plan thématique","Un plan document par document","Un plan en deux parties","Un plan en trois parties"]'::jsonb, 1, 'Il faut classer les informations par idée.', 4),
    ('5ebdd83b-b046-51fb-915b-c20509f5b6fa'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Un taux passe de 12 % à 15 %. De combien a-t-il augmenté ?', 'mcq', '["3 %","15 points","3 points, soit une hausse de 25 %","12 %"]'::jsonb, 2, 'L’écart est de 3 points ; (15 − 12) ÷ 12 × 100 = 25 %.', 5),
    ('040bb0a3-56ce-5a9e-a217-d756e2b070de'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Comment calcule-t-on un taux de variation ?', 'mcq', '["(départ − arrivée) ÷ arrivée × 100","arrivée × départ","arrivée ÷ 100","(arrivée − départ) ÷ départ × 100"]'::jsonb, 3, 'On rapporte l’évolution à la valeur de départ.', 6),
    ('07e93db1-a472-5e5d-bcec-7f26e33e7e96'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Quelle règle suit un bon argument ?', 'mcq', '["Idée → preuve tirée d’un document → connaissance personnelle","Document → recopie → conclusion","Opinion → émotion → conclusion","Chiffre → chiffre → chiffre"]'::jsonb, 0, 'Les connaissances expliquent et complètent les documents.', 7),
    ('713a7ad3-e326-5766-86e7-0d8608325ff4'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Dans la première partie, il faut s’appuyer sur des documents fournis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est sans document : on mobilise ses connaissances.', 8),
    ('0cdef745-ab52-57a8-8420-c31ad107c7c4'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Que doit contenir l’introduction de la seconde partie ?', 'mcq', '["La conclusion","Le contexte, les définitions, la problématique et l’annonce du plan","La liste des documents recopiés","Une opinion personnelle"]'::jsonb, 1, 'Elle pose le cadre de la réponse.', 9),
    ('3da45986-0724-5897-8afe-4ec40dd2c8c3'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Quel est l’ordre conseillé pour traiter le dossier ?', 'mcq', '["Rédiger puis lire les documents","Conclure puis introduire","Analyser le sujet, lire les documents, construire un plan, rédiger","Lire uniquement le premier document"]'::jsonb, 2, 'La réflexion précède la rédaction.', 10),
    ('d803cdb1-5a90-5e61-95cf-17c9736507aa'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Une grandeur passe de 40 à 60. Quel est le coefficient multiplicateur ?', 'mcq', '["0,5","1,5","2","20"]'::jsonb, 1, '60 ÷ 40 = 1,5.', 11),
    ('966fb7de-02a3-53d1-acb4-60b133bd2717'::uuid, '35c5d8e0-55ad-503e-880b-49530a9eddf3'::uuid, 'Que doit faire la conclusion ?', 'mcq', '["Ouvrir sur un sujet sans rapport","Recopier l’introduction","Lister les documents","Répondre clairement à la question posée"]'::jsonb, 3, 'Une ouverture est possible, mais après la réponse.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('biologie-physiopathologie', 'chimie-biologie-physiopathologie', 'physique-chimie-sante', 'sciences-sanitaires-sociales', 'sciences-sanitaires-sociales');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('biologie-physiopathologie', 'chimie-biologie-physiopathologie', 'physique-chimie-sante', 'sciences-sanitaires-sociales', 'sciences-sanitaires-sociales')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 392 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 392 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
